V.gaps=()=>`<section class="p w12"><h2>Gaps against leading CRM and ERP suites</h2><p class="sub">What the order desk and staff office already do, and what this desk adds or still needs</p>
 ${table("tGap",[{t:"Area"},{t:"Before this desk"},{t:"Now"},{t:"Still needed"}],[
  ["Dashboards with drill-down","Order list only","Filters plus click-to-drill on sites, months, profit centres, stages and segments","Saved views per role"],
  ["Profit-centre P&amp;L","Not built","Revenue, margin, contribution, budget variance","Real cost allocation rules from finance"],
  ["Pipeline and forecast","Quote status only","Stages, weighted pipeline, commit / best case, coverage, ageing","Live deal entry screen"],
  ["Market intelligence","Separate pages","Share, relative share, lost and non-offered market, draft targets","Real market sizes from country files (restricted)"],
  ["Management outcomes","Not built","Scorecard in 4 perspectives with RAG and owner role","Targets agreed by owner"],
  ["Formulas visible","No","Every column shows its formula","-"],
  ["Data export","No","Copy or save any table as CSV; copy a whole tab","Scheduled export to shared drive"],
  ["Alerts","SLA timer only","9 rules per site and profit centre, limits you can change","Daily email digest (needs yes mail)"],
  ["Role-based access","Staff sign-in","Staff-only page, demo data","Per-role row filters"],
  ["Data from live orders","Demo orders","Demo facts","Nightly job from the order database"]].map(r=>r))}</section>`;

/* ---------- modules (bi-suite/modules/*.js, added by build.py) ---------- */
const BI={mods:[],add(m){this.mods.push(m);V[m.id]=m.render;if(m.formulas)Object.assign(FX,m.formulas);}};

/* module: board.js */
// Board pack tab: a one-page management summary written from the numbers. Respects every filter. Demo data only.
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const div = (a, b) => (fin(b) !== 0 ? fin(fin(a) / b) : 0);
  const GOAL = {sla: 0.90, dso: 45, win: 0.35, gmp: 0.40, varp: -0.05};
  let lastText = "";

  const decKey = () => "board.dec." + D.side + "." + D.sites.map(s => s.id).join("-");
  function decisions(){
    try { const v = JSON.parse(load(decKey()) || "[]"); return Array.isArray(v) ? v.filter(x => x && typeof x.t === "string") : []; }
    catch(e){ return []; }
  }
  function saveDecisions(list){ store(decKey(), JSON.stringify(list)); }

  function scopeText(ms){
    return (st.site === "all" ? "All sites on this side" : siteName(st.site)) + " · " +
      (st.pc === "all" ? "all profit centres" : st.pc) + " · " +
      (st.country === "all" ? "all countries" : st.country) + " · last " + ms.length + " months";
  }

  // Outcomes (same rule as the Management outcomes tab): average each measure over sites in view, status on the latest value.
  function outcomes(){
    const k = D.kpis.filter(x => st.site === "all" || x.site === st.site);
    const names = [...new Set(k.map(x => x.name))];
    return names.map(n => {
      const y = k.filter(z => z.name === n);
      const len = y[0].series.length;
      const ser = y[0].series.map((_, i) => fin(sum(y, z => z.series[i]) / y.length));
      const a = len ? ser[len - 1] : 0;
      const r = rag(a, y[0].target, y[0].better);
      const gap = y[0].better === "lower" ? div(a - y[0].target, y[0].target) : div(y[0].target - a, y[0].target);
      return {n, a, r, gap, target: y[0].target, unit: y[0].unit, owner: y[0].owner};
    });
  }
  const fmtK = (v, u) => u === "%" ? v.toFixed(1) + "%" : v.toFixed(u === "count" ? 0 : 1) + " " + u;

  function compute(){
    const ms = months();
    const F = facts(ms);
    const a = agg(F), p = agg(facts(prevMonths()));
    const days = ms.length * 30.4;
    // profit centres in view
    const units = [];
    D.sites.filter(s => st.site === "all" || s.id === st.site).forEach(s => s.pcs.filter(pc => st.pc === "all" || pc === st.pc).forEach(pc => {
      const r = D.facts.filter(f => f.site === s.id && f.pc === pc && ms.includes(f.m));
      if (r.length) units.push({s, pc, a: agg(r)});
    }));
    // pipeline (same probabilities and what-if as the Pipeline tab)
    const dl = deals(); const mult = st.prob / 100;
    const P = n => { const sg = D.stages.find(s => s.name === n); return Math.min(1, (sg ? sg.p : 0) * (n === "Won" ? 1 : mult)); };
    const open = dl.filter(d => !["Won", "Lost"].includes(d.stage));
    const wp = sum(open, d => d.amount * P(d.stage));
    const won = dl.filter(d => d.stage === "Won"), lost = dl.filter(d => d.stage === "Lost");
    const winRate = div(won.length, won.length + lost.length);
    const lastM = D.months[D.months.length - 1] || "2026-01";
    const yr = +lastM.slice(0, 4), qn = Math.floor((+lastM.slice(5, 7) - 1) / 3);
    const qMs = [1, 2, 3].map(i => yr + "-" + String(qn * 3 + i).padStart(2, "0"));
    const qLbl = "Q" + (qn + 1) + " " + yr;
    const inQ = dl.filter(d => qMs.includes(d.close));
    const commit = sum(inQ.filter(d => d.stage === "Won" || d.stage === "Negotiation"), d => d.amount);
    const best = commit + sum(inQ.filter(d => d.stage === "Proposal"), d => d.amount);
    const stale = open.filter(d => d.age > 90);
    // market
    const m = mkt();
    const size = sum(m, x => x.size), ours = sum(m, x => x.size * x.ours);
    const lostM = sum(m.filter(x => x.offered), x => x.size * (1 - x.ours)), nonM = sum(m.filter(x => !x.offered), x => x.size);
    const tgt = 0.10 * lostM + 0.05 * nonM;
    const tr = D.share_trend.filter(t => st.site === "all" || t.site === st.site);
    const qs = [...new Set(tr.map(t => t.q))].sort();
    const qAvg = q => { const x = tr.filter(t => t.q === q); return x.length ? fin(sum(x, t => t.ours) / x.length) : 0; };
    const shNow = qs.length ? qAvg(qs[qs.length - 1]) : 0, shPrev = qs.length > 1 ? qAvg(qs[qs.length - 2]) : shNow;
    const ot = outcomes(); const cnt = {g: 0, a: 0, r: 0}; ot.forEach(o => cnt[o.r]++);
    const ontime = F.length ? fin(sum(F, f => f.ontime) / F.length) : 0;
    return {ms, F, a, p, days, units, dl, open, wp, won, lost, winRate, qLbl, commit, best, stale, m, size, ours, share: div(ours, size),
      lostM, nonM, tgt, shNow, shPrev, qs, ot, cnt, ontime, P};
  }

  // Wins and concerns: each rule gives one line, scored by how far it is from its goal.
  function winsConcerns(c){
    const out = [];
    const a = c.a;
    const byVar = c.units.slice().sort((x, y) => y.a.var - x.a.var);
    const bestU = byVar[0], worstU = byVar[byVar.length - 1];
    const nm = u => (st.site === "all" ? u.s.name + " · " : "") + u.pc;
    if (bestU && bestU.a.var > 0)
      out.push({w: true, s: 5 + bestU.a.varp * 20, rule: "Biggest positive budget variance by profit centre", drill: "site:" + bestU.s.id + "|pc:" + bestU.pc + "|tab:profit",
        t: `${nm(bestU)} beat its budget by ${money(bestU.a.var)} (${pct(bestU.a.varp)}).`});
    if (worstU && worstU.a.var < 0)
      out.push({w: false, s: 5 - worstU.a.varp * 20, rule: "Biggest negative budget variance by profit centre", drill: "site:" + worstU.s.id + "|pc:" + worstU.pc + "|tab:profit",
        t: `${nm(worstU)} is ${money(-worstU.a.var)} (${pct(-worstU.a.varp)}) below budget.`});
    if (a.budget > 0) {
      out.push({w: a.var >= 0, s: Math.abs(a.varp) * 20, rule: "Total revenue against budget", drill: "tab:overview",
        t: a.var >= 0 ? `Total revenue is ${money(a.var)} (${pct(a.varp)}) ahead of budget.` : `Total revenue is ${money(-a.var)} (${pct(-a.varp)}) behind budget.`});
    }
    if (a.quotes > 0) {
      const g = div(a.sla - GOAL.sla, GOAL.sla);
      out.push({w: g >= 0, s: Math.abs(g) * 20, rule: "Quote speed: 30-minute goal of 90%", drill: "tab:overview",
        t: g >= 0 ? `Quotes are fast: ${pct(a.sla)} went out within 30 minutes (goal 90%).`
                  : `Quotes are slow: only ${pct(a.sla)} went out within 30 minutes (goal 90%); ${Math.max(0, a.quotes - a.q30)} quotes were late.`});
    }
    if (a.rev > 0) {
      const g = div(GOAL.dso - a.dso, GOAL.dso);
      out.push({w: g >= 0, s: Math.abs(g) * 20, rule: "Days sales outstanding: goal 45 days or less", drill: "tab:overview",
        t: g >= 0 ? `Customers pay in ${a.dso.toFixed(0)} days on average, inside the 45-day goal.`
                  : `Customers take ${a.dso.toFixed(0)} days to pay, ${(a.dso - GOAL.dso).toFixed(0)} days over the 45-day goal.`});
    }
    if (c.won.length + c.lost.length > 0) {
      const g = div(c.winRate - GOAL.win, GOAL.win);
      out.push({w: g >= 0, s: Math.abs(g) * 20, rule: "Win rate: goal 35%", drill: "tab:pipeline",
        t: `Win rate is ${pct(c.winRate)} (${c.won.length} won, ${c.lost.length} lost) against a 35% goal.`});
    }
    if (c.qs.length > 1) {
      const ch = c.shNow - c.shPrev;
      out.push({w: ch >= 0, s: Math.abs(div(ch, c.shPrev)) * 20, rule: "Market share change, last quarter", drill: "tab:market",
        t: `Market share ${ch >= 0 ? "rose" : "fell"} from ${pct(c.shPrev)} to ${pct(c.shNow)} last quarter (${ch >= 0 ? "+" : ""}${(ch * 100).toFixed(2)} pts).`});
    }
    if (a.rev > 0) {
      const g = div(a.gmp - GOAL.gmp, GOAL.gmp);
      out.push({w: g >= 0, s: Math.abs(g) * 10, rule: "Gross margin: goal 40%", drill: "tab:profit",
        t: `Gross margin is ${pct(a.gmp)} of revenue (goal 40%).`});
    }
    if (c.p.rev > 0 && a.rev > 0) {
      const g = div(a.rev - c.p.rev, c.p.rev);
      out.push({w: g >= 0, s: Math.abs(g) * 10, rule: "Revenue against the previous period", drill: "tab:overview",
        t: `Revenue is ${g >= 0 ? "up" : "down"} ${pct(Math.abs(g))} on the previous ${c.ms.length} months.`});
    }
    if (c.ot.length) {
      const g = div(c.cnt.g - c.cnt.r, c.ot.length);
      out.push({w: g >= 0, s: Math.abs(g) * 5, rule: "Outcomes on track against act now", drill: "tab:outcomes",
        t: `${c.cnt.g} of ${c.ot.length} management outcomes are on track; ${c.cnt.r} need action now.`});
    }
    const by = (x, y) => (y.s - x.s) || (x.t < y.t ? -1 : 1);
    return {wins: out.filter(x => x.w).sort(by).slice(0, 3), concerns: out.filter(x => !x.w).sort(by).slice(0, 3)};
  }

  // Five actions, each from a rule and given to an owner role (never a person).
  function actions(c){
    const a = c.a, L = [];
    const worstU = c.units.slice().sort((x, y) => x.a.varp - y.a.varp)[0];
    if (worstU && worstU.a.varp < GOAL.varp)
      L.push({pri: 90 + -worstU.a.varp * 100, role: "Finance lead", rule: "Profit centre more than 5% below budget",
        t: `Review the plan for ${(st.site === "all" ? worstU.s.name + " · " : "") + worstU.pc}: it is ${money(-worstU.a.var)} (${pct(-worstU.a.varp)}) below budget. Agree a price or volume fix this month.`});
    if (a.quotes > 0 && a.sla < GOAL.sla)
      L.push({pri: 80 + (GOAL.sla - a.sla) * 100, role: "Service lead", rule: "Quotes within 30 minutes below 90%",
        t: `Set a quote rota so every quote goes out within 30 minutes. Today ${pct(a.sla)} do; ${Math.max(0, a.quotes - a.q30)} were late.`});
    if (a.rev > 0 && a.dso > GOAL.dso) {
      const free = Math.max(0, a.recv - GOAL.dso * a.rev / c.days);
      L.push({pri: 75 + (a.dso - GOAL.dso), role: "Finance lead", rule: "Days sales outstanding above 45",
        t: `Chase money owed. Customers take ${a.dso.toFixed(0)} days to pay; getting to 45 days would free about ${money(free)} of cash.`});
    }
    if (c.stale.length)
      L.push({pri: 60 + c.stale.length, role: "Head of sales", rule: "Open deals older than 90 days",
        t: `Decide on ${c.stale.length} open deals older than 90 days, worth ${money(sum(c.stale, d => d.amount))}: move each one forward or close it as lost.`});
    if (c.won.length + c.lost.length > 0 && c.winRate < GOAL.win)
      L.push({pri: 55 + (GOAL.win - c.winRate) * 100, role: "Head of sales", rule: "Win rate below 35%",
        t: `Run a lost-deal review: win rate is ${pct(c.winRate)} against 35%. Find the top two reasons and fix the offer or the follow-up.`});
    if (c.qs.length > 1 && c.shNow < c.shPrev)
      L.push({pri: 50 + div(c.shPrev - c.shNow, c.shPrev) * 100, role: "Head of sales", rule: "Market share fell last quarter",
        t: `Win back share: it fell from ${pct(c.shPrev)} to ${pct(c.shNow)}. Focus on the ${money(c.lostM)} of market we already serve but do not win.`});
    const reds = c.ot.filter(o => o.r === "r").sort((x, y) => y.gap - x.gap);
    if (reds.length)
      L.push({pri: 45 + reds.length, role: reds[0].owner, rule: "Outcome more than 10% off target",
        t: `Fix "${reds[0].n}": latest ${fmtK(reds[0].a, reds[0].unit)} against a target of ${fmtK(reds[0].target, reds[0].unit)}.${reds.length > 1 ? ` ${reds.length - 1} more ${reds.length > 2 ? "outcomes are" : "outcome is"} also red.` : ""}`});
    if (a.rev > 0 && a.gmp < GOAL.gmp)
      L.push({pri: 40 + (GOAL.gmp - a.gmp) * 100, role: "Operations lead", rule: "Gross margin below 40%",
        t: `Check cost of sales: gross margin is ${pct(a.gmp)} against a 40% goal. Look at supplier prices and waste first.`});
    // routine actions, always available so there are five
    if (c.tgt > 0)
      L.push({pri: 20, role: "Head of sales", rule: "Draft growth target (routine)",
        t: `Turn the draft growth target of ${money(c.tgt)} into named accounts and a monthly number.`});
    L.push({pri: 15, role: "Finance lead", rule: "Budget review (routine)",
      t: `Confirm next period's budget. This period ended ${a.budget > 0 ? pct(a.varp) + " against budget" : "with no budget set"}.`});
    L.push({pri: 12, role: "Operations lead", rule: "On-time delivery (routine)",
      t: `Keep on-time delivery at or above ${c.ontime.toFixed(0)}%, the average for this period (goal 95%).`});
    L.push({pri: 10, role: "Quality lead", rule: "Decision follow-up (routine)",
      t: "Check each decision in the log below at the next review and mark what is done."});
    L.push({pri: 8, role: "People lead", rule: "Share the pack (routine)",
      t: "Share this pack with every profit-centre lead and agree one action each."});
    return L.sort((x, y) => y.pri - x.pri).slice(0, 5);
  }

  // Diverging bar chart of budget variance by profit centre, one scale for both sides.
  function varChart(units){
    if (!units.length) return '<p class="note">No profit centres match the filters.</p>';
    let u = units.slice().sort((x, y) => y.a.var - x.a.var);
    if (u.length > 8) u = u.slice(0, 4).concat(u.slice(-4));
    const W = 480, RH = 24, T = 6, Lw = 150, R = 8, H = T + u.length * RH + 6;
    const mx = Math.max(1, ...u.map(x => Math.abs(x.a.var)));
    const half = (W - Lw - R) / 2, zero = Lw + half;
    const nm = x => { const s = (st.site === "all" ? x.s.code + " · " : "") + x.pc; return s.length > 24 ? s.slice(0, 23) + "…" : s; };
    let g = `<line x1="${zero}" x2="${zero}" y1="${T - 2}" y2="${H - 4}" stroke="var(--line)"/>`;
    u.forEach((x, i) => {
      const v = fin(x.a.var), w = Math.abs(v) / mx * half, y = T + i * RH;
      const x0 = v >= 0 ? zero : zero - w;
      g += `<g data-drill="site:${esc(x.s.id)}|pc:${esc(x.pc)}" data-s="cursor:pointer"><text x="0" y="${y + 15}">${esc(nm(x))}</text>`;
      g += `<rect x="${x0}" y="${y + 4}" width="${Math.max(0.5, w)}" height="${RH - 9}" rx="2" fill="${v >= 0 ? "var(--c2)" : "var(--bad)"}"><title>${esc(x.s.name + " · " + x.pc)}: ${money(v)} (${pct(x.a.varp)}) vs budget</title></rect>`;
      g += `<text x="${v >= 0 ? zero - 4 : zero + 4}" y="${y + 15}" text-anchor="${v >= 0 ? "end" : "start"}">${money(v)}</text></g>`;
    });
    return `<svg id="boardVarSvg" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Budget variance by profit centre">${g}</svg>
      <div class="legend"><span><i data-s="background:var(--c2)"></i>Above budget</span><span><i data-s="background:var(--bad)"></i>Below budget</span><span>Bar length to one scale; click a row to filter</span></div>`;
  }
  function ragBar(cnt){
    const tot = cnt.g + cnt.a + cnt.r; if (!tot) return "";
    const W = 300, H = 18; let x = 0, g = "";
    [["g", "var(--good)", "On track"], ["a", "var(--warn)", "Watch"], ["r", "var(--bad)", "Act now"]].forEach(([k, c, n]) => {
      const w = cnt[k] / tot * W; if (w > 0) g += `<rect x="${x}" y="0" width="${w}" height="${H}" fill="${c}"><title>${n}: ${cnt[k]}</title></rect>`; x += w; });
    return `<svg id="boardRagSvg" viewBox="0 0 ${W} ${H}" width="100%" preserveAspectRatio="none" data-s="height:18px;border-radius:4px" role="img" aria-label="Outcomes by status">${g}</svg>`;
  }

  // Delegated events (the view is redrawn on every render).
  function addDecision(){
    const i = document.getElementById("boardDecIn"); if (!i) return;
    const t = i.value.trim(); if (!t) { toast("Type a decision first"); return; }
    const list = decisions();
    list.unshift({id: Date.now().toString(36) + list.length, d: new Date().toISOString().slice(0, 10), t: t.slice(0, 300)});
    saveDecisions(list.slice(0, 200)); render(); toast("Decision added");
    const n = document.getElementById("boardDecIn"); if (n) n.focus();
  }
  function copySummary(){
    const txt = lastText, done = () => toast("Summary copied");
    const fallback = () => { const ta = document.createElement("textarea"); ta.value = txt; ta.setAttribute("readonly", ""); ta.style.position = "fixed"; ta.style.opacity = "0";
      document.body.append(ta); ta.select(); try { document.execCommand("copy"); } catch(e) {} ta.remove(); done(); };
    try { if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(txt).then(done, fallback); else fallback(); }
    catch(e) { fallback(); }
  }
  document.addEventListener("click", e => {
    if (e.target.closest("[data-board-copy]")) { copySummary(); return; }
    if (e.target.closest("[data-board-add]")) { addDecision(); return; }
    const del = e.target.closest("[data-board-del]");
    if (del) { saveDecisions(decisions().filter(x => x.id !== del.dataset.boardDel)); render(); toast("Decision deleted"); }
  });
  document.addEventListener("keydown", e => { if (e.key === "Enter" && e.target.id === "boardDecIn") { e.preventDefault(); addDecision(); } });

  BI.add({
    id: "board",
    label: "Board pack",
    formulas: {
      boardHead: "Headline = Revenue, Contribution (Gross margin - Direct operating cost) and Budget variance (Revenue - Budget) for the filters above",
      boardWin: "Wins and concerns: each rule (profit-centre budget variance, total budget variance, quote speed, DSO, win rate, market share change, gross margin, revenue trend, outcomes) is scored by how far it is from its goal; the 3 strongest above goal are wins, the 3 furthest below are concerns",
      boardCommit: "Commit this quarter = Won + Negotiation deals closing in the current quarter; Best case = Commit + Proposal",
      boardAct: "Actions: each rule that breaks its goal adds an action for an owner role, ranked by how far off it is; routine actions fill the list to five",
      boardFree: "Cash freed = Receivables now - 45 x (Revenue / days in period)"
    },
    render: () => {
      const c = compute();
      const a = c.a, p = c.p, sc = scopeText(c.ms);
      if (!c.F.length) {
        lastText = "Board pack: no data for these filters.";
        return `<section class="p w12"><h2>Board pack</h2><p class="sub">${esc(sc)}</p><p>No figures match these filters. Clear a filter to see the summary.</p></section>`;
      }
      const wc = winsConcerns(c), acts = actions(c), decs = decisions();
      const vsP = p.rev > 0 ? `, ${a.rev >= p.rev ? "up" : "down"} ${pct(Math.abs(div(a.rev - p.rev, p.rev)))} on the previous ${c.ms.length} months` : " (no earlier period to compare)";
      const head = [
        `Revenue was ${money(a.rev)}${vsP}.`,
        a.budget > 0 ? `That is ${money(Math.abs(a.var))} (${pct(Math.abs(a.varp))}) ${a.var >= 0 ? "above" : "below"} the budget of ${money(a.budget)}.` : "No budget was set for this period.",
        `Contribution was ${money(a.contrib)}, or ${pct(a.cp)} of revenue, after ${money(a.cogs)} cost of sales and ${money(a.opex)} direct cost.`
      ];
      const pipe = c.dl.length ? [
        `Weighted pipeline is ${money(c.wp)} across ${c.open.length} open deals${st.prob !== 100 ? ` (stage chances at ${st.prob}%)` : ""}.`,
        `Commit for ${c.qLbl} is ${money(c.commit)}, and best case is ${money(c.best)}.`,
        c.won.length + c.lost.length ? `Win rate is ${pct(c.winRate)}.` : "No deals have been won or lost yet."
      ] : ["No deals match these filters."];
      const mk = c.m.length ? [
        `Our share of a ${money(c.size)} yearly market is ${pct(c.share)}.`,
        c.qs.length > 1 ? `Share ${c.shNow >= c.shPrev ? "rose" : "fell"} from ${pct(c.shPrev)} to ${pct(c.shNow)} last quarter.` : "",
        `Lost market (lines we offer but do not win) is ${money(c.lostM)}; lines we do not offer yet are worth ${money(c.nonM)}.`,
        `The draft growth target is ${money(c.tgt)}.`
      ].filter(Boolean) : ["No market records match these filters."];
      const oc = c.ot.length ? `${c.cnt.g} outcomes are on track, ${c.cnt.a} to watch and ${c.cnt.r} to act on now, out of ${c.ot.length}.` : "No management outcomes for these filters.";

      // plain-text copy
      const T = [];
      T.push("BOARD PACK (demo data)", sc, "");
      T.push("HEADLINE", ...head, "");
      T.push("WINS", ...(wc.wins.length ? wc.wins.map((x, i) => `${i + 1}. ${x.t}`) : ["None under the rules for these filters."]), "");
      T.push("CONCERNS", ...(wc.concerns.length ? wc.concerns.map((x, i) => `${i + 1}. ${x.t}`) : ["None under the rules for these filters."]), "");
      T.push("PIPELINE OUTLOOK", ...pipe, "");
      T.push("MARKET", ...mk, "");
      T.push("OUTCOMES", oc, "");
      T.push("RECOMMENDED ACTIONS", ...acts.map((x, i) => `${i + 1}. [${x.role}] ${x.t} (Rule: ${x.rule})`));
      if (decs.length) T.push("", "DECISIONS LOG", ...decs.map(x => `${x.d}: ${x.t}`));
      lastText = T.join("\n");

      const li = (list, pill, empty) => list.length
        ? `<ol data-s="margin:0;padding-left:1.2em;display:grid;gap:8px">${list.map(x => `<li>${esc(x.t)} <span class="note">Rule: ${esc(x.rule)}.</span> <button type="button" class="lnk" data-drill="${esc(x.drill)}">See</button></li>`).join("")}</ol>`
        : `<p class="note">${empty}</p>`;
      const tile = (k, v, d, f) => `<div class="tile" title="${esc(FX[f] || "")}"><span class="k">${k}</span><span class="v">${v}</span><span class="d">${d}</span></div>`;
      const numRows = [
        ["Revenue", money(a.rev), p.rev > 0 ? pct(div(a.rev - p.rev, p.rev)) + " vs previous" : "-", `<span class="pill ${a.varp >= 0 ? "g" : a.varp > -0.1 ? "a" : "r"}">${a.varp >= 0 ? "On budget" : "Below budget"}</span>`],
        ["Budget variance", money(a.var), pct(a.varp), `<span class="pill ${a.varp >= 0 ? "g" : a.varp > -0.1 ? "a" : "r"}">${ragTxt[a.varp >= 0 ? "g" : a.varp > -0.1 ? "a" : "r"]}</span>`],
        ["Contribution", money(a.contrib), pct(a.cp) + " of revenue", "-"],
        ["Quotes within 30 min", pct(a.sla), "goal 90%", `<span class="pill ${rag(a.sla, GOAL.sla, "higher")}">${ragTxt[rag(a.sla, GOAL.sla, "higher")]}</span>`],
        ["Days sales outstanding", a.dso.toFixed(0) + " days", "goal 45 days", `<span class="pill ${rag(a.dso, GOAL.dso, "lower")}">${ragTxt[rag(a.dso, GOAL.dso, "lower")]}</span>`],
        ["Weighted pipeline", money(c.wp), c.open.length + " open deals", "-"],
        ["Commit " + c.qLbl, money(c.commit), "best case " + money(c.best), "-"],
        ["Win rate", pct(c.winRate), "goal 35%", c.won.length + c.lost.length ? `<span class="pill ${rag(c.winRate, GOAL.win, "higher")}">${ragTxt[rag(c.winRate, GOAL.win, "higher")]}</span>` : "-"],
        ["Market share", pct(c.share), c.qs.length > 1 ? ((c.shNow - c.shPrev) * 100).toFixed(2) + " pts last quarter" : "-", "-"],
        ["Draft growth target", money(c.tgt), "10% lost + 5% non-offered", "-"]
      ];
      return `<div class="tiles t3">
    ${tile("Revenue", money(a.rev), delta(a.rev, p.rev), "rev")}
    ${tile("Contribution", money(a.contrib), delta(a.contrib, p.contrib), "contrib")}
    ${tile("Against budget", money(a.var), `<span class="${a.var >= 0 ? "up" : "down"}">${pct(a.varp)} vs budget</span>`, "var")}
    ${tile("Weighted pipeline", money(c.wp), `<span class="flat">commit ${money(c.commit)}</span>`, "wp")}
    ${tile("Market share", pct(c.share), `<span class="flat">target ${money(c.tgt)}</span>`, "share")}
    ${tile("Outcomes on track", c.cnt.g + " of " + c.ot.length, `<span class="${c.cnt.r ? "down" : "up"}">${c.cnt.r} act now</span>`, "rag")}</div>
  <section class="p w12" id="boardHead"><h2>Headline</h2><p class="sub">${esc(sc)} · written from the numbers, demo data</p>
    <p data-s="margin:0 0 10px;max-width:72ch">${esc(head.join(" "))}</p>
    <div class="row"><button type="button" data-board-copy>Copy summary</button><span class="note">Copies the whole pack as plain text, ready to paste into an email.</span></div>
    <details data-s="margin-top:8px"><summary class="note">Show plain text</summary><pre id="boardText" data-s="white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--f-num);font-size:.75rem;margin:8px 0 0">${esc(lastText)}</pre></details></section>
  <section class="p w4"><h2>Wins</h2><p class="sub" title="${esc(FX.boardWin)}">Strongest results against their goals</p>${li(wc.wins, "g", "No measure beats its goal under the rules for these filters.")}</section>
  <section class="p w4"><h2>Concerns</h2><p class="sub" title="${esc(FX.boardWin)}">Furthest below their goals</p>${li(wc.concerns, "r", "No measure is below its goal under the rules for these filters.")}</section>
  <section class="p w4"><h2>Outcomes</h2><p class="sub">${esc(FX.rag)}</p>${ragBar(c.cnt)}
    <div class="row" data-s="margin-top:8px"><span class="pill g">${c.cnt.g} on track</span><span class="pill a">${c.cnt.a} watch</span><span class="pill r">${c.cnt.r} act now</span></div>
    <p data-s="margin:8px 0 0">${esc(oc)}</p><button type="button" class="lnk" data-drill="tab:outcomes">Open outcomes</button></section>
  <section class="p w8"><h2>Budget variance by profit centre</h2><p class="sub">${esc(FX.var)} · ${c.units.length > 8 ? "best 4 and worst 4" : "all in view"}</p>${varChart(c.units)}</section>
  <section class="p w4"><h2>Pipeline outlook</h2><p class="sub" title="${esc(FX.boardCommit)}">${esc(st.country === "all" ? "All countries" : st.country)}</p><p data-s="margin:0">${esc(pipe.join(" "))}</p>
    <h2 data-s="margin-top:14px">Market headline</h2><p class="sub">${esc(FX.tgt)}</p><p data-s="margin:0">${esc(mk.join(" "))}</p></section>
  <section class="p w12"><h2>Five recommended actions</h2><p class="sub">${esc(FX.boardAct)}</p>
    ${table("tBoardAct", [{t: "#"}, {t: "Action"}, {t: "Rule", f: "boardAct"}, {t: "Owner role"}], acts.map((x, i) => [i + 1, `<span data-s="white-space:normal;display:block;min-width:16rem">${esc(x.t)}</span>`, esc(x.rule), esc(x.role)]))}</section>
  <section class="p w12"><h2>Key numbers</h2><p class="sub">${esc(sc)}</p>
    ${table("tBoardNum", [{t: "Measure"}, {t: "Value"}, {t: "Compare"}, {t: "Status", f: "rag"}], numRows)}</section>
  <section class="p w12"><h2>Decisions log</h2><p class="sub">Write down what the board agreed. Kept in this browser only.</p>
    <div class="row"><label for="boardDecIn" class="note">Decision</label><input id="boardDecIn" type="text" maxlength="300" placeholder="For example: approve a quote rota from next month" data-s="flex:1 1 14rem;min-width:0;font:inherit;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:6px 8px"><button type="button" data-board-add>Add</button></div>
    ${decs.length ? table("tBoardDec", [{t: "Date"}, {t: "Decision"}, {t: ""}], decs.map(x => [esc(x.d), `<span data-s="white-space:normal">${esc(x.t)}</span>`, `<button type="button" data-board-del="${esc(x.id)}" aria-label="Delete this decision">Delete</button>`]))
      : '<p class="note" id="boardDecEmpty">No decisions logged yet.</p>'}</section>`;
    }
  });
})();

/* module: cash.js */
// Cash and working capital tab. Respects site, profit-centre and period filters. Demo data only.
(function(){
  const WPM = 4.33; // weeks in a month
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const clamp01 = v => Math.min(1, Math.max(0, fin(v)));
  const AGE_W = [0.60, 0.25, 0.10, 0.05];
  const AGE_K = ["0-30 days", "31-60 days", "61-90 days", "Over 90 days"];

  function inScope(f){ return (st.site==="all"||f.site===st.site)&&(st.pc==="all"||f.pc===st.pc); }

  // Cash measures for one slice of facts (pred) over months ms.
  function calc(pred, ms){
    ms = ms || months();
    const all = D.facts.filter(pred);
    const r = all.filter(f=>ms.includes(f.m));
    const rev = sum(r,f=>f.rev), cash = sum(r,f=>f.cash), cost = sum(r,f=>f.cogs+f.opex);
    const last = ms[ms.length-1];
    const recv = last ? sum(all.filter(f=>f.m===last),f=>f.recv) : 0;
    const i0 = ms.length ? D.months.indexOf(ms[0]) : -1;
    const openM = i0>0 ? D.months[i0-1] : ms[0];
    const openRecv = openM ? sum(all.filter(f=>f.m===openM),f=>f.recv) : 0;
    const days = ms.length*30.4;
    const n = ms.length;
    return {
      rev: fin(rev), cash: fin(cash), cost: fin(cost), recv: fin(recv), openRecv: fin(openRecv), n,
      dso: rev>0 ? fin(recv/(rev/days)) : 0,
      coll: (openRecv+rev)>0 ? clamp01(cash/(openRecv+rev)) : 0,
      conv: rev>0 ? fin(cash/rev) : 0,
      last, all
    };
  }

  // Ageing estimate from the last 4 months of receivables up to the period end.
  function ageing(c){
    const idx = c.last ? D.months.indexOf(c.last) : -1;
    const ms4 = [0,1,2,3].map(k=>idx-k>=0 ? D.months[idx-k] : null); // latest first
    const bal = ms4.map(m=>m ? fin(sum(c.all.filter(f=>f.m===m),f=>f.recv)) : 0);
    const raw = bal.map((b,i)=>b*AGE_W[i]);
    const tot = sum(raw);
    const amt = raw.map(x=>tot>0 ? fin(x/tot*c.recv) : 0);
    return AGE_K.map((k,i)=>({k, month: ms4[i]||"none", bal: bal[i], amt: amt[i], share: c.recv>0 ? fin(amt[i]/c.recv) : 0}));
  }

  // 13-week forecast.
  function forecast(c){
    const wks = Math.max(1, c.n*WPM);
    const wRev = fin(c.rev/wks), wOut = fin(c.cost/wks);
    const wRate = c.dso>0 ? clamp01(7/c.dso) : 0;
    let bal = c.n ? fin(c.rev/c.n) : 0, recv = c.recv;
    const rows = [];
    for(let w=1; w<=13; w++){
      const open = bal, rStart = recv;
      const fromRecv = fin(rStart*wRate);
      const fromNew = fin(wRev*c.coll);
      const inflow = fromRecv + fromNew;
      const net = inflow - wOut;
      bal = fin(open + net);
      recv = Math.max(0, fin(rStart - fromRecv + wRev - fromNew));
      rows.push({w, open, rStart, fromRecv, fromNew, inflow, out: wOut, net, close: bal});
    }
    return {rows, wRev, wOut, wRate, opening: rows[0].open};
  }

  // Line chart that also handles values below zero.
  function cashLine(labels, vals){
    const W=640,H=220,L=58,R=12,T=12,B=28,w=W-L-R,h=H-T-B;
    const hi0 = Math.max(0, ...vals), lo0 = Math.min(0, ...vals);
    const hi = hi0>0 ? niceMax(hi0*1.05) : (lo0<0 ? 0 : 1);
    const lo = lo0<0 ? -niceMax(-lo0*1.05) : 0;
    const span = (hi-lo)||1;
    const x = i=>L+i*w/Math.max(1,labels.length-1), y = v=>T+h-(v-lo)/span*h;
    let g = "";
    for(let i=0;i<=4;i++){const v=lo+span*i/4; g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${money(v)}</text>`;}
    if(lo<0) g+=`<line x1="${L}" x2="${W-R}" y1="${y(0)}" y2="${y(0)}" stroke="var(--bad)" stroke-dasharray="4 3"/>`;
    labels.forEach((l,i)=>g+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${l}</text>`);
    g += `<polyline points="${vals.map((v,i)=>x(i)+","+y(v)).join(" ")}" fill="none" stroke="var(--c1)" stroke-width="2"/>`;
    vals.forEach((v,i)=>g+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.8" fill="${v<0?"var(--bad)":"var(--c1)"}"><title>Closing balance ${labels[i]}: ${money(v)}</title></circle>`);
    return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Closing cash balance for the next 13 weeks">${g}</svg><div class="legend"><span><i data-s="background:var(--c1)"></i>Closing balance</span>${lo<0?'<span><i data-s="background:var(--bad)"></i>Zero line</span>':""}</div>`;
  }

  const dsoPill = d => d<=45 ? "g" : d<=60 ? "a" : "r";

  BI.add({
    id: "cash",
    label: "Cash",
    formulas: {
      cashIn: "Cash collected = sum of customer payments received in the period",
      cashRecv: "Receivables now = money customers owe at the end of the last month in the period",
      cashColl: "Collection rate = Cash collected / (Receivables at start of period + Revenue billed in period)",
      cashConv: "Cash conversion = Cash collected / Revenue",
      cashAge: "Ageing estimate: take receivables for the last 4 months; weight them 60% (latest month, 0-30 days), 25% (month before, 31-60), 10% (two months back, 61-90), 5% (three months back, over 90); then scale the four so they add up to receivables now",
      cashWkRate: "Weekly collection rate = 7 / DSO (share of what customers owe that comes in each week)",
      cashWkRev: "Average weekly revenue = Revenue in period / (months in period x 4.33)",
      cashOut: "Weekly outflow = (Cost of sales + Operating cost) in period / (months in period x 4.33)",
      cashFromRecv: "Collected from receivables = Receivables at start of week x Weekly collection rate",
      cashFromNew: "New billing collected = Average weekly revenue x Collection rate",
      cashInflow: "Expected inflow = Collected from receivables + New billing collected",
      cashNet: "Net cash = Expected inflow - Weekly outflow",
      cashOpen: "Opening balance (demo) = 1 month of revenue (Revenue in period / months in period); after week 1 it is last week's closing balance",
      cashClose: "Closing balance = Opening balance + Expected inflow - Weekly outflow",
      cashRecvRoll: "Receivables next week = Receivables at start - Collected from receivables + Average weekly revenue - New billing collected",
      cashLow: "Lowest balance = smallest closing balance in the 13-week forecast",
      cashStatus: "DSO status: green 45 days or less; amber 46 to 60 days; red over 60 days"
    },
    render: () => {
      const ms = months();
      const c = calc(inScope, ms);
      const p = calc(inScope, prevMonths());
      const age = ageing(c);
      const fc = forecast(c);
      const low = Math.min(...fc.rows.map(r=>r.close));
      const scope = (st.site==="all"?"All sites on this side":esc(siteName(st.site)))+" · "+(st.pc==="all"?"all profit centres":esc(st.pc))+" · last "+ms.length+" months";

      const tiles = [
        ["Cash collected", money(c.cash), delta(c.cash,p.cash), "cashIn"],
        ["Receivables now", money(c.recv), delta(c.recv,p.recv,"lower"), "cashRecv"],
        ["Collection rate", pct(c.coll), delta(c.coll,p.coll), "cashColl"],
        ["Days sales outstanding", c.dso.toFixed(0)+" days", `<span class="pill ${dsoPill(c.dso)}">${ragTxt[dsoPill(c.dso)]}</span> goal 45 days`, "dso"],
        ["Cash conversion", pct(c.conv), delta(c.conv,p.conv), "cashConv"],
        ["Lowest balance, 13 weeks", money(low), `<span class="${low<0?"down":"flat"}">${low<0?"Goes below zero":"Stays above zero"}</span>`, "cashLow"]
      ];

      const ageColors = ["var(--good)","var(--c1)","var(--warn)","var(--bad)"];
      const ageRows = age.map(a=>[esc(a.k), esc(a.month), money(a.bal), Math.round(AGE_W[age.indexOf(a)]*100)+"%", money(a.amt), pct(a.share)]);

      const fRows = fc.rows.map(r=>["Week "+r.w, money(r.open), money(r.rStart), money(r.fromRecv), money(r.fromNew), money(r.inflow), money(r.out),
        `<span class="${r.net>=0?"up":"down"}">${money(r.net)}</span>`, `<span class="${r.close>=0?"":"down"}">${money(r.close)}</span>`]);
      const fFoot = ["13 weeks", money(fc.opening), "", money(sum(fc.rows,r=>r.fromRecv)), money(sum(fc.rows,r=>r.fromNew)), money(sum(fc.rows,r=>r.inflow)),
        money(sum(fc.rows,r=>r.out)), money(sum(fc.rows,r=>r.net)), money(fc.rows[12].close)];

      const units = [];
      D.sites.filter(s=>st.site==="all"||s.id===st.site).forEach(s=>s.pcs.filter(pc=>st.pc==="all"||pc===st.pc).forEach(pc=>{
        const u = calc(f=>f.site===s.id&&f.pc===pc, ms);
        units.push({s, pc, u});
      }));
      units.sort((a,b)=>(b.u.dso-a.u.dso)||(a.u.coll-b.u.coll));
      const uRows = units.map(x=>[`<span data-drill="site:${esc(x.s.id)}|pc:${esc(x.pc)}" data-s="cursor:pointer" title="Click to filter to this profit centre">${esc(x.s.name+" · "+x.pc)}</span>`,
        money(x.u.rev), money(x.u.cash), money(x.u.recv), x.u.dso.toFixed(0)+" days", pct(x.u.coll), `<span class="pill ${dsoPill(x.u.dso)}">${ragTxt[dsoPill(x.u.dso)]}</span>`]);
      const red = units.filter(x=>dsoPill(x.u.dso)==="r").length;

      return `<div class="tiles t3">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]]||"")}"><span class="k">${t[0]}</span><span class="v">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>
  <section class="p w8"><h2>Closing cash balance, next 13 weeks</h2><p class="sub">${scope} · demo opening balance = 1 month of revenue</p>${cashLine(fc.rows.map(r=>"W"+r.w), fc.rows.map(r=>r.close))}
    <p class="note">Each week: ${money(fc.wRev)} average revenue, ${pct(fc.wRate)} of what customers owe comes in, ${money(fc.wOut)} goes out.</p></section>
  <section class="p w4"><h2>How old is the money owed</h2><p class="sub">Estimate from the last 4 months of receivables</p>${hbars(age.map((a,i)=>({k:a.k,v:a.amt,c:ageColors[i]})),money)}
    <p class="note" title="${esc(FX.cashAge)}">Rule: ${esc(FX.cashAge)}.</p></section>
  <section class="p w12"><h2>Receivables ageing estimate</h2><p class="sub">${scope}</p>${table("tCashAge",[{t:"Age bucket"},{t:"From month"},{t:"That month's receivables",f:"cashRecv"},{t:"Weight",f:"cashAge"},{t:"Estimated amount",f:"cashAge"},{t:"Share",f:"cashAge"}],ageRows,["Total","","","",money(sum(age,a=>a.amt)),pct(sum(age,a=>a.share))])}</section>
  <section class="p w12"><h2>13-week cash forecast</h2><p class="sub">${scope} · hover a column title to see how it is worked out</p>${table("tCashFc",[{t:"Week"},{t:"Opening",f:"cashOpen"},{t:"Owed at start",f:"cashRecvRoll"},{t:"From money owed",f:"cashFromRecv"},{t:"From new billing",f:"cashFromNew"},{t:"Inflow",f:"cashInflow"},{t:"Outflow",f:"cashOut"},{t:"Net",f:"cashNet"},{t:"Closing",f:"cashClose"}],fRows,fFoot)}</section>
  <section class="p w12"><h2>Who pays slowest</h2><p class="sub">${scope} · worst first · ${units.length} profit centres${red?` · ${red} over 60 days`:""}</p>${table("tCashDso",[{t:"Site · profit centre"},{t:"Revenue",f:"rev"},{t:"Cash collected",f:"cashIn"},{t:"Receivables now",f:"cashRecv"},{t:"DSO",f:"dso"},{t:"Collection rate",f:"cashColl"},{t:"Status",f:"cashStatus"}],uRows)}</section>`;
    }
  });
})();

/* module: compare.js */
// Compare tab: benchmarks every site and every profit centre side by side.
// Ignores the site, profit-centre and country filters on purpose (so every unit shows); respects the period. Demo data only.
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const pctv = v => v===null ? "n/a" : pct(v);
  const M = [
    {k:"rev",    t:"Revenue",        f:"cmpRev",    better:"higher", fmt:v=>money(v)},
    {k:"growth", t:"Growth",         f:"cmpGrowth", better:"higher", fmt:v=>v===null?"n/a":(v>=0?"+":"")+(v*100).toFixed(1)+"%", points:true},
    {k:"gmp",    t:"GM %",           f:"gmp",       better:"higher", fmt:pctv},
    {k:"cp",     t:"Contribution %", f:"cp",        better:"higher", fmt:pctv},
    {k:"sla",    t:"Quote SLA %",    f:"cmpSla",    better:"higher", fmt:pctv},
    {k:"dso",    t:"DSO",            f:"dso",       better:"lower",  fmt:v=>v===null?"n/a":v.toFixed(0)+" d"},
    {k:"win",    t:"Win rate",       f:"cmpWin",    better:"higher", fmt:pctv},
    {k:"ontime", t:"On-time %",      f:"cmpOntime", better:"higher", fmt:v=>v===null?"n/a":v.toFixed(1)+"%"},
    {k:"nps",    t:"NPS",            f:"cmpNps",    better:"higher", fmt:v=>v===null?"n/a":v.toFixed(1)}
  ];
  const RADAR = ["gmp","cp","sla","win","ontime","dso"];
  const RADAR_T = {gmp:"GM %", cp:"Contribution %", sla:"Quote SLA", win:"Win rate", ontime:"On-time", dso:"DSO (low = good)"};
  const SW = ["var(--c1)","var(--c2)","var(--c3)","var(--c4)","var(--c5)","var(--c6)"];

  // All measures for one slice of facts and deals.
  function measure(fpred, dpred, ms, pms){
    const r = D.facts.filter(f=>fpred(f)&&ms.includes(f.m));
    if(!r.length) return null;
    const p = D.facts.filter(f=>fpred(f)&&pms.includes(f.m));
    const rev = sum(r,f=>f.rev), cogs = sum(r,f=>f.cogs), opex = sum(r,f=>f.opex);
    const prev = sum(p,f=>f.rev);
    const quotes = sum(r,f=>f.quotes), q30 = sum(r,f=>f.quotes_30);
    const last = ms[ms.length-1];
    const recv = sum(r.filter(f=>f.m===last),f=>f.recv);
    const days = ms.length*30.4;
    const dl = D.deals.filter(dpred);
    const won = dl.filter(d=>d.stage==="Won").length, lost = dl.filter(d=>d.stage==="Lost").length;
    return {
      rev: fin(rev),
      growth: prev>0 ? fin((rev-prev)/prev) : null,
      gmp: rev>0 ? fin((rev-cogs)/rev) : null,
      cp: rev>0 ? fin((rev-cogs-opex)/rev) : null,
      sla: quotes>0 ? fin(q30/quotes) : null,
      dso: rev>0 ? fin(recv/(rev/days)) : null,
      win: (won+lost)>0 ? fin(won/(won+lost)) : null,
      ontime: fin(sum(r,f=>f.ontime)/r.length),
      nps: fin(sum(r,f=>f.nps)/r.length)
    };
  }

  // Adds index (100 = average), rank (1 = best) and quartile per measure to each unit.
  function bench(units){
    const out = {};
    M.forEach(m=>{
      const vals = units.map(u=>u.v[m.k]).filter(v=>v!==null);
      const avg = vals.length ? sum(vals)/vals.length : 0;
      const sorted = vals.slice().sort((a,b)=>m.better==="lower"?a-b:b-a);
      units.forEach(u=>{
        const v = u.v[m.k];
        if(v===null){ u.b[m.k] = null; return; }
        let idx;
        if(m.points) idx = 100 + (v-avg)*100;
        else if(m.better==="lower") idx = v>0 ? avg/v*100 : 100;
        else idx = avg!==0 ? v/avg*100 : 100;
        const rank = sorted.indexOf(v)+1;
        const q = Math.min(4, Math.max(1, Math.ceil(rank/vals.length*4)));
        u.b[m.k] = {idx: fin(idx), rank, q, n: vals.length};
      });
      out[m.k] = {avg: fin(avg), n: vals.length};
    });
    return out;
  }

  const QCLS = {1:"g", 2:"", 3:"a", 4:"r"};
  const QTXT = {1:"Top quarter", 2:"Second quarter", 3:"Third quarter", 4:"Bottom quarter"};
  function cell(u, m){
    const v = u.v[m.k], b = u.b[m.k];
    if(v===null || !b) return `<span class="note">n/a</span>`;
    const cls = QCLS[b.q];
    const style = cls ? "" : ` data-s="background:var(--accent-soft);color:var(--ink)"`;
    return `<span class="pill ${cls}"${style} title="${QTXT[b.q]} · index ${b.idx.toFixed(0)} · rank ${b.rank} of ${b.n}">${m.fmt(v)}</span><br><span class="note">${b.idx.toFixed(0)} · #${b.rank}</span>`;
  }
  const avgCell = (s, m) => s.n ? `<span class="note">avg</span> ${m.fmt(s.avg)}` : "n/a";

  // Radar / spider chart: each site's 6 measures scaled 0-100 (worst site = 0, best = 100).
  function radar(units){
    const W=420,H=330,cx=210,cy=165,R=112,n=RADAR.length;
    const ang = i => (-90 + i*360/n)*Math.PI/180;
    const pt = (i, s) => [cx + Math.cos(ang(i))*R*s/100, cy + Math.sin(ang(i))*R*s/100];
    const score = {};
    RADAR.forEach(k=>{
      const m = M.find(x=>x.k===k);
      const vals = units.map(u=>u.v[k]).filter(v=>v!==null);
      const lo = vals.length ? Math.min(...vals) : 0, hi = vals.length ? Math.max(...vals) : 0;
      units.forEach(u=>{
        const v = u.v[k];
        let s = v===null ? 0 : (hi>lo ? (v-lo)/(hi-lo)*100 : 100);
        if(m.better==="lower" && v!==null && hi>lo) s = 100 - s;
        (score[u.key] = score[u.key] || {})[k] = fin(s);
      });
    });
    let g = "";
    [25,50,75,100].forEach(s=>{ g += `<polygon points="${RADAR.map((k,i)=>pt(i,s).join(",")).join(" ")}" fill="none" stroke="var(--line)" stroke-width="1"/>`; });
    g += `<text x="${cx+4}" y="${cy-R*0.5+4}" data-s="font-size:9px">50</text><text x="${cx+4}" y="${cy-R+4}" data-s="font-size:9px">100</text>`;
    RADAR.forEach((k,i)=>{
      const [x,y] = pt(i,100), [lx,ly] = pt(i,116);
      const c = Math.cos(ang(i));
      const anchor = Math.abs(c)<0.2 ? "middle" : c>0 ? "start" : "end";
      g += `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="var(--line)" stroke-width="1"/>`;
      g += `<text x="${lx}" y="${ly+(Math.sin(ang(i))>0.5?10:Math.sin(ang(i))<-0.5?-2:4)}" text-anchor="${anchor}">${RADAR_T[k]}</text>`;
    });
    units.forEach((u,j)=>{
      const col = SW[j%SW.length];
      const pts = RADAR.map((k,i)=>pt(i,score[u.key][k]));
      g += `<polygon class="cmpSeries" points="${pts.map(p=>p.join(",")).join(" ")}" fill="${col}" fill-opacity="0.12" stroke="${col}" stroke-width="2"><title>${esc(u.label)}: ${RADAR.map(k=>RADAR_T[k]+" "+score[u.key][k].toFixed(0)).join(", ")}</title></polygon>`;
      pts.forEach(p=>{ g += `<circle cx="${p[0]}" cy="${p[1]}" r="2.8" fill="${col}"/>`; });
    });
    return `<svg id="cmpRadar" viewBox="0 0 ${W} ${H}" width="100%" data-s="max-width:520px;display:block;margin:0 auto" role="img" aria-label="Sites compared on six measures, scaled 0 to 100">${g}</svg>
      <div class="legend">${units.map((u,j)=>`<span><i data-s="background:${SW[j%SW.length]}"></i>${esc(u.label)}</span>`).join("")}</div>`;
  }

  function getRankKey(){
    const v = load("cmp.rank");
    return M.some(m=>m.k===v) ? v : "cp";
  }

  document.addEventListener("change", e=>{
    if(e.target && e.target.id==="cmpRank"){ store("cmp.rank", e.target.value); render(); const n=document.getElementById("cmpRank"); if(n) n.focus(); }
  });

  BI.add({
    id: "compare",
    label: "Compare",
    formulas: {
      cmpRev: "Revenue = sum of invoice values in the period (before tax)",
      cmpGrowth: "Growth = (Revenue this period - Revenue previous period of the same length) / Revenue previous period",
      cmpSla: "Quote SLA % = Quotes sent within 30 minutes / All quotes",
      cmpWin: "Win rate = Won deals / (Won + Lost deals), all closed deals on record (deals carry no period date)",
      cmpOntime: "On-time % = average of the monthly on-time delivery figures in the period",
      cmpNps: "NPS = average of the monthly customer score (net promoter score) figures in the period",
      cmpIndex: "Index = value / average of all rows x 100 (100 = average). For DSO, lower is better: index = average / value x 100. For growth: index = 100 + (growth - average growth) in percentage points",
      cmpRank: "Rank = position when rows are sorted best first (1 = best)",
      cmpQuart: "Quartile = rank / number of rows, split in four: top quarter green, second neutral, third amber, bottom red",
      cmpRadar: "Radar score = (value - lowest site) / (highest site - lowest site) x 100; for DSO it is flipped so lower DSO scores higher. One site alone scores 100"
    },
    render: () => {
      const ms = months(), pms = prevMonths();
      const rk = getRankKey(), rm = M.find(m=>m.k===rk);

      const sites = D.sites.map((s,j)=>({key:s.id, label:s.name, s, v: measure(f=>f.site===s.id, d=>d.site===s.id, ms, pms), b:{}})).filter(u=>u.v);
      const pcs = [];
      D.sites.forEach(s=>s.pcs.forEach(pc=>{
        const v = measure(f=>f.site===s.id&&f.pc===pc, d=>d.site===s.id&&d.pc===pc, ms, pms);
        if(v) pcs.push({key:s.id+"|"+pc, label:s.name+" · "+pc, s, pc, v, b:{}});
      }));
      if(!sites.length) return `<section class="p w12"><h2>Compare</h2><p class="note">No figures for this period yet. Try a longer period.</p></section>`;
      const sAvg = bench(sites), pAvg = bench(pcs);

      const scope = `Every site on this page · last ${ms.length} months · site, profit-centre and country filters are not applied here so all can be compared`;
      const head = [{t:"Site"}].concat(M.map(m=>({t:m.t, f:m.f})));
      const sRows = sites.map(u=>[`<span data-drill="site:${esc(u.s.id)}" data-s="cursor:pointer" title="Click to filter to this site">${esc(u.label)}</span>${st.site===u.s.id?' <span class="chip">selected</span>':""}`].concat(M.map(m=>cell(u,m))));
      const sFoot = ["Average"].concat(M.map(m=>avgCell(sAvg[m.k],m)));
      const pHead = [{t:"Site · profit centre"}].concat(M.map(m=>({t:m.t, f:m.f})));
      const pRows = pcs.map(u=>[`<span data-drill="site:${esc(u.s.id)}|pc:${esc(u.pc)}|tab:profit" data-s="cursor:pointer" title="Open this profit centre">${esc(u.label)}</span>`].concat(M.map(m=>cell(u,m))));
      const pFoot = ["Average"].concat(M.map(m=>avgCell(pAvg[m.k],m)));

      // League table: profit centres ranked by the chosen measure; n/a goes last.
      const league = pcs.slice().sort((a,b)=>{
        const ba=a.b[rk], bb=b.b[rk];
        if(!ba && !bb) return 0; if(!ba) return 1; if(!bb) return -1;
        return ba.rank-bb.rank || a.label.localeCompare(b.label);
      });
      const lRows = league.map((u,i)=>{
        const b = u.b[rk];
        return [b ? "#"+b.rank : "–", `<span data-drill="site:${esc(u.s.id)}|pc:${esc(u.pc)}|tab:profit" data-s="cursor:pointer" title="Open this profit centre">${esc(u.label)}</span>`,
          cell(u, rm), b ? b.idx.toFixed(0) : "n/a", money(u.v.rev), pctv(u.v.cp)];
      });
      const sel = `<label class="note" for="cmpRank">Rank by </label><select id="cmpRank">${M.map(m=>`<option value="${m.k}"${m.k===rk?" selected":""}>${m.t}</option>`).join("")}</select>`;

      // Tiles
      const bestBy = (arr,k)=>arr.filter(u=>u.b[k]).sort((a,b)=>a.b[k].rank-b.b[k].rank)[0];
      const bs = bestBy(sites,"cp"), bp = bestBy(pcs,rk);
      const cps = pcs.map(u=>u.v.cp).filter(v=>v!==null);
      const gap = cps.length ? Math.max(...cps)-Math.min(...cps) : 0;
      const tiles = [
        ["Units compared", `${sites.length} sites · ${pcs.length} PCs`, `last ${ms.length} months`, "cmpRank"],
        ["Best site, contribution %", bs ? esc(bs.label) : "n/a", bs ? pct(bs.v.cp)+" · index "+bs.b.cp.idx.toFixed(0) : "no data", "cp"],
        ["Top profit centre, "+esc(rm.t), bp ? esc(bp.label) : "n/a", bp ? rm.fmt(bp.v[rk])+" · index "+bp.b[rk].idx.toFixed(0) : "no data", rm.f],
        ["Contribution % gap", (gap*100).toFixed(1)+" pts", "best minus worst profit centre", "cp"]
      ];

      return `<div class="tiles">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]]||"")}"><span class="k">${t[0]}</span><span class="v" data-s="font-size:1.05rem">${t[1]}</span><span class="d flat">${t[2]}</span></div>`).join("")}</div>
  <section class="p w12"><h2>Sites side by side</h2><p class="sub">${scope}</p>
    <p class="note">Each cell: the value (coloured by quarter: green top, neutral second, amber third, red bottom), then its index (100 = average) and rank (#1 = best). DSO: lower is better.</p>
    ${table("tCmpSites", head, sRows, sFoot)}</section>
  <section class="p w8"><h2>Sites on six measures</h2><p class="sub">0 = weakest site, 100 = strongest site on each measure · ${esc(FX.cmpRadar)}</p>${radar(sites)}</section>
  <section class="p w4"><h2>League table</h2><p class="sub">Profit centres across all sites, best first · click one to open it</p>
    <div class="row" data-s="margin-bottom:8px">${sel}</div>
    ${hbars(league.slice(0,8).filter(u=>u.v[rk]!==null).map(u=>({k:u.label, v:rk==="dso"||rk==="rev"||rk==="ontime"||rk==="nps"?u.v[rk]:u.v[rk]*100, c:SW[Math.max(0,sites.findIndex(x=>x.s.id===u.s.id))%SW.length], drill:"site:"+u.s.id+"|pc:"+u.pc+"|tab:profit"})), v=>rk==="rev"?money(v):rk==="dso"?v.toFixed(0)+" d":rk==="ontime"?v.toFixed(1)+"%":rk==="nps"?v.toFixed(1):v.toFixed(1)+"%")}
    <p class="note">Top 8 shown; bar colour = site colour in the radar. Ranked by ${esc(rm.t)}${rm.better==="lower"?" (lower is better)":""}.</p></section>
  <section class="p w12"><h2>League table: profit centres by ${esc(rm.t)}</h2><p class="sub">${scope}</p>
    ${table("tCmpLeague", [{t:"Rank",f:"cmpRank"},{t:"Site · profit centre"},{t:rm.t,f:rm.f},{t:"Index",f:"cmpIndex"},{t:"Revenue",f:"cmpRev"},{t:"Contribution %",f:"cp"}], lRows)}</section>
  <section class="p w12"><h2>Every profit centre across sites</h2><p class="sub">${scope} · ranks are across all ${pcs.length} profit centres</p>
    ${table("tCmpPcs", pHead, pRows, pFoot)}</section>`;
    }
  });
})();

/* module: countries.js */
// Countries tab: one view per country of market, our sales, share, deals and an attractiveness score.
// Respects the site and country filters (market rows have no profit centre; deals also follow the profit-centre filter). Demo data only.
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const SORTS = {att:"Attractiveness", size:"Market size", share:"Our share", growth:"Market growth"};
  let sortBy = "att";
  try { const s = load("ctySort"); if (s && SORTS[s]) sortBy = s; } catch(e) {}

  // Fixed operating notes per country (rough demo notes only).
  const NOTES = {
    "India": {cur:"INR", tax:"18% GST on most services"},
    "United Arab Emirates": {cur:"AED", tax:"5% VAT"},
    "Hong Kong": {cur:"HKD", tax:"No VAT or GST"},
    "Canada": {cur:"CAD", tax:"5% GST plus provincial sales tax where it applies"}
  };
  const noteOf = c => NOTES[c] || {cur:"Not set", tax:"No note yet"};

  // Countries in scope: the side's list, narrowed by the site and country filters.
  function scopeCountries(){
    const sites = D.sites.filter(s => st.site === "all" || s.id === st.site);
    const allowed = new Set(sites.flatMap(s => s.countries || D.countries));
    return D.countries.filter(c => allowed.has(c) && (st.country === "all" || st.country === c));
  }

  function calc(){
    const M = mkt(), DL = deals();
    const rows = scopeCountries().map(c => {
      const m = M.filter(r => r.country === c);
      const size = fin(sum(m, r => r.size));
      const ours = fin(sum(m, r => r.size * r.ours));
      const comp = [0,1,2,3,4].map(i => fin(sum(m, r => r.size * (r.comp[i] || 0))));
      const growth = size > 0 ? fin(sum(m, r => r.size * r.growth) / size) : 0;
      const off = m.filter(r => r.offered);
      const offSize = sum(off, r => r.size);
      const pidx = offSize > 0 ? fin(sum(off, r => r.size * r.price_index) / offSize) : null;
      const d = DL.filter(x => x.country === c);
      const open = d.filter(x => x.stage !== "Won" && x.stage !== "Lost");
      const won = d.filter(x => x.stage === "Won"), lost = d.filter(x => x.stage === "Lost");
      const segs = {};
      m.forEach(r => { segs[r.segment] = (segs[r.segment] || 0) + fin(r.size); });
      return {c, size, ours, share: size > 0 ? fin(ours / size) : 0, comp, growth, pidx,
        openV: fin(sum(open, x => x.amount)), openN: open.length, wonV: fin(sum(won, x => x.amount)),
        winN: won.length, lostN: lost.length, win: (won.length + lost.length) ? won.length / (won.length + lost.length) : 0,
        segs, has: m.length > 0 || d.length > 0};
    }).filter(r => r.has);
    // Normalise across the countries shown (min-max; if all equal, each counts as 1).
    const norm = (v, lo, hi) => hi > lo ? (v - lo) / (hi - lo) : 1;
    const sz = rows.map(r => r.size), gr = rows.map(r => r.growth);
    const sLo = Math.min(...sz), sHi = Math.max(...sz), gLo = Math.min(...gr), gHi = Math.max(...gr);
    rows.forEach(r => {
      r.nSize = fin(norm(r.size, sLo, sHi));
      r.nGrowth = fin(norm(r.growth, gLo, gHi));
      r.att = fin(0.5 * r.nSize + 0.3 * r.nGrowth + 0.2 * (1 - r.share));
    });
    return rows;
  }

  const attPill = a => a >= 0.66 ? ["g","High"] : a >= 0.4 ? ["a","Medium"] : ["r","Low"];
  const pidxTxt = p => p === null ? "No offer" : p.toFixed(1);

  // Mini 100% bar: our share, competitors A to E, everyone else.
  function shareBar(r){
    const parts = [{n:"Us", v:r.share, c:"var(--c1)"}];
    const cc = ["var(--c3)","var(--c4)","var(--c5)","var(--c2)","var(--mut)"];
    r.comp.forEach((v, i) => parts.push({n:"Competitor " + "ABCDE"[i], v: r.size > 0 ? v / r.size : 0, c: cc[i]}));
    const used = sum(parts, p => p.v);
    parts.push({n:"Others", v: Math.max(0, 1 - used), c:"var(--line)"});
    let x = 0, g = "";
    parts.forEach(p => { const w = fin(p.v) * 200; if (w > 0) g += `<rect x="${x.toFixed(2)}" y="0" width="${w.toFixed(2)}" height="10" fill="${p.c}"><title>${esc(p.n)}: ${pct(p.v)}</title></rect>`; x += w; });
    return `<svg viewBox="0 0 200 10" width="100%" height="10" preserveAspectRatio="none" role="img" aria-label="Market split for ${esc(r.c)}: us ${pct(r.share)}" data-s="display:block;border-radius:3px;overflow:hidden">${g}</svg>`;
  }

  // Stacked bars: market by segment, one bar per country, drawn to one scale.
  function stack(rows){
    const tot = {};
    rows.forEach(r => Object.entries(r.segs).forEach(([k, v]) => tot[k] = (tot[k] || 0) + v));
    const order = Object.keys(tot).sort((a, b) => tot[b] - tot[a]);
    const top = order.slice(0, 5), rest = order.slice(5);
    const cols = ["var(--c1)","var(--c2)","var(--c3)","var(--c4)","var(--c5)"];
    const keys = top.map((k, i) => ({k, c: cols[i], segs:[k]}));
    if (rest.length) keys.push({k: "Other segments (" + rest.length + ")", c: "var(--c6)", segs: rest});
    const W = 640, L = 8, R = 70, rowH = 46, T = 8, B = 22, w = W - L - R;
    const H = T + rows.length * rowH + B;
    const mx = niceMax(Math.max(1, ...rows.map(r => r.size)));
    const x = v => L + v / mx * w;
    let g = "";
    for (let i = 0; i <= 4; i++) { const v = mx * i / 4; g += `<line class="gl" x1="${x(v)}" x2="${x(v)}" y1="${T}" y2="${H - B}"/><text x="${x(v)}" y="${H - 6}" text-anchor="${i === 0 ? "start" : i === 4 ? "end" : "middle"}">${money(v)}</text>`; }
    rows.forEach((r, i) => {
      const y0 = T + i * rowH;
      g += `<text x="${L}" y="${y0 + 13}" data-s="fill:var(--ink)">${esc(r.c)}</text>`;
      let acc = 0;
      keys.forEach(k => {
        const v = fin(sum(k.segs, s => r.segs[s] || 0));
        if (v <= 0) return;
        g += `<rect data-drill="country:${esc(r.c)}" x="${x(acc).toFixed(2)}" y="${y0 + 18}" width="${(x(acc + v) - x(acc)).toFixed(2)}" height="20" fill="${k.c}"><title>${esc(r.c)} · ${esc(k.k)}: ${money(v)}</title></rect>`;
        acc += v;
      });
      g += `<text x="${(x(acc) + 4).toFixed(2)}" y="${y0 + 32}">${money(r.size)}</text>`;
    });
    return `<svg id="ctyStack" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Market size by segment for each country">${g}</svg>
      <div class="legend">${keys.map(k => `<span><i data-s="background:${k.c}"></i>${esc(k.k)}</span>`).join("")}</div>`;
  }

  // Sort control (kept in this browser only).
  document.addEventListener("change", e => {
    if (e.target && e.target.id === "ctySort") { sortBy = SORTS[e.target.value] ? e.target.value : "att"; store("ctySort", sortBy); render(); }
  });

  BI.add({
    id: "countries",
    label: "Countries",
    formulas: {
      ctySize: "Market size = sum of yearly market size for every segment in the country",
      ctyOurs: "Our sales = sum of (segment market size x our share)",
      ctyShare: "Our share = Our sales / Market size",
      ctyGrowth: "Market growth = market-size-weighted average of segment growth",
      ctyOpen: "Open deals = value of deals not yet Won or Lost",
      ctyWon: "Won value = value of deals marked Won",
      ctyWin: "Win rate = Won deals / (Won + Lost deals), counted by number of deals",
      ctyPidx: "Average price index = market-size-weighted price index over segments we offer (100 = at market)",
      ctyNorm: "Normalised value = (value - lowest) / (highest - lowest) across the countries shown; if they are all equal, it counts as 1",
      ctyAtt: "Country attractiveness = 0.5 x normalised market size + 0.3 x normalised growth + 0.2 x (1 - our share)",
      ctyBand: "Attractiveness band: High 0.66 or more; Medium 0.40 to 0.65; Low under 0.40"
    },
    render: () => {
      const rows = calc();
      const scope = (st.site === "all" ? "All sites on this side" : esc(siteName(st.site))) + " · " + (st.country === "all" ? "all countries" : esc(st.country));
      if (!rows.length) {
        return `<section class="p w12"><h2>Countries</h2><p class="sub">${scope}</p><p>No market or deal records for these filters. Try another site or country, or press Clear all.</p></section>`;
      }
      const key = {att: r => r.att, size: r => r.size, share: r => r.share, growth: r => r.growth}[sortBy];
      rows.sort((a, b) => key(b) - key(a) || a.c.localeCompare(b.c));
      const tSize = sum(rows, r => r.size), tOurs = sum(rows, r => r.ours);
      const tOpen = sum(rows, r => r.openV), tWon = sum(rows, r => r.wonV);
      const tWinN = sum(rows, r => r.winN), tLostN = sum(rows, r => r.lostN);
      const best = rows.slice().sort((a, b) => b.att - a.att)[0];
      const tGrowth = tSize > 0 ? sum(rows, r => r.size * r.growth) / tSize : 0;

      const tiles = [
        ["Countries shown", String(rows.length), `<span class="flat">${scope}</span>`, "ctyAtt"],
        ["Market size, yearly", money(tSize), `<span class="${tGrowth >= 0 ? "up" : "down"}">${pct(tGrowth)} market growth</span>`, "ctySize"],
        ["Our sales, yearly", money(tOurs), `<span class="flat">${pct(tSize > 0 ? tOurs / tSize : 0)} share</span>`, "ctyOurs"],
        ["Open deals", money(tOpen), `<span class="flat">${sum(rows, r => r.openN)} deals</span>`, "ctyOpen"],
        ["Won value", money(tWon), `<span class="flat">win rate ${pct((tWinN + tLostN) ? tWinN / (tWinN + tLostN) : 0)}</span>`, "ctyWin"],
        ["Most attractive", esc(best.c), `<span class="pill ${attPill(best.att)[0]}">${attPill(best.att)[1]}</span> score ${best.att.toFixed(2)}`, "ctyAtt"]
      ];

      const cards = rows.map(r => {
        const [pc, pt] = attPill(r.att);
        return `<button type="button" class="tile" data-drill="country:${esc(r.c)}" title="Click to filter to ${esc(r.c)} (click again to clear)" data-s="text-align:left;font:inherit;color:var(--ink);gap:6px">
          <span class="row" data-s="justify-content:space-between;width:100%"><strong>${esc(r.c)}</strong><span class="pill ${pc}" title="${esc(FX.ctyAtt)}">${pt} ${r.att.toFixed(2)}</span></span>
          <span class="note">Market ${money(r.size)} · ours ${money(r.ours)}</span>
          ${shareBar(r)}
          <span class="note">Share ${pct(r.share)} · growth <span class="${r.growth >= 0 ? "up" : "down"}">${pct(r.growth)}</span></span>
          <span class="note">Open ${money(r.openV)} · won ${money(r.wonV)} · win rate ${pct(r.win)}</span>
          <span class="note">Price index ${pidxTxt(r.pidx)} · ${esc(noteOf(r.c).cur)}</span>
        </button>`;
      }).join("");

      const cmpRows = rows.map(r => {
        const [pc, pt] = attPill(r.att);
        return [`<button type="button" class="lnk" data-drill="country:${esc(r.c)}">${esc(r.c)}</button>`, money(r.size), money(r.ours), pct(r.share),
          `<span class="${r.growth >= 0 ? "up" : "down"}">${pct(r.growth)}</span>`, money(r.openV), money(r.wonV), pct(r.win), pidxTxt(r.pidx),
          r.nSize.toFixed(2), r.nGrowth.toFixed(2), `<span class="pill ${pc}">${pt} ${r.att.toFixed(2)}</span>`];
      });
      const cmpFoot = ["All shown", money(tSize), money(tOurs), pct(tSize > 0 ? tOurs / tSize : 0), pct(tGrowth), money(tOpen), money(tWon),
        pct((tWinN + tLostN) ? tWinN / (tWinN + tLostN) : 0), "", "", "", ""];

      const noteRows = rows.map(r => { const n = noteOf(r.c); return [esc(r.c), esc(n.cur), esc(n.tax), `<span class="pill a">Demo note, check with finance</span>`]; });

      const sortSel = `<label class="f" for="ctySort">Sort countries by<select id="ctySort">${Object.entries(SORTS).map(([k, t]) => `<option value="${k}"${k === sortBy ? " selected" : ""}>${t}</option>`).join("")}</select></label>`;

      return `<div class="tiles t3">${tiles.map(t => `<div class="tile" title="${esc(FX[t[3]] || "")}"><span class="k">${t[0]}</span><span class="v" data-s="overflow:hidden;text-overflow:ellipsis">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>
  <section class="p w12"><div class="row" data-s="justify-content:space-between"><div><h2>Country cards</h2><p class="sub">${scope} · click a card to filter to that country · bar shows the market split: us, competitors A to E, others</p></div>${sortSel}</div>
    <div id="ctyCards" data-s="display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(min(100%,230px),1fr))">${cards}</div>
    <div class="legend"><span><i data-s="background:var(--c1)"></i>Us</span><span><i data-s="background:var(--c3)"></i>A</span><span><i data-s="background:var(--c4)"></i>B</span><span><i data-s="background:var(--c5)"></i>C</span><span><i data-s="background:var(--c2)"></i>D</span><span><i data-s="background:var(--mut)"></i>E</span><span><i data-s="background:var(--line)"></i>Others</span></div></section>
  <section class="p w12"><h2>Market by segment, per country</h2><p class="sub">${scope} · yearly market size · one scale for all bars · click a bar to filter</p>${stack(rows)}</section>
  <section class="p w12"><h2>Country comparison</h2><p class="sub">${scope} · sorted by ${SORTS[sortBy].toLowerCase()} · deals also follow the profit-centre filter</p>${table("tCtyCmp", [{t:"Country"},{t:"Market size",f:"ctySize"},{t:"Our sales",f:"ctyOurs"},{t:"Share",f:"ctyShare"},{t:"Growth",f:"ctyGrowth"},{t:"Open deals",f:"ctyOpen"},{t:"Won value",f:"ctyWon"},{t:"Win rate",f:"ctyWin"},{t:"Price index",f:"ctyPidx"},{t:"Size (0-1)",f:"ctyNorm"},{t:"Growth (0-1)",f:"ctyNorm"},{t:"Attractiveness",f:"ctyAtt"}], cmpRows, cmpFoot)}
    <p class="note">${esc(FX.ctyAtt)}. ${esc(FX.ctyBand)}.</p></section>
  <section class="p w12"><h2>Operating notes</h2><p class="sub">Rough demo notes only. Rates change; check with finance before quoting.</p>${table("tCtyNotes", [{t:"Country"},{t:"Currency"},{t:"Sales tax (rough)"},{t:"Status"}], noteRows)}</section>`;
    }
  });
})();

/* module: customers.js */
/* Customers and concentration: who buys from us, and how much we lean on a few accounts.
   Won deals = bookings. Won + open deals (everything not Lost) = relationship value. */
(function(){
  const STG=["Lead","Qualified","Proposal","Negotiation","Won"];
  const fin=v=>isFinite(v)?v:0;
  const div=(a,b)=>b?fin(a/b):0;

  /* Country bars: keep the Country select in step with the click (the shared drill only sets the value). */
  function pickCountry(v){
    st.country=st.country===v?"all":v;
    const sel=document.getElementById("fCountry");
    if(sel){if(![...sel.options].some(o=>o.value===st.country))st.country="all";sel.value=st.country;}
    try{localStorage.setItem("bi.country",st.country)}catch(e){}
    render();
  }
  function hit(e){const el=e.target.closest&&e.target.closest("#custCountry [data-drill^='country:']");return el?el.dataset.drill.slice(8):null;}
  document.addEventListener("click",e=>{const v=hit(e);if(v===null)return;e.stopImmediatePropagation();e.preventDefault();pickCountry(v);},true);
  document.addEventListener("keydown",e=>{if(e.key!=="Enter"&&e.key!==" ")return;const v=hit(e);if(v===null)return;e.stopImmediatePropagation();e.preventDefault();pickCountry(v);},true);

  function model(){
    const dl=deals();
    const rel=dl.filter(d=>d.stage!=="Lost"), won=dl.filter(d=>d.stage==="Won");
    const relV=sum(rel,d=>d.amount), wonV=sum(won,d=>d.amount);
    const acc={};
    dl.forEach(d=>{const a=acc[d.account]||(acc[d.account]={k:d.account,country:d.country,won:0,open:0,n:0,mix:{}});
      if(d.stage==="Won")a.won+=d.amount;else if(d.stage!=="Lost")a.open+=d.amount;
      a.n++;a.mix[d.stage]=(a.mix[d.stage]||0)+1;});
    let cum=0;
    const abc=Object.values(acc).map(a=>(a.v=a.won+a.open,a)).filter(a=>a.v>0).sort((x,y)=>y.v-x.v||x.k.localeCompare(y.k)).map(a=>{
      const before=cum;cum+=div(a.v,relV);a.share=div(a.v,relV);a.cum=Math.min(1,cum);
      a.cls=before<0.8-1e-9?"A":before<0.95-1e-9?"B":"C";return a;});
    const wonBy=Object.values(acc).map(a=>a.won).filter(v=>v>0).sort((x,y)=>y-x);
    const top5=div(sum(wonBy.slice(0,5)),wonV);
    const rep=div(sum(won.filter(d=>d.source==="Repeat buyer"),d=>d.amount),wonV);
    const hhi=fin(sum(abc,a=>a.share*a.share));
    return {dl,rel,won,relV,wonV,abc,top5,rep,hhi,active:abc.length,avgWon:div(wonV,won.length)};
  }

  function pareto(rows,total){
    const W=640,H=260,L=58,R=46,T=14,B=30,w=W-L-R,h=H-T-B,n=rows.length;
    const mx=niceMax(Math.max(0,...rows.map(r=>r.v)));const bw=w/Math.max(n,1);
    const y=v=>T+h-fin(v/mx)*h, yc=p=>T+h-p*h, xc=i=>L+i*bw+bw/2;
    const col={A:"var(--c1)",B:"var(--c5)",C:"var(--c6)"};let g="";
    for(let i=0;i<=4;i++){const v=mx*i/4;g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${money(v)}</text><text x="${W-R+6}" y="${yc(i/4)+4}">${i*25}%</text>`;}
    g+=`<line x1="${L}" x2="${W-R}" y1="${yc(0.8)}" y2="${yc(0.8)}" stroke="var(--mut)" stroke-dasharray="3 3"/><text x="${W-R-4}" y="${yc(0.8)-4}" text-anchor="end">80%</text>`;
    rows.forEach((r,i)=>{g+=`<rect x="${L+i*bw+bw*.16}" y="${y(r.v)}" width="${bw*.68}" height="${T+h-y(r.v)}" fill="${col[r.cls]}" rx="2"><title>${i+1}. ${esc(r.k)}: ${money(r.v)} (class ${r.cls})</title></rect><text x="${xc(i)}" y="${H-10}" text-anchor="middle">${i+1}</text>`;});
    if(n){g+=`<polyline points="${rows.map((r,i)=>xc(i)+","+yc(r.cum)).join(" ")}" fill="none" stroke="var(--c4)" stroke-width="2"/>`;
      rows.forEach((r,i)=>g+=`<circle cx="${xc(i)}" cy="${yc(r.cum)}" r="3" fill="var(--c4)"><title>Running total after ${i+1}: ${pct(r.cum)}</title></circle>`);}
    return `<svg id="custPareto" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Pareto chart: value of the top ${n} accounts with running total share">${g}</svg>
    <div class="legend"><span><i data-s="background:var(--c1)"></i>Class A</span><span><i data-s="background:var(--c5)"></i>Class B</span><span><i data-s="background:var(--c6)"></i>Class C</span><span><i data-s="background:var(--c4)"></i>Running total % (right scale)</span></div>
    <p class="note">Bars are numbered by rank; hover a bar for the account. Left scale is value (${money(total)} in all), right scale is the running share.</p>`;
  }

  function view(){
    const M=model();
    const hp=M.hhi<0.15?"g":M.hhi<0.25?"a":"r";
    const tiles=`<div class="tiles">
     <div class="tile" title="${esc(FX.custActive)}"><span class="k">Active accounts</span><span class="v">${M.active}</span><span class="d flat">${M.rel.length} live or won deals</span></div>
     <div class="tile" title="${esc(FX.custTop5)}"><span class="k">Top 5 share of won value</span><span class="v">${pct(M.top5)}</span><span class="d ${M.top5>0.6?"down":"flat"}">${money(M.wonV)} won in all</span></div>
     <div class="tile" title="${esc(FX.custAvgWon)}"><span class="k">Average won deal</span><span class="v">${money(M.avgWon)}</span><span class="d flat">${M.won.length} won deals</span></div>
     <div class="tile" title="${esc(FX.custRepeat)}"><span class="k">Repeat-buyer share</span><span class="v">${pct(M.rep)}</span><span class="d flat">of won value</span></div></div>`;
    if(!M.relV) return tiles+`<section class="p w12" id="custEmpty"><h2>No customers to show</h2><p class="sub">No won or open deals match the filters above.</p><p>Try another country or profit centre, or clear the filters to see every account.</p></section>`;
    const cls=["A","B","C"].map(c=>{const x=M.abc.filter(a=>a.cls===c);return [`<span class="pill ${c==="A"?"g":c==="B"?"a":"r"}">${c}</span>`,x.length,pct(div(x.length,M.abc.length)),money(sum(x,a=>a.v)),pct(div(sum(x,a=>a.v),M.relV))];});
    const mix=a=>STG.filter(s=>a.mix[s]).map(s=>s+" "+a.mix[s]).join(" · ")||"-";
    const abcRows=M.abc.map((a,i)=>[i+1,esc(a.k),esc(a.country),money(a.won),money(a.open),money(a.v),pct(a.share),pct(a.cum),`<span class="pill ${a.cls==="A"?"g":a.cls==="B"?"a":"r"}">${a.cls}</span>`,esc(mix(a))]);
    const ctry=[...new Set(M.rel.map(d=>d.country))].map(c=>({k:c,v:sum(M.rel.filter(d=>d.country===c),d=>d.amount),c:"var(--c3)",drill:"country:"+c})).sort((a,b)=>b.v-a.v);
    const srcs=[...new Set(M.dl.map(d=>d.source))].sort().map(s=>{const x=M.dl.filter(d=>d.source===s);const w=x.filter(d=>d.stage==="Won"),l=x.filter(d=>d.stage==="Lost").length;const wv=sum(w,d=>d.amount);
      return {s,n:x.length,w:w.length,wv,wr:div(w.length,w.length+l)};}).sort((a,b)=>b.wv-a.wv);
    const hhiTxt={g:"Spread out: no single account can hurt us much.",a:"Some reliance on a few accounts. Grow the B and C accounts.",r:"High reliance on a few accounts. Losing one would hurt. Win more mid-size accounts."}[hp];
    return tiles+`
    <section class="p w8"><h2>Top 15 accounts (Pareto)</h2><p class="sub">Won + open value per account, biggest first, with the running total share</p>${pareto(M.abc.slice(0,15),M.relV)}</section>
    <section class="p w4"><h2>Concentration risk</h2><p class="sub" title="${esc(FX.custHhi)}">${esc(FX.custHhi)}</p>
     <div class="row"><span class="tile" data-s="flex:1"><span class="k">Concentration index</span><span class="v">${M.hhi.toFixed(3)}</span><span class="d"><span class="pill ${hp}">${ragTxt[hp]}</span></span></span></div>
     <p>${esc(hhiTxt)}</p>
     <p class="note">Green below 0.15 · amber 0.15 to 0.25 · red 0.25 or more. Same as about ${fin(M.hhi?1/M.hhi:0).toFixed(1)} equal-size accounts.</p>
     ${table("tCustCls",[{t:"Class",f:"custAbc"},{t:"Accounts"},{t:"% accounts"},{t:"Value"},{t:"% value"}],cls)}</section>
    <section class="p w12"><h2>ABC list of accounts</h2><p class="sub">${esc(FX.custAbc)}</p>
     ${table("tCustAbc",[{t:"Rank"},{t:"Account"},{t:"Country"},{t:"Won",f:"custWon"},{t:"Open"},{t:"Won + open",f:"custRel"},{t:"Share"},{t:"Cumulative %",f:"custCum"},{t:"Class",f:"custAbc"},{t:"Stage mix"}],abcRows,["","Total",M.abc.length+" accounts",money(M.wonV),money(M.relV-M.wonV),money(M.relV),pct(1),"","",""])}</section>
    <section class="p" id="custCountry"><h2>Value by country</h2><p class="sub">Won + open value · click a country to filter the whole page (click again to clear)</p>${hbars(ctry,money)}</section>
    <section class="p"><h2>Lead source mix</h2><p class="sub">${esc(FX.win)}</p>
     ${table("tCustSrc",[{t:"Lead source"},{t:"Deals"},{t:"Won deals"},{t:"Won value",f:"custWon"},{t:"Win rate",f:"win"}],srcs.map(x=>[esc(x.s),x.n,x.w,money(x.wv),pct(x.wr)]),["Total",M.dl.length,M.won.length,money(M.wonV),pct(div(M.won.length,M.won.length+M.dl.filter(d=>d.stage==="Lost").length))])}</section>`;
  }

  BI.add({id:"customers",label:"Customers",formulas:{
    custWon:"Bookings = sum of Won deal values",
    custRel:"Relationship value = sum of Won + open deal values (all deals not Lost)",
    custActive:"Active accounts = accounts with at least one Won or open deal",
    custTop5:"Top 5 share = Won value of the 5 biggest accounts / all Won value",
    custAvgWon:"Average won deal = Won value / number of Won deals",
    custRepeat:"Repeat-buyer share = Won value from lead source Repeat buyer / all Won value",
    custCum:"Cumulative % = running total of account value, biggest first / all relationship value",
    custAbc:"ABC class = A for accounts in the first 80% of cumulative value, B for the next 15%, C for the rest",
    custHhi:"Concentration index = sum of (each account's share of relationship value) squared; 1 means one account has everything"
  },render:view});
})();

/* module: dataquality.js */
// Data checks tab: data quality and audit evidence. Runs fixed checks over the page data D,
// proves totals tie, and shows a fingerprint of the data. Respects site, profit-centre, country and period filters.
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const SDS = ["2", "2.5", "3"];
  let sdPick = (()=>{ const v = load("dq.sd"); return SDS.includes(v) ? v : "2.5"; })();
  let onlyCheck = "all";
  const TABS = {overview:1, profit:1, pipeline:1, market:1, outcomes:1};

  // 32-bit FNV-1a over the UTF-8 bytes of JSON.stringify(D). Cached: D never changes on the page.
  let fpCache = null;
  function fingerprint(){
    if(fpCache) return fpCache;
    const s = JSON.stringify(D);
    let bytes;
    try { bytes = new TextEncoder().encode(s); } catch(e){ bytes = Array.from(s, c=>c.charCodeAt(0)&255); }
    let h = 0x811c9dc5;
    for(let i=0;i<bytes.length;i++){ h ^= bytes[i]; h = Math.imul(h, 0x01000193) >>> 0; }
    fpCache = {hex: ("00000000"+(h>>>0).toString(16)).slice(-8).toUpperCase(), len: bytes.length};
    return fpCache;
  }

  // KPI sane ranges by unit.
  const RANGE = {"%":[0,100], "days":[0,365], "pts":[-100,100], "count":[0,1000], "h":[0,200]};

  function scopeSites(){ return D.sites.filter(s=>st.site==="all"||s.id===st.site); }
  function scopePcs(s){ return s.pcs.filter(p=>st.pc==="all"||p===st.pc); }

  function runChecks(){
    const ms = months();
    const cur = D.months[D.months.length-1] || "";
    const k = +sdPick;
    const F = facts(ms);
    const dl = deals();
    const mk = mkt();
    const kp = D.kpis.filter(x=>st.site==="all"||x.site===st.site);
    const fIssue = (f, val) => ({site:f.site, pc:f.pc, item:f.m, val, drill:`site:${f.site}|pc:${f.pc}|tab:profit`});
    const C = [];
    const add = (id, name, tested, issues, sev, fix) => C.push({id, name, tested, issues, sev, fix});

    // 1. Completeness: every site x profit centre x month in the period has a fact row.
    const miss = [];
    let exp = 0;
    scopeSites().forEach(s=>scopePcs(s).forEach(pc=>ms.forEach(m=>{
      exp++;
      if(!D.facts.some(f=>f.site===s.id&&f.pc===pc&&f.m===m)) miss.push({site:s.id, pc, item:m, val:"missing row", drill:`site:${s.id}|pc:${pc}|tab:profit`});
    })));
    add("dqComplete", "Every site, profit centre and month has a row", exp, miss, "r", "Load the missing month from the order system, or enter zero with a note if the unit did not trade.");

    // 2. Negative or zero values.
    const neg = [];
    F.forEach(f=>{
      const bad = [];
      if(!(f.rev>0)) bad.push("revenue "+money(fin(f.rev)));
      if(!(f.budget>0)) bad.push("budget "+money(fin(f.budget)));
      ["cogs","opex","cash","recv"].forEach(c=>{ if(!(f[c]>=0)) bad.push(c+" "+money(fin(f[c]))); });
      ["orders","quotes","quotes_30"].forEach(c=>{ if(!(f[c]>=0)) bad.push(c+" "+fin(f[c])); });
      if(bad.length) neg.push(fIssue(f, bad.join(", ")));
    });
    add("dqNeg", "No negative or zero amounts", F.length, neg, "r", "Find the source entry; credit notes belong in their own line, not as negative revenue.");

    // 3. Quotes sent in 30 min cannot exceed all quotes.
    const q30 = F.filter(f=>fin(f.quotes_30)>fin(f.quotes)).map(f=>fIssue(f, `${f.quotes_30} in 30 min > ${f.quotes} quotes`));
    add("dqQ30", "Quotes within 30 min ≤ all quotes", F.length, q30, "r", "Check the quote log timestamps; a quote counted twice usually causes this.");

    // 4. Orders cannot exceed quotes.
    const oq = F.filter(f=>fin(f.orders)>fin(f.quotes)).map(f=>fIssue(f, `${f.orders} orders > ${f.quotes} quotes`));
    add("dqOrdQ", "Orders ≤ quotes", F.length, oq, "r", "Log a quote for every order, including repeat orders taken by phone.");

    // 5. Loss months: cost of sales above revenue.
    const loss = F.filter(f=>fin(f.cogs)>fin(f.rev)).map(f=>fIssue(f, `cost ${money(fin(f.cogs))} > revenue ${money(fin(f.rev))}`));
    add("dqLoss", "Cost of sales ≤ revenue (no loss months)", F.length, loss, "a", "Confirm the costs belong to this month; if real, review pricing for that profit centre.");

    // 6. Outliers: revenue more than k standard deviations from that profit centre's mean (all 12 months).
    const out = [];
    const stats = {};
    F.forEach(f=>{
      const key = f.site+"|"+f.pc;
      if(!stats[key]){
        const r = D.facts.filter(x=>x.site===f.site&&x.pc===f.pc).map(x=>fin(x.rev));
        const mean = r.length ? sum(r)/r.length : 0;
        const sd = r.length>1 ? Math.sqrt(sum(r,v=>(v-mean)*(v-mean))/(r.length-1)) : 0;
        stats[key] = {mean, sd};
      }
      const s = stats[key];
      const z = s.sd>0 ? (fin(f.rev)-s.mean)/s.sd : 0;
      if(Math.abs(z)>k) out.push({site:f.site, pc:f.pc, item:f.m, val:`revenue ${money(fin(f.rev))}, ${z.toFixed(1)} SD from mean ${money(s.mean)}`, drill:`site:${f.site}|pc:${f.pc}|tab:profit`});
    });
    add("dqOut", `Revenue within ${k} SD of its profit centre's mean`, F.length, out, "a", "Check the month for a one-off order, a missing invoice or a typing error.");

    // 7. Deals with close month in the past but still open.
    const open = dl.filter(d=>d.stage!=="Won"&&d.stage!=="Lost");
    const past = open.filter(d=>String(d.close)<cur).map(d=>({site:d.site, pc:d.pc, item:d.id, val:`${d.stage}, close ${d.close}`, drill:`site:${d.site}|pc:${d.pc}|tab:pipeline`}));
    add("dqPast", "Open deals have a close month not in the past", open.length, past, "r", "Ask the owner of each deal for a new close month, or mark it Lost.");

    // 8. Deals older than 180 days.
    const old = dl.filter(d=>fin(d.age)>180).map(d=>({site:d.site, pc:d.pc, item:d.id, val:`${fin(d.age)} days old, ${d.stage}`, drill:`site:${d.site}|pc:${d.pc}|tab:pipeline`}));
    add("dqOld", "No deal older than 180 days", dl.length, old, "a", "Close out or re-qualify deals that have been open for more than six months.");

    // 9. Market rows whose shares add to more than 100%.
    const shr = mk.map(m=>({m, t: fin(m.ours)+sum(m.comp||[],c=>fin(c))+fin(m.others)})).filter(x=>x.t>1.0005)
      .map(x=>({site:x.m.site, pc:"", item:x.m.segment+" · "+x.m.country, val:`shares add to ${pct(x.t)}`, drill:`site:${x.m.site}|tab:market`}));
    add("dqShare", "Market shares add to 100% or less", mk.length, shr, "r", "Re-check the market study figures; our share plus competitors plus others must not pass 100%.");

    // 10. KPI series outside a sane range.
    let kn = 0;
    const kb = [];
    kp.forEach(x=>{
      const r = RANGE[x.unit] || [-1e12, 1e12];
      (x.series||[]).forEach((v,i)=>{
        kn++;
        if(!(typeof v==="number"&&isFinite(v)&&v>=r[0]&&v<=r[1])) kb.push({site:x.site, pc:"", item:x.name+" · point "+(i+1), val:`${v} ${x.unit} (allowed ${r[0]} to ${r[1]})`, drill:`site:${x.site}|tab:outcomes`});
      });
    });
    add("dqKpi", "KPI values inside a sensible range", kn, kb, "r", "Fix the unit (for example 0.92 entered instead of 92%) or the source report.");

    return C;
  }

  // Three independent ways to add up revenue for the period. They must agree.
  function reconcile(){
    const ms = months();
    const inP = f=>ms.includes(f.m);
    const sideRev = sum(D.facts.filter(inP), f=>fin(f.rev));
    const rows = D.sites.map(s=>{
      const pcSum = sum(s.pcs.map(pc=>sum(D.facts.filter(f=>f.site===s.id&&f.pc===pc&&inP(f)), f=>fin(f.rev))));
      const siteRev = sum(D.facts.filter(f=>f.site===s.id&&inP(f)), f=>fin(f.rev));
      return {s, pcSum, siteRev, diff: pcSum-siteRev};
    });
    const sitesSum = sum(rows, r=>r.siteRev);
    const pcAll = sum(rows, r=>r.pcSum);
    return {rows, sideRev, sitesSum, pcAll, diff: Math.max(Math.abs(pcAll-sitesSum), Math.abs(sitesSum-sideRev))};
  }
  const ties = d => Math.abs(fin(d)) < 0.5; // half a currency unit tolerance for rounding

  function ring(p){
    const R = 42, c = 2*Math.PI*R, f = Math.max(0, Math.min(1, fin(p)));
    const col = f>=0.9 ? "var(--good)" : f>=0.7 ? "var(--warn)" : "var(--bad)";
    return `<svg viewBox="0 0 110 110" width="110" height="110" role="img" aria-label="Checks passed ${Math.round(f*100)}%">
      <circle cx="55" cy="55" r="${R}" fill="none" stroke="var(--line)" stroke-width="12"/>
      <circle cx="55" cy="55" r="${R}" fill="none" stroke="${col}" stroke-width="12" stroke-dasharray="${(f*c).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 55 55)" stroke-linecap="butt"/>
      <text x="55" y="61" text-anchor="middle" font-size="20" font-family="var(--f-num)" fill="var(--ink)">${Math.round(f*100)}%</text></svg>`;
  }

  document.addEventListener("change", e=>{
    const t = e.target;
    if(t && t.id==="dqSd"){ sdPick = SDS.includes(t.value) ? t.value : "2.5"; store("dq.sd", sdPick); render(); const n=document.getElementById("dqSd"); if(n) n.focus(); }
    else if(t && t.id==="dqWhich"){ onlyCheck = t.value; render(); const n=document.getElementById("dqWhich"); if(n) n.focus(); }
  });

  BI.add({
    id: "dataquality",
    label: "Data checks",
    formulas: {
      dqScore: "Data score = checks with no issues / all checks run",
      dqTested: "Rows tested = number of records the check looked at in the current filters and period",
      dqIssues: "Issues = records that break the rule",
      dqStatus: "Status: green no issues; amber issues on a warning check (loss months, outliers, old deals); red issues on a data-integrity check",
      dqComplete: "Completeness = site x profit centre x month combinations that have a fact row / all combinations expected",
      dqOutlier: "Outlier = |Revenue - mean revenue of that profit centre over 12 months| / standard deviation of the same > chosen limit (default 2.5)",
      dqShareSum: "Share total = our share + competitors A to E + all others; must be 100% or less",
      dqRecPc: "Profit-centre sum = sum over each site's profit centres of their revenue in the period",
      dqRecSite: "Site revenue = revenue of all rows for the site in the period",
      dqRecSide: "Side revenue = revenue of every row on this page in the period",
      dqRecDiff: "Difference = Profit-centre sum - Site revenue; must be zero (within 0.5 for rounding)",
      dqFp: "Data fingerprint = 32-bit FNV-1a hash of the page data as JSON, shown as hex; the same data always gives the same fingerprint"
    },
    render: () => {
      const ms = months();
      const C = runChecks();
      const passed = C.filter(c=>c.issues.length===0).length;
      const score = C.length ? passed/C.length : 0;
      const totIssues = sum(C, c=>c.issues.length);
      const totTested = sum(C, c=>c.tested);
      const rec = reconcile();
      const fp = fingerprint();
      const scope = (st.site==="all"?"All sites on this page":esc(siteName(st.site)))+" · "+(st.pc==="all"?"all profit centres":esc(st.pc))+(st.country==="all"?"":" · "+esc(st.country))+" · last "+ms.length+" months";

      const pillOf = c => c.issues.length===0 ? `<span class="pill g">Pass</span>` : `<span class="pill ${c.sev}">${c.sev==="r"?"Fix":"Review"}</span>`;
      const cRows = C.map(c=>[esc(c.name), String(c.tested), c.issues.length ? `<button type="button" class="lnk" data-dqpick="${c.id}">${c.issues.length}</button>` : "0", pillOf(c), `<span class="note">${esc(c.fix)}</span>`]);

      if(!C.some(c=>c.id===onlyCheck)) onlyCheck = "all";
      const pool = C.filter(c=>onlyCheck==="all"||c.id===onlyCheck).flatMap(c=>c.issues.map(i=>({c, i})));
      const shown = pool.slice(0, 50);
      const iRows = shown.map(({c,i})=>[`<span class="pill ${c.sev}">${c.sev==="r"?"Fix":"Review"}</span> ${esc(c.name)}`, esc(siteName(i.site)), esc(i.pc||"All"), esc(i.item), esc(i.val),
        TABS[(i.drill.split("tab:")[1]||"")] ? `<button type="button" class="lnk" data-drill="${esc(i.drill)}">Open</button>` : ""]);
      const issueBlock = shown.length
        ? table("tDqIssues", [{t:"Check"},{t:"Site"},{t:"Profit centre"},{t:"Month or item"},{t:"What we found"},{t:"Drill"}], iRows)
        : `<p class="note" id="tDqNone">No issues found for ${onlyCheck==="all"?"any check":"this check"} in the current filters. Nothing to fix.</p>`;

      const rRows = rec.rows.filter(r=>st.site==="all"||r.s.id===st.site).map(r=>[
        `<button type="button" class="lnk" data-drill="site:${esc(r.s.id)}|tab:profit">${esc(r.s.name)}</button>`, money(r.pcSum), money(r.siteRev), money(ties(r.diff)?0:r.diff),
        ties(r.diff) ? `<span class="pill g">Ties</span>` : `<span class="pill r">Does not tie</span>`]);
      const rFoot = ["Whole page", money(rec.pcAll), money(rec.sitesSum)+" (side "+money(rec.sideRev)+")", money(ties(rec.pcAll-rec.sideRev)?0:rec.pcAll-rec.sideRev), ties(rec.diff) ? `<span class="pill g">Ties</span>` : `<span class="pill r">Does not tie</span>`];

      const tiles = [
        ["Data score", pct(score), `${passed} of ${C.length} checks passed`, "dqScore"],
        ["Issues found", String(totIssues), totIssues ? `<span class="down">needs a look</span>` : `<span class="up">clean</span>`, "dqIssues"],
        ["Rows tested", String(totTested), `${C.length} checks · ${ms.length} months`, "dqTested"],
        ["Totals tie", ties(rec.diff) ? "Yes" : "No", `profit centres = sites = side`, "dqRecDiff"],
        ["Data fingerprint", fp.hex, `${fp.len} bytes hashed`, "dqFp"],
        ["Records on page", String(D.facts.length+D.deals.length+D.market.length+D.kpis.length), `${D.facts.length} facts · ${D.deals.length} deals`, "dqTested"]
      ];

      return `<div class="tiles t3">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]]||"")}"><span class="k">${t[0]}</span><span class="v" ${t[0]==="Data fingerprint"?'id="dqFp" data-s="letter-spacing:.04em"':""}>${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>
  <section class="p w4"><h2>Data score</h2><p class="sub">${scope}</p><div class="row" data-s="align-items:center;gap:14px;flex-wrap:wrap">${ring(score)}<div><p data-s="margin:0">${passed} of ${C.length} checks pass.</p><p class="note" data-s="margin:4px 0 0">Red means the data is wrong and must be fixed. Amber means the data may be right but someone should look.</p></div></div>
    <p class="note"><label for="dqSd">Outlier limit </label><select id="dqSd">${SDS.map(v=>`<option value="${v}"${v===sdPick?" selected":""}>${v} standard deviations</option>`).join("")}</select></p></section>
  <section class="p w8"><h2>Checks</h2><p class="sub">${scope} · click an issue count to list those rows below</p>${table("tDqChecks", [{t:"Check"},{t:"Rows tested",f:"dqTested"},{t:"Issues",f:"dqIssues"},{t:"Status",f:"dqStatus"},{t:"How to fix"}], cRows, ["Score", String(totTested), String(totIssues), pct(score), ""])}</section>
  <section class="p w12"><h2>Issues in detail</h2><p class="sub">First ${shown.length} of ${pool.length} · Open takes you to the right tab with the site and profit centre set</p>
    <p class="note"><label for="dqWhich">Show </label><select id="dqWhich"><option value="all">All checks</option>${C.map(c=>`<option value="${c.id}"${c.id===onlyCheck?" selected":""}>${esc(c.name)} (${c.issues.length})</option>`).join("")}</select></p>${issueBlock}</section>
  <section class="p w12"><h2>Reconciliation: do the totals tie?</h2><p class="sub">Revenue for the last ${ms.length} months, added up three separate ways. All three must match.</p>${table("tDqRec", [{t:"Site"},{t:"Sum of profit centres",f:"dqRecPc"},{t:"Site revenue",f:"dqRecSite"},{t:"Difference",f:"dqRecDiff"},{t:"Status"}], rRows, rFoot)}
    <p class="note">Side revenue ${money(rec.sideRev)} · sum of sites ${money(rec.sitesSum)} · sum of profit centres ${money(rec.pcAll)}.</p></section>
  <section class="p w12"><h2>Evidence</h2><p class="sub">Keep this with any report you send out</p>
    <p data-s="margin:0">Data fingerprint: <code id="dqFpCode" data-s="font-family:var(--f-num)">${fp.hex}</code> <span class="note">(32-bit FNV-1a of the page data, ${fp.len} bytes)</span></p>
    <p class="note">If the fingerprint changes, the data changed. Note it next to the date of any report so an auditor can confirm which data was used. Checks run in this browser each time the tab opens; nothing is sent anywhere.</p></section>`;
    }
  });

  // Clicking an issue count narrows the detail table to that check.
  document.addEventListener("click", e=>{
    const b = e.target.closest && e.target.closest("[data-dqpick]");
    if(!b) return;
    onlyCheck = b.dataset.dqpick; render();
    const t = document.getElementById("dqWhich"); if(t) t.scrollIntoView({block:"nearest"});
  });
})();

/* module: forecast.js */
/* Revenue forecast tab: straight-line trend + 4-month seasonal index, 6 months ahead with an 80% band,
   a what-if growth slider, a target gap table and a back-test. Demo data only. */
(function(){
  const fin = v => (isFinite(v) ? v : 0);
  const AHEAD = 6, CYCLE = 4, Z = 1.28;

  // Least-squares straight line through (x, y) points.
  function line(ys){
    const n = ys.length; if(!n) return {a:0,b:0};
    const mx = (n-1)/2, my = sum(ys)/n;
    let sxy = 0, sxx = 0;
    ys.forEach((y,i)=>{sxy += (i-mx)*(y-my); sxx += (i-mx)*(i-mx);});
    const b = sxx ? sxy/sxx : 0;
    return {a: my - b*mx, b};
  }
  // Fit trend x season on a series; returns a predictor for any month index.
  function fit(ys){
    const {a,b} = line(ys);
    const tr = i => a + b*i;
    const idx = [];
    for(let k=0;k<CYCLE;k++){
      const r = ys.map((y,i)=>i%CYCLE===k && tr(i)>0 ? y/tr(i) : null).filter(v=>v!==null);
      idx.push(r.length ? sum(r)/r.length : 1);
    }
    const m = sum(idx)/CYCLE || 1; const si = idx.map(v=>fin(v/m) || 1);
    const pred = i => Math.max(0, fin(tr(i)*si[i%CYCLE]));
    const res = ys.map((y,i)=>y-pred(i));
    const sd = ys.length>2 ? Math.sqrt(sum(res,e=>e*e)/(ys.length-2)) : 0;
    const my = ys.length ? sum(ys)/ys.length : 0;
    const ssT = sum(ys,y=>(y-my)*(y-my)), ssR = sum(res,e=>e*e);
    return {a, b, si, pred, tr, sd: fin(sd), r2: ssT ? fin(1-ssR/ssT) : 0, mean: my};
  }
  function addMonths(ym, n){
    const [y,m] = ym.split("-").map(Number); const t = y*12 + (m-1) + n;
    return Math.floor(t/12) + "-" + String(t%12+1).padStart(2,"0");
  }
  const short = ym => ym.slice(5) + "/" + ym.slice(2,4);

  function chart(hist, fut, fx){
    const all = [...hist, ...fut];
    const W=640, H=270, L=62, R=14, T=14, B=44, w=W-L-R, h=H-T-B;
    const mx = niceMax(Math.max(1, ...hist.map(p=>p.v), ...fut.map(p=>p.hi)));
    const x = i => L + i*w/(all.length-1), y = v => T + h - Math.max(0,v)/mx*h;
    let g = "";
    for(let i=0;i<=4;i++){const v=mx*i/4; g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${money(v)}</text>`;}
    all.forEach((p,i)=>{ if(i%2===(all.length-1)%2) g+=`<text x="${x(i)}" y="${H-24}" text-anchor="middle">${short(p.m)}</text>`; });
    g += `<text x="${L+w/2}" y="${H-6}" text-anchor="middle">Month</text>`;
    g += `<text transform="translate(12 ${T+h/2}) rotate(-90)" text-anchor="middle">Revenue</text>`;
    const n0 = hist.length-1, last = hist[n0];
    // shaded 80% band, starting from the last actual month
    const top = [{i:n0,v:last.v}, ...fut.map((p,j)=>({i:n0+1+j,v:p.hi}))];
    const bot = [{i:n0,v:last.v}, ...fut.map((p,j)=>({i:n0+1+j,v:p.lo}))].reverse();
    g += `<polygon points="${[...top,...bot].map(p=>x(p.i)+","+y(p.v)).join(" ")}" fill="var(--c1)" fill-opacity="0.16" stroke="none"><title>80% band: low to high</title></polygon>`;
    g += `<line x1="${x(n0)}" x2="${x(n0)}" y1="${T}" y2="${T+h}" stroke="var(--mut)" stroke-dasharray="3 3"/><text x="${x(n0)+6}" y="${T+12}">Forecast</text>`;
    // trend line across history and forecast
    g += `<line x1="${x(0)}" y1="${y(fx.tr(0))}" x2="${x(all.length-1)}" y2="${y(fx.tr(all.length-1))}" stroke="var(--c6)" stroke-width="1.4" stroke-dasharray="2 4"/>`;
    g += `<polyline points="${hist.map((p,i)=>x(i)+","+y(p.v)).join(" ")}" fill="none" stroke="var(--c2)" stroke-width="2"/>`;
    hist.forEach((p,i)=>g+=`<circle cx="${x(i)}" cy="${y(p.v)}" r="3" fill="var(--c2)"><title>Actual ${p.m}: ${money(p.v)}</title></circle>`);
    g += `<polyline points="${[{i:n0,v:last.v},...fut.map((p,j)=>({i:n0+1+j,v:p.f}))].map(p=>x(p.i)+","+y(p.v)).join(" ")}" fill="none" stroke="var(--c1)" stroke-width="2" stroke-dasharray="6 3"/>`;
    fut.forEach((p,j)=>g+=`<circle cx="${x(n0+1+j)}" cy="${y(p.f)}" r="3" fill="var(--c1)"><title>Forecast ${p.m}: ${money(p.f)} (low ${money(p.lo)}, high ${money(p.hi)})</title></circle>`);
    return `<svg id="fcstChart" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Monthly revenue: actuals, forecast and 80% band">${g}</svg>
    <div class="legend"><span><i data-s="background:var(--c2)"></i>Actual</span><span><i data-s="background:var(--c1)"></i>Forecast</span><span><i data-s="background:var(--c1);opacity:.25"></i>80% band (low to high)</span><span><i data-s="background:var(--c6)"></i>Straight-line trend</span></div>`;
  }

  function model(){
    const ms = D.months;
    const ys = ms.map(m=>fin(sum(facts([m]),r=>r.rev)));
    const buds = ms.map(m=>fin(sum(facts([m]),r=>r.budget)));
    const fx = fit(ys);
    const g = fin(+st.fcstGrowth || 0); fx.lift = 1 + g/100;
    const hist = ms.map((m,i)=>({m, v: ys[i]}));
    const lastBud = buds[buds.length-1];
    const fut = [];
    for(let j=1;j<=AHEAD;j++){
      const i = ys.length-1+j; const f = fx.pred(i)*fx.lift; const band = Z*fx.sd;
      const tgt = lastBud*Math.pow(1.035,j);
      fut.push({m:addMonths(ms[ms.length-1],j), f, lo:Math.max(0,f-band), hi:f+band, tgt, gap:f-tgt, gp: tgt ? (f-tgt)/tgt : 0});
    }
    // back-test: fit on first 9 months, forecast months 10-12
    const k = Math.max(3, ys.length-3); const bt = fit(ys.slice(0,k));
    const bRows = ys.slice(k).map((y,j)=>{const f=bt.pred(k+j); return {m:ms[k+j], y, f, e: y ? Math.abs(y-f)/y : 0};});
    const mape = bRows.length ? sum(bRows,r=>r.e)/bRows.length : 0;
    return {fx, g, hist, fut, ys, mape, bRows, k};
  }

  BI.add({
    id: "forecast",
    label: "Forecast",
    formulas: {
      fcTrend: "Trend = a + b x month number (straight line by least squares over the 12 months)",
      fcSeason: "Seasonal index = average of (Actual / Trend) for months in the same place of a 4-month cycle, scaled so the 4 indexes average 1",
      fcFc: "Forecast = Trend x Seasonal index x (1 + what-if growth %)",
      fcBand: "Low / High = Forecast -/+ 1.28 x standard deviation of past misses (about an 80% range)",
      fcGrow: "Trend growth per month % = b / average monthly revenue",
      fcR2: "R squared = 1 - (sum of squared misses / sum of squared gaps to the average); 1 = perfect fit",
      fcTgt: "Target = last month's budget x 1.035 ^ months ahead",
      fcGap: "Gap to target = Forecast - Target; Gap % = Gap / Target",
      fcMape: "MAPE = average of |Actual - Forecast| / Actual over the test months"
    },
    render(){
      const M = model(), F = M.fut;
      const tot = sum(F,p=>p.f), gr = M.fx.mean ? M.fx.b/M.fx.mean : 0;
      const scope = (st.site==="all" ? "All sites on this side" : esc(siteName(st.site))) + " · " + (st.pc==="all" ? "all profit centres" : esc(st.pc));
      const r2 = M.fx.r2, fitTxt = r2>=0.7 ? ["up","Good fit"] : r2>=0.4 ? ["flat","Fair fit"] : ["down","Weak fit: use with care"];
      const pill = p => `<span class="pill ${p>=0?"g":p>-0.1?"a":"r"}">${p>=0?"+":""}${pct(p)}</span>`;
      const rows = F.map((p,j)=>[p.m, j+1, money(p.lo), `<b>${money(p.f)}</b>`, money(p.hi), money(p.tgt), `<span class="${p.gap>=0?"up":"down"}">${money(p.gap)}</span>`, pill(p.gp)]);
      const tt = sum(F,p=>p.tgt);
      const foot = ["Total", "", money(sum(F,p=>p.lo)), money(tot), money(sum(F,p=>p.hi)), money(tt), `<span class="${tot-tt>=0?"up":"down"}">${money(tot-tt)}</span>`, pill(tt ? (tot-tt)/tt : 0)];
      const bt = M.bRows.map(r=>[r.m, money(r.y), money(r.f), `<span class="pill ${r.e<=0.1?"g":r.e<=0.2?"a":"r"}">${pct(r.e)}</span>`]);
      const mTxt = M.mape<=0.1 ? ["g","Close"] : M.mape<=0.2 ? ["a","Fair"] : ["r","Wide"];
      const si = M.fx.si.map((v,k)=>`position ${k+1}: ${v.toFixed(2)}`).join(" · ");
      return `<div class="tiles">
        <div class="tile" title="${esc(FX.fcFc)}"><span class="k">Next month forecast</span><span class="v" id="fcstNext">${money(F[0].f)}</span><span class="d flat">${F[0].m} · ${money(F[0].lo)} to ${money(F[0].hi)}</span></div>
        <div class="tile" title="${esc(FX.fcFc)}"><span class="k">6-month total</span><span class="v" id="fcstTotal">${money(tot)}</span><span class="d ${tot>=tt?"up":"down"}">${pct(tt ? (tot-tt)/tt : 0)} vs target</span></div>
        <div class="tile" title="${esc(FX.fcGrow)}"><span class="k">Trend growth per month</span><span class="v">${pct(gr)}</span><span class="d ${gr>0.001?"up":gr<-0.001?"down":"flat"}">${money(M.fx.b)} a month</span></div>
        <div class="tile" title="${esc(FX.fcR2)}"><span class="k">Fit quality (R squared)</span><span class="v">${fin(r2).toFixed(2)}</span><span class="d ${fitTxt[0]}">${fitTxt[1]}</span></div></div>
      <section class="p w8"><h2>Revenue: last 12 months and next 6</h2><p class="sub">${scope} · uses all 12 months of history, so the Period and Country filters do not change this tab · shaded area is the 80% band</p>${chart(M.hist, F, M.fx)}</section>
      <section class="p w4"><h2>What if growth changes?</h2><p class="sub">Move the slider to lift or cut every forecast month. The band moves with it.</p>
        <div class="row"><label for="fcstGrowth" class="note">Extra growth: <b id="fcstGrowthV">${M.g>0?"+":""}${M.g}%</b></label><input id="fcstGrowth" type="range" min="-20" max="30" step="1" value="${M.g}" data-s="width:100%;max-width:100%"></div>
        <p class="note" data-s="margin-top:12px"><span class="formula">${esc(FX.fcFc)}</span></p>
        <p class="note">The forecast is a simple guide: it repeats the past trend and the 4-month pattern. It does not know about new deals, prices or one-off events.</p></section>
      <section class="p w12"><h2>Forecast by month against target</h2><p class="sub">${esc(FX.fcTgt)} · green = at or above target, amber = within 10%, red = more than 10% short</p>
        ${table("tFcstMonths",[{t:"Month"},{t:"Months ahead"},{t:"Low",f:"fcBand"},{t:"Forecast",f:"fcFc"},{t:"High",f:"fcBand"},{t:"Target",f:"fcTgt"},{t:"Gap",f:"fcGap"},{t:"Gap %",f:"fcGap"}],rows,foot)}</section>
      <section class="p"><h2>Forecast accuracy (back-test)</h2><p class="sub">We fit the same method on the first ${M.k} months only, then forecast the last ${M.bRows.length} and compare with what really happened.</p>
        <p>Average miss (MAPE): <b id="fcstMape">${pct(M.mape)}</b> <span class="pill ${mTxt[0]}">${mTxt[1]}</span></p>
        ${table("tFcstBack",[{t:"Month"},{t:"Actual",f:"rev"},{t:"Back-test forecast",f:"fcFc"},{t:"Miss %",f:"fcMape"}],bt)}</section>
      <section class="p"><h2>How the forecast is made</h2><p class="sub">Four steps, same for every site and profit centre</p>
        <dl class="fx">
          <dt>1. Trend</dt><dd><span class="formula">${esc(FX.fcTrend.split(" = ")[1])}</span><br><span class="note">Here: a = ${money(M.fx.a)}, b = ${money(M.fx.b)} a month.</span></dd>
          <dt>2. Season</dt><dd><span class="formula">${esc(FX.fcSeason.split(" = ")[1])}</span><br><span class="note">${si}</span></dd>
          <dt>3. Forecast</dt><dd><span class="formula">${esc(FX.fcFc.split(" = ")[1])}</span></dd>
          <dt>4. Band</dt><dd><span class="formula">${esc(FX.fcBand.split(" = ")[1])}</span><br><span class="note">Standard deviation of misses: ${money(M.fx.sd)}.</span></dd>
        </dl></section>`;
    }
  });

  document.addEventListener("input", e=>{
    if(e.target.id!=="fcstGrowth") return;
    st.fcstGrowth = +e.target.value; render();
    const n = document.getElementById("fcstGrowth"); if(n) n.focus();
  });
})();

/* module: opportunity.js */
/* Competitors and opportunities tab: who holds each segment, how strong each competitor is,
   which segment x country lines to go after first, and a bubble map of growth against our share.
   Demo data only. Competitors stay anonymous (Competitor A to E). */
(function(){
  const NAMES=["Competitor A","Competitor B","Competitor C","Competitor D","Competitor E"];
  const fin=v=>isFinite(v)?v:0;
  const div=(a,b)=>b?fin(a/b):0;

  // Size-weighted shares for one group of market rows.
  function shares(rows){
    const sz=sum(rows,r=>r.size);
    return {size:sz, us:div(sum(rows,r=>r.size*r.ours),sz), comp:NAMES.map((_,i)=>div(sum(rows,r=>r.size*r.comp[i]),sz)),
      growth:div(sum(rows,r=>r.size*r.growth),sz)};
  }

  // Opportunity score for every segment x country line.
  function scoreLines(m){
    const n=m.length; const bySize=[...m].sort((a,b)=>a.size-b.size);
    const gs=m.map(r=>r.growth); const gMin=Math.min(...gs), gMax=Math.max(...gs);
    return m.map(r=>{
      const rank=bySize.indexOf(r);
      const sizeN=n>1?rank/(n-1):1;
      const growthN=gMax>gMin?(r.growth-gMin)/(gMax-gMin):0.5;
      const gap=r.offered?1-r.ours:1;
      const score=fin(0.4*sizeN+0.3*growthN+0.3*gap);
      const top=Math.max(...r.comp); const topI=r.comp.indexOf(top);
      const move=!r.offered?"Enter":r.ours>top?"Defend":score>=0.6?"Grow share":"Watch";
      const tgt=r.offered?0.10*r.size*(1-r.ours):0.05*r.size;
      return {r,score,sizeN,growthN,gap,top,topI,move,tgt};
    }).sort((a,b)=>b.score-a.score);
  }

  function bubbleChart(segs){
    const W=640,H=300,L=52,R=16,T=16,B=40,w=W-L-R,h=H-T-B;
    const gs=segs.map(s=>s.growth), us=segs.map(s=>s.us);
    let xLo=Math.min(0,...gs), xHi=Math.max(0.01,...gs);
    const xStep=(xHi-xLo)/4; xLo-=xStep*0.15; xHi+=xStep*0.15;
    const yHi=niceMax(Math.max(0.01,...us)*1.15);
    const x=v=>L+(v-xLo)/(xHi-xLo)*w, y=v=>T+h-v/yHi*h;
    const maxSize=Math.max(1,...segs.map(s=>s.size)); const rMax=Math.min(26,w/Math.max(4,segs.length*1.8));
    const rad=s=>Math.max(4,Math.sqrt(s.size/maxSize)*rMax); // area grows with market size
    let g="";
    for(let i=0;i<=4;i++){const v=yHi*i/4;g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text x="${L-6}" y="${(y(v)+4).toFixed(1)}" text-anchor="end">${(v*100).toFixed(1)}%</text>`;}
    for(let i=0;i<=4;i++){const v=xLo+(xHi-xLo)*i/4;g+=`<line class="gl" x1="${x(v).toFixed(1)}" x2="${x(v).toFixed(1)}" y1="${T}" y2="${T+h}" stroke-dasharray="2 4"/><text x="${x(v).toFixed(1)}" y="${T+h+16}" text-anchor="middle">${(v*100).toFixed(1)}%</text>`;}
    if(xLo<0&&xHi>0)g+=`<line x1="${x(0).toFixed(1)}" x2="${x(0).toFixed(1)}" y1="${T}" y2="${T+h}" stroke="var(--mut)" stroke-width="1"/>`;
    g+=`<text x="${L+w/2}" y="${H-4}" text-anchor="middle">Market growth per year</text>`;
    g+=`<text x="12" y="${T+h/2}" text-anchor="middle" transform="rotate(-90 12 ${T+h/2})">Our share</text>`;
    const placed=[], labels=[];
    [...segs].sort((a,b)=>b.size-a.size).forEach(s=>{
      const cx=x(s.growth),cy=y(s.us),r=rad(s); const c=s.offered?"var(--c1)":"var(--c4)";
      g+=`<g data-drill="seg:${esc(s.seg)}" data-s="cursor:pointer"><circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="${r.toFixed(1)}" fill="${c}" fill-opacity=".4" stroke="${c}" stroke-width="1.5"><title>${esc(s.seg)}: growth ${pct(s.growth)}, our share ${pct(s.us)}, market ${money(s.size)}</title></circle></g>`;
      // label: try above, below, right, left of the bubble; keep inside the plot and away from other labels
      const lw=s.seg.length*6.1+4, lh=13;
      const cand=[[cx,cy-r-4],[cx,cy+r+13],[cx+r+4+lw/2,cy+4],[cx-r-4-lw/2,cy+4]].map(([lx,ly])=>[Math.min(W-R-lw/2,Math.max(L+lw/2,lx)),Math.min(T+h-2,Math.max(T+lh,ly))]);
      const hit=([lx,ly])=>placed.some(b=>Math.abs(b[0]-lx)<(b[2]+lw)/2&&Math.abs(b[1]-ly)<lh);
      const pos=cand.find(c=>!hit(c))||cand[0]; placed.push([pos[0],pos[1],lw]);
      labels.push(`<text x="${pos[0].toFixed(1)}" y="${pos[1].toFixed(1)}" text-anchor="middle" data-s="fill:var(--ink);font-size:11px;pointer-events:none">${esc(s.seg)}</text>`);
    });
    g+=labels.join("");
    return `<svg id="oppBubble" viewBox="0 0 ${W} ${H}" width="100%" data-s="max-width:780px;display:block" role="img" aria-label="Bubble chart: market growth against our share, bubble size is market size">${g}</svg>
    <div class="legend"><span><i data-s="background:var(--c1)"></i>We sell here</span><span><i data-s="background:var(--c4)"></i>We do not sell here yet</span><span>Bigger bubble = bigger market</span></div>`;
  }

  BI.add({id:"opportunity", label:"Opportunities",
    formulas:{
      heat:"Segment share = sum of (market size x share) / sum of market size, for the segment across countries",
      lead:"Segments led = segments where this competitor has the biggest share (us included)",
      threat:"Threat score = competitor's overall share x market growth weighted by its sales x 100",
      opp:"Opportunity score = 0.4 x size rank (0 smallest to 1 biggest) + 0.3 x growth (0 slowest to 1 fastest) + 0.3 x gap (1 - our share)",
      move:"Move = Enter if we do not sell there; Defend if our share beats the largest competitor; Grow share if score is 0.60 or more; Watch otherwise",
      oppTgt:"Line target = 10% of lost market if we sell there, or 5% of market size if it is a new line"
    },
    render:()=>{
      const m=mkt();
      if(!m.length) return `<section class="p w12"><h2>Competitors and opportunities</h2><p class="sub">No market rows match these filters.</p><p>Try "All countries" or another site in the filters above.</p></section>`;
      const segNames=[...new Set(m.map(x=>x.segment))];
      const segs=segNames.map(sg=>{const rows=m.filter(x=>x.segment===sg);const s=shares(rows);return {seg:sg,...s,offered:rows.some(x=>x.offered)};});
      const all=shares(m);

      // (1) heatmap
      const cellMax=Math.max(0.0001,...segs.flatMap(s=>[s.us,...s.comp]));
      const heat=v=>`<span data-s="display:block;padding:2px 4px;border-radius:3px;background:color-mix(in srgb,var(--accent) ${Math.round(fin(v/cellMax)*55)}%,transparent)">${pct(v)}</span>`;
      const heatRows=segs.map(s=>{const top=Math.max(s.us,...s.comp);
        return [`<button type="button" class="lnk" data-drill="seg:${esc(s.seg)}">${esc(s.seg)}</button>`,...[s.us,...s.comp].map(v=>v===top&&v>0?`<b>${heat(v)}</b>`:heat(v))];});

      // (2) competitor profiles
      const prof=NAMES.map((n,i)=>{
        const share=all.comp[i];
        const leads=segs.filter(s=>s.comp[i]>0&&s.comp[i]>=Math.max(s.us,...s.comp)).length;
        const wg=div(sum(m,r=>r.size*r.comp[i]*r.growth),sum(m,r=>r.size*r.comp[i]));
        return {n,share,leads,wg,threat:fin(share*wg*100)};});
      const tMax=Math.max(...prof.map(p=>p.threat));
      prof.forEach(p=>{p.lvl=tMax>0&&p.threat>=0.75*tMax?"r":tMax>0&&p.threat>=0.4*tMax?"a":"g";});
      prof.sort((a,b)=>b.threat-a.threat);
      const lvlTxt={r:"High",a:"Medium",g:"Low"};
      const profRows=prof.map(p=>[esc(p.n),pct(p.share),`${p.leads} of ${segs.length}`,`<span class="${p.wg>=0?"up":"down"}">${pct(p.wg)}</span>`,p.threat.toFixed(2),`<span class="pill ${p.lvl}">${lvlTxt[p.lvl]}</span>`]);

      // (3) opportunity ranking
      const scored=scoreLines(m).filter(o=>!st.seg||o.r.segment===st.seg);
      const top12=scored.slice(0,12);
      const multi=st.site==="all"&&D.sites.length>1;
      const mvCls={"Defend":"g","Grow share":"g","Enter":"a","Watch":"r"};
      const rankRows=top12.map((o,i)=>[String(i+1),esc(o.r.segment),esc(o.r.country),...(multi?[esc(siteName(o.r.site))]:[]),
        o.r.offered?'<span class="pill g">Offered</span>':'<span class="pill a">New line</span>',money(o.r.size),
        `<span class="${o.r.growth>=0?"up":"down"}">${pct(o.r.growth)}</span>`,pct(o.r.ours),`${esc(NAMES[o.topI].replace("Competitor ",""))} ${pct(o.top)}`,
        o.score.toFixed(2),`<span class="pill ${mvCls[o.move]}">${o.move}</span>`,money(o.tgt)]);
      const tgtSum=sum(top12,o=>o.tgt);
      const newLines=scored.filter(o=>!o.r.offered).length;
      const best=top12[0];

      return `<div class="tiles">
   <div class="tile" title="${esc(FX.opp)}"><span class="k">Lines scored</span><span class="v">${scored.length}</span><span class="d flat">segment x country</span></div>
   <div class="tile" title="${esc(FX.opp)}"><span class="k">Best score</span><span class="v">${best?best.score.toFixed(2):"0.00"}</span><span class="d flat">${best?esc(best.r.segment)+" · "+esc(best.r.country):"no lines"}</span></div>
   <div class="tile"><span class="k">New lines</span><span class="v">${newLines}</span><span class="d flat">markets we do not sell in yet</span></div>
   <div class="tile" title="${esc(FX.oppTgt)}"><span class="k">Draft target, top ${top12.length}</span><span class="v">${money(tgtSum)}</span><span class="d flat">10% lost + 5% new lines</span></div></div>
  <section class="p w12"><h2>Who holds each segment</h2><p class="sub">Share of each segment, weighted by market size across countries. Darker cell = bigger share. Bold = segment leader. Competitors are anonymised.</p>
   ${table("tOppHeat",[{t:"Segment"},{t:"Us",f:"heat"},...NAMES.map(n=>({t:n.replace("Competitor","Comp."),f:"heat"}))],heatRows)}</section>
  <section class="p w8"><h2>Competitor profiles</h2><p class="sub">Threat score = share x their weighted market growth x 100. High = within 25% of the top threat.</p>
   ${table("tOppComp",[{t:"Competitor"},{t:"Overall share",f:"share"},{t:"Segments led",f:"lead"},{t:"Their market growth"},{t:"Threat score",f:"threat"},{t:"Level"}],profRows)}</section>
  <section class="p w4"><h2>Our position</h2><p class="sub">All segments in view</p>
   ${hbars([{k:"Us",v:all.us,c:"var(--c2)"},...NAMES.map((n,i)=>({k:n,v:all.comp[i],c:"var(--c6)"}))].sort((a,b)=>b.v-a.v),pct)}
   <p class="note">We lead ${segs.filter(s=>s.us>0&&s.us>=Math.max(...s.comp)).length} of ${segs.length} segments.</p></section>
  <section class="p w12"><h2>Top ${top12.length} opportunities${st.seg?": "+esc(st.seg):""}</h2><p class="sub">${esc(FX.opp)}. ${esc(FX.move)}.</p>
   ${top12.length?table("tOppRank",[{t:"Rank"},{t:"Segment"},{t:"Country"},...(multi?[{t:"Site"}]:[]),{t:"Status"},{t:"Market size"},{t:"Growth"},{t:"Our share",f:"share"},{t:"Largest competitor"},{t:"Score",f:"opp"},{t:"Move",f:"move"},{t:"Draft target",f:"tgt"}],rankRows):'<p class="note">No lines for this segment with these filters.</p>'}</section>
  <section class="p w12"><h2>Growth against our share</h2><p class="sub">One bubble per segment. Right = faster-growing market, up = bigger share for us. Click a bubble to focus the ranking on that segment.</p>${bubbleChart(segs)}</section>`;
    }});
})();

/* module: people.js */
// People and productivity tab. Demo headcount by role group (never person names).
// Respects site, profit-centre and period filters. All staff numbers are demo data from a seeded generator.
(function(){
  const CAP = 12;                 // demo capacity: orders one delivery person can handle per month
  const ROLES = ["Sales", "Delivery", "Support", "Admin"];
  const RCOL = {Sales:"var(--c1)", Delivery:"var(--c2)", Support:"var(--c3)", Admin:"var(--c4)"};
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const ui = {pc:"", role:"Delivery", n:2};
  const LKPI = "Course hours per staff member";

  // Small seeded generator keyed on site id + profit centre, so numbers never change between visits.
  function seed(str){ let h = 2166136261; for (let i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h>>>0; }
  function prng(str){ let a = seed(str); return () => { a = (a + 0x6D2B79F5)>>>0; let t = a; t = Math.imul(t ^ (t>>>15), t | 1); t ^= t + Math.imul(t ^ (t>>>7), t | 61); return ((t ^ (t>>>14))>>>0) / 4294967296; }; }

  // Demo team for one site x profit centre, from its 12-month averages (stable whatever the period).
  const cache = {};
  function team(siteId, pc){
    const key = siteId + "|" + pc;
    if (cache[key]) return cache[key];
    const r = prng("people|" + key);
    const all = D.facts.filter(f=>f.site===siteId&&f.pc===pc);
    const n = Math.max(1, all.length);
    const avgRev = fin(sum(all,f=>f.rev)/n), avgOrd = fin(sum(all,f=>f.orders)/n);
    const util = 0.55 + r()*0.6;                                   // 55% to 115% busy
    const del = Math.max(1, Math.round(avgOrd/(CAP*util)));
    let head = Math.round(5*Math.log(Math.max(avgRev,1500)/1500) + 3 + r()*5 - 2);
    head = Math.min(40, Math.max(3, del + 3, head));
    const rest = head - del;
    const sales = Math.max(1, Math.round(rest*(0.36 + r()*0.12)));
    const support = Math.max(1, Math.round((rest - sales)*(0.45 + r()*0.2)));
    const admin = Math.max(1, rest - sales - support);
    const total = sales + del + support + admin;
    const t = {Sales:sales, Delivery:del, Support:support, Admin:admin, head: total, openExtra: Math.floor(r()*2.2)};
    cache[key] = t;
    return t;
  }

  function loadPill(l){ return (l>=0.70&&l<=0.90) ? "g" : ((l>0.90&&l<=1.05)||(l>=0.50&&l<0.70)) ? "a" : "r"; }
  const loadTxt = {g:"Healthy", a:"Watch", r:"Act now"};
  function learnH(siteId){
    const k = D.kpis.filter(x=>x.site===siteId&&x.name===LKPI);
    if (!k.length) return null;
    const v = fin(k[0].series[k[0].series.length-1]);
    return v;
  }

  // Measures for one unit over months ms.
  function unit(s, pc, ms, extra){
    const t = team(s.id, pc);
    const add = extra || {};
    const roles = {}; ROLES.forEach(k=>roles[k] = t[k] + (add[k]||0));
    const head = sum(ROLES,k=>roles[k]);
    const a = agg(D.facts.filter(f=>f.site===s.id&&f.pc===pc&&ms.includes(f.m)));
    const nm = Math.max(1, ms.length);
    const costHead = t.head>0 ? fin(a.opex/t.head) : 0;          // direct cost per current head, for the period
    const addHeads = head - t.head;
    const contrib = fin(a.contrib - addHeads*costHead);
    const load = roles.Delivery>0 ? fin(a.orders/(roles.Delivery*CAP*nm)) : 0;
    const need = Math.max(0, Math.ceil(a.orders/nm/(CAP*0.85)) - t.Delivery);
    const lh = learnH(s.id);
    return {s, pc, t, roles, head, rev: fin(a.rev), contrib, orders: fin(a.orders), quotes: fin(a.quotes),
      revHead: head>0 ? fin(a.rev/head) : 0, contribHead: head>0 ? contrib/head : 0,
      qSales: roles.Sales>0 ? fin(a.quotes/nm/roles.Sales) : 0, oDel: roles.Delivery>0 ? fin(a.orders/nm/roles.Delivery) : 0,
      load, open: (load>1.05 ? need : 0) + t.openExtra, lh, lhTotal: lh===null ? 0 : lh*head, costHead, nm};
  }

  // Load % bars, drawn to scale with the healthy 70-90% band shaded.
  function loadChart(us){
    if (!us.length) return "";
    const W=640, rowH=26, T=20, L=170, R=56, B=26, H=T+us.length*rowH+B, w=W-L-R;
    const top = Math.max(...us.map(u=>u.load));
    const mx = Math.max(1.25, Math.ceil(top*1.05*4)/4);
    const x = v => L + Math.min(v,mx)/mx*w;
    const col = {g:"var(--good)", a:"var(--warn)", r:"var(--bad)"};
    let g = `<rect x="${x(0.7)}" y="${T-4}" width="${x(0.9)-x(0.7)}" height="${us.length*rowH+4}" fill="var(--good)" opacity="0.12"><title>Healthy band 70% to 90%</title></rect>`;
    const ticks = []; for (let v=0; v<=mx+1e-9; v+=mx>2?0.5:0.25) ticks.push(v);
    ticks.forEach(v=>{ g += `<line class="gl" x1="${x(v)}" x2="${x(v)}" y1="${T-4}" y2="${T+us.length*rowH}"/><text x="${x(v)}" y="${H-8}" text-anchor="middle">${Math.round(v*100)}%</text>`; });
    g += `<line x1="${x(1)}" x2="${x(1)}" y1="${T-8}" y2="${T+us.length*rowH}" stroke="var(--bad)" stroke-dasharray="4 3"/><text x="${x(1)}" y="${T-8}" text-anchor="middle">full</text>`;
    us.forEach((u,i)=>{
      const y = T + i*rowH, p = loadPill(u.load), lab = u.s.name + " · " + u.pc;
      g += `<g data-drill="site:${esc(u.s.id)}|pc:${esc(u.pc)}" data-s="cursor:pointer"><text x="${L-8}" y="${y+rowH/2+4}" text-anchor="end">${esc(lab.length>26?lab.slice(0,25)+"…":lab)}</text>
        <rect x="${L}" y="${y+5}" width="${Math.max(0,x(u.load)-L)}" height="${rowH-10}" rx="2" fill="${col[p]}"><title>${esc(lab)}: ${pct(u.load)} load</title></rect>
        <text x="${x(u.load)+4}" y="${y+rowH/2+4}">${Math.round(u.load*100)}%</text></g>`;
    });
    return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Delivery load by profit centre">${g}</svg>
      <div class="legend"><span><i data-s="background:var(--good)"></i>Healthy 70-90%</span><span><i data-s="background:var(--warn)"></i>Watch 50-70% or 90-105%</span><span><i data-s="background:var(--bad)"></i>Act now: under 50% or over 105%</span></div>`;
  }

  // One change listener for the what-if inputs (the page re-renders the tab).
  document.addEventListener("change", e=>{
    const t = e.target.closest("[data-ppl]"); if (!t) return;
    const k = t.dataset.ppl;
    if (k==="n") { const v = Math.round(+t.value); ui.n = isFinite(v) ? Math.min(50, Math.max(-20, v)) : 0; }
    else ui[k] = t.value;
    store("ppl."+k, String(ui[k]));
    const id = t.id; render(); const el = document.getElementById(id); if (el) el.focus();
  });
  (function(){ const p=load("ppl.pc"), r=load("ppl.role"), n=load("ppl.n"); if (p) ui.pc=p; if (r&&ROLES.includes(r)) ui.role=r; if (n!==null&&n!==""&&isFinite(+n)) ui.n=Math.round(+n); })();

  BI.add({
    id: "people",
    label: "People",
    formulas: {
      pplHead: "Headcount (demo) = Sales + Delivery + Support + Admin people for the profit centre; sized from its 12-month average revenue and orders with a fixed seed",
      pplRole: "Role group = Sales (quotes and deals), Delivery (fulfils orders), Support (after-sales help), Admin (finance, office, people)",
      pplRevHead: "Revenue per head = Revenue in period / Headcount",
      pplContribHead: "Contribution per head = Contribution in period / Headcount",
      pplQSales: "Quotes per sales head = Quotes in period / months in period / Sales heads (per month)",
      pplODel: "Orders per delivery head = Orders in period / months in period / Delivery heads (per month)",
      pplLoad: "Load % = Orders in period / (Delivery heads x 12 orders per head per month x months in period)",
      pplLoadStatus: "Load status: green 70% to 90%; amber 50% to 70% or 90% to 105%; red under 50% or over 105%",
      pplOpen: "Open roles (demo) = extra delivery people needed to bring load down to 85% when load is over 105%, plus a seeded 0 to 2 other open roles",
      pplLearn: "Learning hours per person = latest month of the site's 'Course hours per staff member' measure",
      pplLearnTot: "Learning hours a month = Learning hours per person x Headcount",
      pplCostHead: "Cost per new head = Direct operating cost in period / current Headcount (used in the hiring what-if)",
      pplWhatIf: "What-if: new Load % uses Delivery heads + N; new Revenue per head = Revenue / (Headcount + N); new Contribution per head = (Contribution - N x Cost per head) / (Headcount + N)"
    },
    render: () => {
      const ms = months(), pm = prevMonths();
      const scope = (st.site==="all" ? "All sites on this side" : esc(siteName(st.site))) + " · " + (st.pc==="all" ? "all profit centres" : esc(st.pc)) + " · last " + ms.length + " months";
      const us = [], ps = [];
      D.sites.filter(s=>st.site==="all"||s.id===st.site).forEach(s=>s.pcs.filter(pc=>st.pc==="all"||pc===st.pc).forEach(pc=>{
        us.push(unit(s, pc, ms)); ps.push(unit(s, pc, pm.length ? pm : ms));
      }));
      if (!us.length) return `<section class="p w12"><h2>People and productivity</h2><p class="sub">${scope}</p><p class="note">No profit centres match these filters. Clear a filter to see staff numbers.</p></section>`;

      const T = {head: sum(us,u=>u.head), rev: sum(us,u=>u.rev), contrib: sum(us,u=>u.contrib), open: sum(us,u=>u.open),
        orders: sum(us,u=>u.orders), del: sum(us,u=>u.roles.Delivery), sales: sum(us,u=>u.roles.Sales), quotes: sum(us,u=>u.quotes),
        lhTot: sum(us,u=>u.lhTotal), lhHead: sum(us.filter(u=>u.lh!==null),u=>u.head)};
      const P = {head: sum(ps,u=>u.head), rev: sum(ps,u=>u.rev), contrib: sum(ps,u=>u.contrib)};
      const nm = Math.max(1, ms.length);
      const rh = T.head ? T.rev/T.head : 0, ch = T.head ? T.contrib/T.head : 0;
      const prh = P.head && pm.length ? P.rev/P.head : 0, pch = P.head && pm.length ? P.contrib/P.head : 0;
      const tLoad = T.del ? fin(T.orders/(T.del*CAP*nm)) : 0, tp = loadPill(tLoad);
      const lhAvg = T.lhHead ? fin(T.lhTot/T.lhHead) : null;
      const byRole = ROLES.map(k=>({k, v: sum(us,u=>u.roles[k]), c: RCOL[k]}));

      const tiles = [
        ["Headcount (demo)", String(T.head), `<span class="flat">${byRole.map(r=>r.v+" "+r.k.toLowerCase()).join(" · ")}</span>`, "pplHead"],
        ["Revenue per head", money(rh), delta(rh, prh), "pplRevHead"],
        ["Contribution per head", money(ch), delta(ch, pch), "pplContribHead"],
        ["Open roles", String(T.open), `<span class="${T.open?"down":"flat"}">${T.open?"to fill":"none open"}</span>`, "pplOpen"],
        ["Delivery load", pct(tLoad), `<span class="pill ${tp}">${loadTxt[tp]}</span> healthy 70-90%`, "pplLoad"],
        ["Learning hours per person", lhAvg===null ? "n/a" : lhAvg.toFixed(1)+" h", lhAvg===null ? '<span class="flat">no learning measure</span>' : `<span class="flat">${Math.round(T.lhTot)} h a month in all</span>`, "pplLearn"]
      ];

      const sorted = us.slice().sort((a,b)=>b.load-a.load);
      const rows = sorted.map(u=>[
        `<span data-drill="site:${esc(u.s.id)}|pc:${esc(u.pc)}" data-s="cursor:pointer" title="Click to filter to this profit centre">${esc(u.s.name+" · "+u.pc)}</span>`,
        String(u.head), ROLES.map(k=>u.roles[k]).join(" / "), money(u.revHead), `<span class="${u.contribHead>=0?"":"down"}">${money(u.contribHead)}</span>`,
        u.qSales.toFixed(1), u.oDel.toFixed(1), pct(u.load), `<span class="pill ${loadPill(u.load)}">${loadTxt[loadPill(u.load)]}</span>`,
        String(u.open), u.lh===null ? "n/a" : u.lh.toFixed(1)]);
      const foot = ["Total", String(T.head), ROLES.map(k=>sum(us,u=>u.roles[k])).join(" / "), money(rh), money(ch),
        (T.sales ? T.quotes/nm/T.sales : 0).toFixed(1), (T.del ? T.orders/nm/T.del : 0).toFixed(1), pct(tLoad), `<span class="pill ${tp}">${loadTxt[tp]}</span>`, String(T.open), lhAvg===null ? "n/a" : lhAvg.toFixed(1)];

      const capRows = sorted.map(u=>{ const p = loadPill(u.load); const msg = u.load>1.05 ? `Add ${Math.max(1, Math.ceil(u.orders/nm/(CAP*0.85)) - u.roles.Delivery)} delivery` : u.load<0.5 ? "Spare people: move or win more orders" : u.load<0.7 ? "Room for more orders" : u.load>0.9 ? "Nearly full: plan ahead" : "Keep as is";
        return [esc(u.s.name+" · "+u.pc), (u.orders/nm).toFixed(1), String(u.roles.Delivery), String(u.roles.Delivery*CAP), pct(u.load), `<span class="pill ${p}">${loadTxt[p]}</span>`, esc(msg)]; });

      // Hiring what-if
      const keys = us.map(u=>u.s.id+"|"+u.pc);
      if (!keys.includes(ui.pc)) ui.pc = sorted[0].s.id+"|"+sorted[0].pc;
      const cur = us[keys.indexOf(ui.pc)];
      const add = {}; add[ui.role] = Math.max(-(cur.roles[ui.role]-(ui.role==="Delivery"?1:0)), ui.n);
      const nn = add[ui.role];
      const nu = unit(cur.s, cur.pc, ms, add);
      const cp = loadPill(cur.load), np = loadPill(nu.load);
      const opts = us.map(u=>`<option value="${esc(u.s.id+"|"+u.pc)}"${u===cur?" selected":""}>${esc(u.s.name+" · "+u.pc)}</option>`).join("");
      const ropts = ROLES.map(r=>`<option${r===ui.role?" selected":""}>${r}</option>`).join("");
      const wiRows = [
        ["Headcount", String(cur.head), String(nu.head)],
        [ui.role+" heads", String(cur.roles[ui.role]), String(nu.roles[ui.role])],
        ["Delivery load", `${pct(cur.load)} <span class="pill ${cp}">${loadTxt[cp]}</span>`, `${pct(nu.load)} <span class="pill ${np}">${loadTxt[np]}</span>`],
        ["Revenue per head", money(cur.revHead), money(nu.revHead)],
        ["Contribution per head", money(cur.contribHead), money(nu.contribHead)],
        ["Quotes per sales head a month", cur.qSales.toFixed(1), nu.qSales.toFixed(1)]
      ];
      const say = nn===0 ? "Change the number to see the effect." :
        `${nn>0?"Adding":"Removing"} ${Math.abs(nn)} ${ui.role.toLowerCase()} ${Math.abs(nn)===1?"person":"people"} moves load from ${pct(cur.load)} to ${pct(nu.load)} and revenue per head from ${money(cur.revHead)} to ${money(nu.revHead)}. Each person costs about ${money(cur.costHead)} over the period (today's direct cost per head).`;

      return `<div class="tiles t3">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]]||"")}"><span class="k">${t[0]}</span><span class="v">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>
  <section class="p w8"><h2>Is delivery overloaded?</h2><p class="sub">${scope} · load = orders / (delivery people x ${CAP} orders a month) · click a bar to drill in</p>${loadChart(sorted)}</section>
  <section class="p w4"><h2>People by role group</h2><p class="sub">Demo headcount · roles only, no names</p>${hbars(byRole, v=>String(Math.round(v)))}
    <p class="note" title="${esc(FX.pplRole)}">${esc(FX.pplRole)}.</p></section>
  <section class="p w12"><h2>Productivity by profit centre</h2><p class="sub">${scope} · busiest first · roles shown as sales / delivery / support / admin</p>${table("tPplPc",[{t:"Site · profit centre"},{t:"Headcount",f:"pplHead"},{t:"Roles S/D/Su/A",f:"pplRole"},{t:"Revenue / head",f:"pplRevHead"},{t:"Contribution / head",f:"pplContribHead"},{t:"Quotes / sales head",f:"pplQSales"},{t:"Orders / delivery head",f:"pplODel"},{t:"Load",f:"pplLoad"},{t:"Status",f:"pplLoadStatus"},{t:"Open roles",f:"pplOpen"},{t:"Learning h / person",f:"pplLearn"}],rows,foot)}</section>
  <section class="p w12"><h2>Capacity check</h2><p class="sub">${scope} · demo capacity ${CAP} orders per delivery person per month</p>${table("tPplCap",[{t:"Site · profit centre"},{t:"Orders a month",f:"pplODel"},{t:"Delivery heads",f:"pplRole"},{t:"Capacity a month",f:"pplLoad"},{t:"Load",f:"pplLoad"},{t:"Status",f:"pplLoadStatus"},{t:"What to do"}],capRows)}</section>
  <section class="p w12"><h2>Hiring what-if</h2><p class="sub">Try adding people to one profit centre and see the effect · ${scope}</p>
    <div class="row"><label class="note" for="pplPc">Profit centre</label><select id="pplPc" data-ppl="pc" data-s="max-width:100%">${opts}</select>
      <label class="note" for="pplRole">Role</label><select id="pplRole" data-ppl="role">${ropts}</select>
      <label class="note" for="pplN">Add people</label><input id="pplN" data-ppl="n" class="thr" type="number" step="1" min="-20" max="50" value="${nn}"></div>
    <div data-s="margin-top:10px">${table("tPplWhatIf",[{t:"Measure"},{t:"Today"},{t:"After change",f:"pplWhatIf"}],wiRows)}</div>
    <p class="note" id="pplSay">${esc(say)}</p></section>`;
    }
  });
})();

/* module: plan.js */
/* Plan 2027 tab: driver-based annual plan per profit centre. Base year = last 12 months of facts.
   Owners edit four drivers per profit centre (or pick a scenario); edits are kept in this browser. Demo data only. */
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const clamp = (v,lo,hi) => Math.min(hi, Math.max(lo, fin(v)));
  const r1 = v => Math.round(fin(v)*10)/10;
  const MON = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const YEAR = 2027;
  // driver key, column title, formula key, allowed range (in %)
  const DRV = [
    {k:"vol",   t:"Volume growth %",        f:"planVol",   lo:-50, hi:200},
    {k:"price", t:"Price change %",         f:"planPrice", lo:-50, hi:100},
    {k:"cos",   t:"Cost of sales % of revenue", f:"planCos", lo:0, hi:100},
    {k:"dc",    t:"Direct cost growth %",   f:"planDc",    lo:-50, hi:200}
  ];
  const SCN = {
    cautious: {name:"Cautious", vol:-5, price:-1, cos:+1, dc:0},
    base:     {name:"Base",     vol:0,  price:0,  cos:0,  dc:0},
    stretch:  {name:"Stretch",  vol:+5, price:+1, cos:-1, dc:+2}
  };

  const baseMonths = () => D.months.slice(-12);
  const key = (s,pc) => "plan.u." + s + "|" + pc;

  // Profit centres in view (site and profit-centre filters).
  function units(){
    const out = [];
    D.sites.filter(s=>st.site==="all"||s.id===st.site).forEach(s=>s.pcs.filter(pc=>st.pc==="all"||pc===st.pc).forEach(pc=>out.push({s, pc})));
    return out;
  }

  // Base year and history-based default drivers for one profit centre.
  function base(sid, pc){
    const bm = baseMonths();
    const r = D.facts.filter(f=>f.site===sid&&f.pc===pc&&bm.includes(f.m));
    const rev = fin(sum(r,f=>f.rev)), cogs = fin(sum(r,f=>f.cogs)), opex = fin(sum(r,f=>f.opex));
    const half = Math.floor(bm.length/2);
    const h1 = bm.slice(0,half), h2 = bm.slice(half);
    const part = (ms,fn) => fin(sum(r.filter(f=>ms.includes(f.m)),fn));
    const trend = (a,b) => a>0 && b>0 ? fin(Math.pow(b/a, 2) - 1) : 0; // second half vs first half, made yearly
    const revT = clamp(trend(part(h1,f=>f.rev), part(h2,f=>f.rev)), -0.10, 0.30);
    const dcT = clamp(trend(part(h1,f=>f.opex), part(h2,f=>f.opex)), -0.10, 0.30);
    const price = 0.03;
    const def = {
      vol: r1(((1+revT)/(1+price)-1)*100),
      price: r1(price*100),
      cos: r1(rev>0 ? cogs/rev*100 : 60),
      dc: r1(dcT*100)
    };
    // seasonality: share of base revenue in each calendar month (Jan..Dec)
    const byMoy = MON.map(()=>0);
    r.forEach(f=>{ const mo = parseInt(f.m.slice(5),10)-1; if(mo>=0&&mo<12) byMoy[mo] += fin(f.rev); });
    const shares = byMoy.map(v=>rev>0 ? fin(v/rev) : 1/12);
    return {rev, cogs, opex, gm: rev-cogs, contrib: rev-cogs-opex, def, byMoy, shares};
  }

  function drivers(sid, pc, def){
    let saved = null;
    try { const raw = load(key(sid,pc)); saved = raw ? JSON.parse(raw) : null; } catch(e){ saved = null; }
    const d = {};
    DRV.forEach(x=>{ const v = saved && typeof saved[x.k]==="number" && isFinite(saved[x.k]) ? saved[x.k] : def[x.k]; d[x.k] = clamp(v, x.lo, x.hi); });
    d.edited = !!saved;
    return d;
  }
  function save(sid, pc, d){ store(key(sid,pc), JSON.stringify({vol:d.vol, price:d.price, cos:d.cos, dc:d.dc})); }

  function planOf(b, d){
    const rev = fin(b.rev*(1+d.vol/100)*(1+d.price/100));
    const cogs = fin(rev*d.cos/100);
    const gm = rev - cogs;
    const opex = fin(b.opex*(1+d.dc/100));
    const contrib = gm - opex;
    return {rev, cogs, gm, gmp: rev>0 ? gm/rev : 0, opex, contrib, cp: rev>0 ? contrib/rev : 0,
      growth: b.rev>0 ? rev/b.rev-1 : 0, monthly: b.shares.map(s=>fin(rev*s))};
  }

  function model(){
    const us = units().map((u,n)=>{ const b = base(u.s.id, u.pc); const d = drivers(u.s.id, u.pc, b.def); return {...u, n, b, d, p: planOf(b,d)}; });
    const T = {brev: sum(us,u=>u.b.rev), bcontrib: sum(us,u=>u.b.contrib), bgm: sum(us,u=>u.b.gm), bopex: sum(us,u=>u.b.opex),
      rev: sum(us,u=>u.p.rev), cogs: sum(us,u=>u.p.cogs), gm: sum(us,u=>u.p.gm), opex: sum(us,u=>u.p.opex), contrib: sum(us,u=>u.p.contrib)};
    T.growth = T.brev>0 ? T.rev/T.brev-1 : 0;
    T.cgrowth = T.bcontrib!==0 ? (T.contrib-T.bcontrib)/Math.abs(T.bcontrib) : 0;
    T.gmp = T.rev>0 ? T.gm/T.rev : 0; T.cp = T.rev>0 ? T.contrib/T.rev : 0;
    T.bcp = T.brev>0 ? T.bcontrib/T.brev : 0;
    T.planM = MON.map((_,i)=>sum(us,u=>u.p.monthly[i]));
    T.baseM = MON.map((_,i)=>sum(us,u=>u.b.byMoy[i]));
    return {us, T};
  }

  function phasing(planM, baseM){
    const W=640,H=230,L=58,R=12,T=12,B=28,w=W-L-R,h=H-T-B;
    const mx = niceMax(Math.max(1, ...planM, ...baseM)*1.05);
    const bw = w/12, y = v=>T+h-fin(v)/mx*h;
    let g = "";
    for(let i=0;i<=4;i++){const v=mx*i/4; g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${money(v)}</text>`;}
    planM.forEach((v,i)=>{
      g += `<rect x="${L+i*bw+bw*.18}" y="${y(v)}" width="${bw*.64}" height="${Math.max(0,T+h-y(v))}" fill="var(--c1)" rx="2"><title>Plan ${MON[i]} ${YEAR}: ${money(v)}</title></rect>`;
      g += `<text x="${L+i*bw+bw/2}" y="${H-10}" text-anchor="middle">${MON[i]}</text>`;
    });
    g += `<polyline points="${baseM.map((v,i)=>`${L+i*bw+bw/2},${y(v)}`).join(" ")}" fill="none" stroke="var(--c4)" stroke-width="2" stroke-dasharray="5 3"/>`;
    baseM.forEach((v,i)=>g+=`<circle cx="${L+i*bw+bw/2}" cy="${y(v)}" r="3" fill="var(--c4)"><title>Base year ${MON[i]}: ${money(v)}</title></circle>`);
    return `<svg id="planChart" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Plan revenue by month for ${YEAR} against the base year">${g}</svg><div class="legend"><span><i data-s="background:var(--c1)"></i>Plan ${YEAR}</span><span><i data-s="background:var(--c4)"></i>Base year, same month</span></div>`;
  }

  const sign = v => (v>0?"+":"") + pct(v);
  const cls = v => v>0 ? "up" : v<0 ? "down" : "flat";

  function view(){
    const {us, T} = model();
    const scope = (st.site==="all"?"All sites on this side":esc(siteName(st.site)))+" · "+(st.pc==="all"?"all profit centres":esc(st.pc));
    const bm = baseMonths();
    const baseLbl = bm.length ? esc(bm[0])+" to "+esc(bm[bm.length-1]) : "no months";
    const cNote = st.country!=="all" ? `<p class="note">The country filter does not split profit-centre figures, so this plan covers all countries.</p>` : "";
    if(!us.length || T.brev<=0){
      return `<section class="p w12" data-po="all"><h2>Plan ${YEAR}</h2><p class="sub">${scope}</p><p>No base-year revenue for this choice of filters, so there is nothing to plan yet. Pick another site or profit centre, or <button type="button" class="lnk" data-clear="all">clear all filters</button>.</p></section>`;
    }
    const active = load("plan.scn") || "base";
    const scnTxt = SCN[active] ? SCN[active].name : "Your own edits";

    const tiles = [
      ["Plan revenue "+YEAR, money(T.rev), `<span class="${cls(T.growth)}">${sign(T.growth)}</span> vs base ${money(T.brev)}`, "planRev"],
      ["Plan contribution", money(T.contrib), `<span class="${cls(T.cgrowth)}">${sign(T.cgrowth)}</span> vs base ${money(T.bcontrib)}`, "planContrib"],
      ["Growth vs base", sign(T.growth), `<span class="flat">${money(T.rev-T.brev)} more revenue</span>`, "planGrowth"],
      ["Contribution %", pct(T.cp), `<span class="${cls(T.cp-T.bcp)}">${(T.cp-T.bcp>=0?"+":"")+((T.cp-T.bcp)*100).toFixed(1)} pts</span> vs base ${pct(T.bcp)}`, "planCp"]
    ];
    const tilesHtml = `<div class="tiles" data-po="tiles">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]]||"")}"><span class="k">${t[0]}</span><span class="v">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>`;

    const label = u => `<span data-drill="site:${esc(u.s.id)}|pc:${esc(u.pc)}" title="Click to plan only this profit centre">${esc(u.s.name+" · "+u.pc)}</span>`;
    const dRows = us.map(u=>[label(u), money(u.b.rev)].concat(DRV.map(x=>
      `<input type="number" class="thr" id="plan-${u.n}-${x.k}" data-plan="${u.n}" data-pk="${x.k}" step="0.5" min="${x.lo}" max="${x.hi}" value="${r1(u.d[x.k])}" aria-label="${esc(x.t)} for ${esc(u.s.name+" "+u.pc)}" title="History default: ${u.b.def[x.k]}%">`
    )).concat([u.d.edited ? '<span class="pill a">Edited</span>' : '<span class="pill g">History</span>']));

    const pRows = us.map(u=>[label(u), money(u.b.rev), money(u.p.rev), `<span class="${cls(u.p.growth)}">${sign(u.p.growth)}</span>`, money(u.p.cogs), money(u.p.gm), pct(u.p.gmp), money(u.p.opex),
      `<span class="${u.p.contrib>=0?"":"down"}">${money(u.p.contrib)}</span>`, `<span class="pill ${u.p.cp>=0.2?"g":u.p.cp>=0.1?"a":"r"}">${pct(u.p.cp)}</span>`]);
    const pFoot = ["Total", money(T.brev), money(T.rev), sign(T.growth), money(T.cogs), money(T.gm), pct(T.gmp), money(T.opex), money(T.contrib), pct(T.cp)];
    const peak = T.planM.indexOf(Math.max(...T.planM)), low = T.planM.indexOf(Math.min(...T.planM));

    return `${tilesHtml}
  <section class="p w12"><h2>Set the drivers</h2><p class="sub">${scope} · base year ${baseLbl} · scenario: <b data-po="scn">${esc(scnTxt)}</b></p>
    <div class="row" data-s="margin-bottom:10px"><span class="note">Set every row at once:</span>${Object.entries(SCN).map(([k,s])=>`<button type="button" id="planScn-${k}" data-plan-scn="${k}"${active===k?' aria-pressed="true" data-s="border-color:var(--accent)"':' aria-pressed="false"'}>${s.name}</button>`).join("")}<button type="button" id="planReset" data-plan-reset>Reset to history</button></div>
    ${table("tPlanDrv",[{t:"Site · profit centre"},{t:"Base revenue",f:"planBase"},...DRV.map(x=>({t:x.t,f:x.f})),{t:"Source",f:"planDef"}],dRows)}
    <p class="note">Type a number and the plan below updates straight away. Your changes stay in this browser. Cautious = volume 5 points lower, price 1 point lower, cost of sales 1 point higher. Stretch = volume 5 points higher, price 1 point higher, cost of sales 1 point lower, direct cost 2 points higher.</p>${cNote}</section>
  <section class="p w12" data-po="table"><h2>Plan ${YEAR} by profit centre</h2><p class="sub">${scope} · ${us.length} profit centre${us.length===1?"":"s"}</p>
    ${table("tPlanTbl",[{t:"Site · profit centre"},{t:"Base revenue",f:"planBase"},{t:"Plan revenue",f:"planRev"},{t:"Growth",f:"planGrowth"},{t:"Cost of sales",f:"planCogs"},{t:"Gross margin",f:"planGm"},{t:"GM %",f:"gmp"},{t:"Direct cost",f:"planOpex"},{t:"Contribution",f:"planContrib"},{t:"Contribution %",f:"planCp"}],pRows,pFoot)}</section>
  <section class="p w12" data-po="chart"><h2>Plan ${YEAR} month by month</h2><p class="sub">${scope} · each profit centre keeps the same monthly pattern as its base year</p>${phasing(T.planM, T.baseM)}
    <p class="note">Biggest month: ${MON[peak]} (${money(T.planM[peak])}). Quietest month: ${MON[low]} (${money(T.planM[low])}).</p></section>`;
  }

  // Update only the computed parts, so the box being typed in keeps focus.
  function refresh(){
    const vw = document.getElementById("view"); if(!vw) return;
    const tmp = document.createElement("div"); tmp.innerHTML = view();
    let swapped = 0;
    tmp.querySelectorAll("[data-po]").forEach(n=>{ const o = vw.querySelector(`[data-po="${n.dataset.po}"]`); if(o){ o.replaceWith(n); swapped++; } });
    if(!swapped) render();
    // keep each row's Edited/History marker in step
    const src = tmp.querySelectorAll("#tPlanDrv tbody tr"), dst = vw.querySelectorAll("#tPlanDrv tbody tr");
    dst.forEach((tr,i)=>{ const a = tr.lastElementChild, b = src[i] && src[i].lastElementChild; if(a&&b) a.innerHTML = b.innerHTML; });
    vw.querySelectorAll("[data-plan-scn]").forEach(b=>{ const on = (load("plan.scn")||"base")===b.dataset.planScn; b.setAttribute("aria-pressed", on?"true":"false"); b.style.borderColor = on ? "var(--accent)" : ""; });
  }

  function onEdit(e){
    const t = e.target.closest && e.target.closest("input[data-plan]"); if(!t) return;
    const v = parseFloat(t.value); if(!isFinite(v)) return;
    const u = units()[+t.dataset.plan]; if(!u) return;
    const b = base(u.s.id, u.pc), d = drivers(u.s.id, u.pc, b.def);
    const x = DRV.find(z=>z.k===t.dataset.pk); if(!x) return;
    d[x.k] = clamp(v, x.lo, x.hi);
    save(u.s.id, u.pc, d); store("plan.scn", "custom");
    refresh();
  }
  document.addEventListener("input", onEdit);
  document.addEventListener("change", onEdit);
  document.addEventListener("click", e=>{
    const s = e.target.closest("[data-plan-scn]");
    if(s){
      const sc = SCN[s.dataset.planScn]; if(!sc) return;
      units().forEach(u=>{ const b = base(u.s.id, u.pc);
        if(s.dataset.planScn==="base"){ store(key(u.s.id,u.pc), ""); return; }
        save(u.s.id, u.pc, {vol: r1(b.def.vol+sc.vol), price: r1(b.def.price+sc.price), cos: r1(clamp(b.def.cos+sc.cos,0,100)), dc: r1(b.def.dc+sc.dc)}); });
      store("plan.scn", s.dataset.planScn); render(); toast(sc.name+" scenario applied to "+units().length+" profit centres"); return;
    }
    if(e.target.closest("[data-plan-reset]")){
      D.sites.forEach(si=>si.pcs.forEach(pc=>store(key(si.id,pc), "")));
      store("plan.scn", "base"); render(); toast("Plan reset to history defaults");
    }
  });

  BI.add({
    id: "plan",
    label: "Plan 2027",
    formulas: {
      planBase: "Base revenue = Revenue over the last 12 months of actual figures",
      planVol: "Volume growth % = how much more you expect to sell next year. Default = yearly revenue trend (last 6 months vs the 6 before, squared to make a year), with the 3% price default taken out, kept between -10% and +30%",
      planPrice: "Price change % = average price rise next year. Default = 3%",
      planCos: "Cost of sales % = Cost of sales / Revenue. Default = base-year cost of sales / base-year revenue",
      planDc: "Direct cost growth % = change in direct operating cost. Default = yearly trend of direct cost (last 6 months vs the 6 before, squared), kept between -10% and +30%",
      planDef: "Source: History = defaults worked out from the base year; Edited = changed by you or by a scenario button",
      planRev: "Plan revenue = Base revenue x (1 + Volume growth) x (1 + Price change)",
      planGrowth: "Growth vs base = Plan revenue / Base revenue - 1",
      planCogs: "Plan cost of sales = Plan revenue x Cost of sales %",
      planGm: "Plan gross margin = Plan revenue - Plan cost of sales",
      planOpex: "Plan direct cost = Base-year direct cost x (1 + Direct cost growth)",
      planContrib: "Plan contribution = Plan gross margin - Plan direct cost",
      planCp: "Contribution % = Plan contribution / Plan revenue (pill: green 20% or more, amber 10% to 20%, red under 10%)",
      planPhase: "Plan for a month = Plan revenue x (that month's base-year revenue / Base revenue), worked out per profit centre and then added up"
    },
    render: view
  });
})();

/* module: retention.js */
// Members and retention tab. Demo member cohorts made from each site's orders with a small seeded generator (never random).
// Respects the site and profit-centre filters; with all sites the cohorts are added up. Demo data only.
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const N = 12; // months tracked per cohort (month 0..11)
  let cut = 20; // what-if: cut churn by this %
  { const v = +load("retCut"); if (load("retCut") !== null && isFinite(v) && v >= 0 && v <= 50) cut = v; }
  let last = null; // model from the last render, used by the slider

  // Small seeded generator keyed on the site id (same numbers every time).
  function prng(key){
    let h = 2166136261;
    for (let i = 0; i < key.length; i++){ h ^= key.charCodeAt(i); h = Math.imul(h, 16777619); }
    let a = h >>> 0;
    return () => { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  }

  // Per-site settings and cohort counts. The draws do not depend on filters, only the sizes do.
  function siteModel(s){
    const r = prng("retention-" + s.id);
    const churn = 0.06 + r()*0.06;        // base monthly churn 6% to 12%
    const perOrder = 2.5 + r()*2.5;       // members who sign up per order
    const share = 0.20 + r()*0.25;        // share of revenue that comes from members
    const exp = 0.004 + r()*0.012;        // monthly growth in spend per staying member
    const fx = facts(D.months).filter(f => f.site === s.id);
    const sizes = [], counts = [];
    D.months.forEach((m, i) => {
      const orders = sum(fx.filter(f => f.m === m), f => f.orders);
      const size = Math.round(fin(orders * perOrder));
      sizes.push(size);
      const tilt = 0.85 + r()*0.3;          // some cohorts stay better than others
      const row = []; let left = size;
      for (let k = 0; k < N; k++){
        const noise = 0.9 + r()*0.2;
        if (k > 0){ const c = Math.min(0.5, churn*tilt*noise*(k === 1 ? 1.4 : 1)); left = left*(1 - c); }
        row.push(k <= N - 1 - i ? Math.round(left) : null); // only months that have happened
      }
      counts.push(row);
    });
    const lastM = D.months[D.months.length - 1];
    const memberRev = fin(share * sum(fx.filter(f => f.m === lastM), f => f.rev));
    return {s, churn, perOrder, share, exp, sizes, counts, memberRev};
  }

  // Add site models together and work out the measures.
  function model(){
    const sites = D.sites.filter(s => st.site === "all" || s.id === st.site);
    const per = sites.map(siteModel);
    const sizes = D.months.map((m, i) => sum(per, p => p.sizes[i]));
    const counts = D.months.map((m, i) => Array.from({length: N}, (_, k) => k <= N - 1 - i ? sum(per, p => p.counts[i][k] || 0) : null));
    // revenue by cohort and age (members x revenue per member x spend growth), added across sites
    const revAt = (i, k) => sum(per, p => { const a = activeNow(p.counts); const arpm = a > 0 ? p.memberRev / a : 0; return (p.counts[i][k] || 0) * arpm * Math.pow(1 + p.exp, k); });
    const active = activeNow(counts);
    let num = 0, den = 0; // weighted churn from every observed month-to-month step
    counts.forEach(row => { for (let k = 0; k < N - 1; k++){ if (row[k + 1] != null && row[k] > 0){ den += row[k]; num += row[k] - row[k + 1]; } } });
    const churn = den > 0 ? Math.max(0.001, fin(num / den)) : 0;
    const curve = Array.from({length: N}, (_, k) => {
      let a = 0, b = 0; counts.forEach((row, i) => { if (row[k] != null){ a += row[k]; b += sizes[i]; } });
      return b > 0 ? fin(a / b) : 0;
    });
    const r0 = revAt(0, 0), r11 = revAt(0, N - 1);
    const nrr = r0 > 0 ? fin(r11 / r0) : 0;
    const memberRev = sum(per, p => p.memberRev);
    const arpm = active > 0 ? fin(memberRev / active) : 0;
    const gmp = fin(agg(facts()).gmp);
    const life = churn > 0 ? fin(1 / churn) : 0;
    const ltv = fin(arpm * life * gmp);
    const joins = Math.round(fin(sum(sizes.slice(-3)) / 3));
    return {per, sizes, counts, active, churn, curve, nrr, memberRev, arpm, gmp, life, ltv, joins, total: sum(sizes)};
  }
  function activeNow(counts){ return sum(counts.map(row => { const v = row.filter(x => x != null); return v.length ? v[v.length - 1] : 0; })); }

  // 12-month projection: members next month = members x (1 - churn) + new sign-ups.
  function project(mo, churn){
    const out = []; let a = mo.active;
    for (let t = 1; t <= 12; t++){ a = a*(1 - churn) + mo.joins; out.push(fin(a)); }
    return out;
  }
  function whatIf(mo){
    const c2 = mo.churn*(1 - cut/100);
    const base = project(mo, mo.churn), alt = project(mo, c2);
    const extra = fin(alt[11] - base[11]);
    const extraRev = fin(sum(alt.map((v, i) => (v - base[i])*mo.arpm)));
    const extraGm = fin(extraRev*mo.gmp);
    return {c2, base, alt, extra, extraRev, extraGm};
  }

  // Retention curve: % of members still active by month since joining, drawn to scale (0 to 100%).
  function curveSvg(vals){
    const W=640,H=220,L=48,R=12,T=12,B=30,w=W-L-R,h=H-T-B;
    const x = i => L + i*w/(N - 1), y = v => T + h - v*h;
    let g = "";
    for (let i = 0; i <= 4; i++){ const v = i/4; g += `<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${(v*100).toFixed(0)}%</text>`; }
    vals.forEach((v, i) => g += `<text x="${x(i)}" y="${H-12}" text-anchor="middle">M${i}</text>`);
    g += `<polygon points="${L},${y(0)} ${vals.map((v, i) => x(i)+","+y(v)).join(" ")} ${x(N-1)},${y(0)}" fill="color-mix(in srgb,var(--c1) 14%,transparent)"/>`;
    g += `<polyline points="${vals.map((v, i) => x(i)+","+y(v)).join(" ")}" fill="none" stroke="var(--c1)" stroke-width="2"/>`;
    vals.forEach((v, i) => g += `<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="var(--c1)"><title>Month ${i}: ${pct(v)} still active</title></circle>`);
    return `<svg id="retCurve" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Average share of members still active by month since joining">${g}</svg><div class="legend"><span><i data-s="background:var(--c1)"></i>Average % still active (all cohorts)</span></div>`;
  }

  // Projection chart for the what-if: members now vs with churn cut.
  function projSvg(mo, wi){
    const W=400,H=190,L=50,R=10,T=10,B=26,w=W-L-R,h=H-T-B;
    const all = [mo.active, ...wi.base, ...wi.alt];
    const mx = niceMax(Math.max(1, ...all)*1.05);
    const x = i => L + i*w/12, y = v => T + h - v/mx*h;
    let g = "";
    for (let i = 0; i <= 4; i++){ const v = mx*i/4; g += `<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${Math.round(v).toLocaleString("en-US")}</text>`; }
    for (let i = 0; i <= 12; i += 2) g += `<text x="${x(i)}" y="${H-10}" text-anchor="middle">${i === 0 ? "Now" : "+" + i}</text>`;
    const line = (vals, c, dash) => `<polyline points="${[mo.active, ...vals].map((v, i) => x(i)+","+y(v)).join(" ")}" fill="none" stroke="${c}" stroke-width="2"${dash ? ' stroke-dasharray="5 3"' : ""}/>`;
    g += line(wi.base, "var(--c6)", true) + line(wi.alt, "var(--c2)", false);
    return `<svg id="retProj" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Active members over the next 12 months, as now and with churn cut">${g}</svg><div class="legend"><span><i data-s="background:var(--c6)"></i>Churn as now</span><span><i data-s="background:var(--c2)"></i>Churn cut by ${cut}%</span></div>`;
  }

  function wiHtml(mo){
    const wi = whatIf(mo);
    return `<div class="tiles" data-s="margin:10px 0;grid-template-columns:repeat(auto-fit,minmax(110px,1fr))">
      <div class="tile" title="${esc(FX.retWiChurn)}"><span class="k">New monthly churn</span><span class="v">${pct(wi.c2)}</span><span class="d flat">now ${pct(mo.churn)}</span></div>
      <div class="tile" title="${esc(FX.retWiMembers)}"><span class="k">Extra members in 12 months</span><span class="v" id="retExtra">${Math.round(wi.extra).toLocaleString("en-US")}</span><span class="d up">${Math.round(wi.alt[11]).toLocaleString("en-US")} vs ${Math.round(wi.base[11]).toLocaleString("en-US")}</span></div>
      <div class="tile" title="${esc(FX.retWiRev)}"><span class="k">Extra revenue, 12 months</span><span class="v">${money(wi.extraRev)}</span><span class="d">${money(wi.extraGm)} gross margin</span></div>
    </div>${projSvg(mo, wi)}
    <p class="note">Assumes ${mo.joins.toLocaleString("en-US")} new members a month (average of the last 3 cohorts) and ${money(mo.arpm)} revenue per member per month.</p>`;
  }

  document.addEventListener("input", e => {
    if (!e.target || e.target.id !== "retCut") return;
    cut = Math.min(50, Math.max(0, Math.round(fin(+e.target.value))));
    store("retCut", String(cut));
    const lb = document.getElementById("retCutLbl"); if (lb) lb.textContent = cut + "%";
    const box = document.getElementById("retWi"); if (box && last) box.innerHTML = wiHtml(last);
  });

  const churnPill = c => c <= 0.07 ? "g" : c <= 0.09 ? "a" : "r";
  const shade = v => `color-mix(in srgb,var(--accent) ${Math.round(6 + 49*Math.min(1, Math.max(0, v)))}%,transparent)`;
  const n0 = v => Math.round(fin(v)).toLocaleString("en-US");

  BI.add({
    id: "retention",
    label: "Retention",
    formulas: {
      retCohort: "Cohort = members who signed up in the same month (demo: orders that month x members per order, fixed per site)",
      retActive: "Active members now = for each cohort, members still active in the latest month; added up",
      retChurn: "Monthly churn = members lost from one month to the next / members at the start of that month, over every cohort and month",
      retNrr: "Net revenue retention (12 months) = revenue now from the oldest cohort / that cohort's revenue in its first month (keeps upgrades, loses leavers)",
      retLife: "Average lifetime (months) = 1 / Monthly churn",
      retArpm: "Revenue per member per month = member revenue in the latest month / Active members now",
      retLtv: "Lifetime value = Revenue per member per month x Average lifetime x Gross margin %",
      retPct: "% retained = members still active in that month / members who signed up in the cohort",
      retCurve: "Retention curve = for each month since joining, members still active / members who joined, over all cohorts that have reached that month",
      retWiChurn: "New monthly churn = Monthly churn x (1 - cut %)",
      retWiMembers: "Extra members = members in 12 months with churn cut - members in 12 months as now; each month: members x (1 - churn) + new members",
      retWiRev: "Extra revenue = sum over 12 months of (extra members that month x Revenue per member per month)"
    },
    render: () => {
      const mo = model(); last = mo;
      const scope = (st.site === "all" ? "All sites on this side, added up" : esc(siteName(st.site))) + " · " + (st.pc === "all" ? "all profit centres" : esc(st.pc));
      if (!(mo.total > 0)){
        return `<section class="p w12"><h2>Members and retention</h2><p class="sub">${scope}</p><p class="note">No members to show for this filter yet. Try another site or profit centre.</p></section>`;
      }
      const cp = churnPill(mo.churn);
      const tiles = [
        ["Active members now", n0(mo.active), `<span class="flat">${n0(mo.total)} joined in 12 months</span>`, "retActive"],
        ["Monthly churn", pct(mo.churn), `<span class="pill ${cp}">${ragTxt[cp]}</span> goal 7% or less`, "retChurn"],
        ["Net revenue retention", pct(mo.nrr), `<span class="flat">oldest cohort, 12 months</span>`, "retNrr"],
        ["Average lifetime", mo.life.toFixed(1) + " months", `<span class="flat">= 1 / monthly churn</span>`, "retLife"],
        ["Revenue per member", money(mo.arpm), `<span class="flat">per month</span>`, "retArpm"],
        ["Lifetime value", money(mo.ltv), `<span class="flat">after ${pct(mo.gmp)} gross margin</span>`, "retLtv"]
      ];
      const head = [{t: "Cohort", f: "retCohort"}, {t: "Joined", f: "retCohort"}].concat(Array.from({length: N}, (_, k) => ({t: "M" + k, f: "retPct"})));
      const rows = D.months.map((m, i) => {
        const sz = mo.sizes[i];
        return [`<span data-drill="month:${esc(m)}" title="Click to pick this month">${esc(m)}</span>`, n0(sz)].concat(mo.counts[i].map((c, k) => {
          if (c == null) return `<span class="note">·</span>`;
          const v = sz > 0 ? c/sz : 0;
          return `<span data-s="display:block;padding:1px 4px;border-radius:3px;background:${shade(v)};color:var(--ink)" title="${esc(m)}, month ${k}: ${n0(c)} of ${n0(sz)} still active">${(v*100).toFixed(0)}%</span>`;
        }));
      });
      const foot = ["Average", n0(mo.total/N)].concat(mo.curve.map(v => (v*100).toFixed(0) + "%"));

      let siteTbl = "";
      if (mo.per.length > 1){
        const sr = mo.per.map(p => {
          const a = activeNow(p.counts); let nn = 0, dd = 0;
          p.counts.forEach(row => { for (let k = 0; k < N - 1; k++){ if (row[k + 1] != null && row[k] > 0){ dd += row[k]; nn += row[k] - row[k + 1]; } } });
          const c = dd > 0 ? Math.max(0.001, nn/dd) : 0; const arpm = a > 0 ? p.memberRev/a : 0;
          const gm = fin(agg(facts().filter(f => f.site === p.s.id)).gmp);
          return {p, a, c, arpm, ltv: fin(arpm*(c > 0 ? 1/c : 0)*gm)};
        }).sort((x, y) => y.c - x.c);
        siteTbl = `<section class="p w12"><h2>Which site keeps members best</h2><p class="sub">Highest churn first · click a site to look at it alone</p>${table("tRetSites",
          [{t: "Site"}, {t: "Active now", f: "retActive"}, {t: "Monthly churn", f: "retChurn"}, {t: "Lifetime", f: "retLife"}, {t: "Revenue per member", f: "retArpm"}, {t: "Lifetime value", f: "retLtv"}, {t: "Status", f: "retChurn"}],
          sr.map(x => [`<span data-drill="site:${esc(x.p.s.id)}" title="Click to filter to this site">${esc(x.p.s.name)}</span>`, n0(x.a), pct(x.c), (x.c > 0 ? 1/x.c : 0).toFixed(1) + " mo", money(x.arpm), money(x.ltv), `<span class="pill ${churnPill(x.c)}">${ragTxt[churnPill(x.c)]}</span>`]),
          ["Total", n0(mo.active), pct(mo.churn), mo.life.toFixed(1) + " mo", money(mo.arpm), money(mo.ltv), ""])}</section>`;
      }

      return `<div class="tiles t3">${tiles.map(t => `<div class="tile" title="${esc(FX[t[3]] || "")}"><span class="k">${t[0]}</span><span class="v">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>
  <section class="p w8"><h2>How long members stay</h2><p class="sub">${scope} · average of all monthly cohorts</p>${curveSvg(mo.curve)}
    <p class="note">After 3 months ${pct(mo.curve[3])} are still with you; after 11 months ${pct(mo.curve[N - 1])}.</p></section>
  <section class="p w4"><h2>What if churn drops?</h2><p class="sub">Move the slider to cut monthly churn</p>
    <label class="row" for="retCut" data-s="gap:8px"><span>Cut churn by</span><input id="retCut" type="range" min="0" max="50" step="5" value="${cut}" data-s="flex:1;min-width:0"><b id="retCutLbl">${cut}%</b></label>
    <div id="retWi">${wiHtml(mo)}</div></section>
  <section class="p w12"><h2>Cohort retention</h2><p class="sub">${scope} · each row is a sign-up month; each column is months since joining; darker = more members kept</p>${table("tRetCohort", head, rows, foot)}</section>
  ${siteTbl}
  <section class="p w12"><h2>How these numbers are made</h2><p class="note">Demo member data: each site's monthly orders are turned into sign-up cohorts with a fixed seed, so the numbers stay the same every time. Monthly churn here is ${pct(mo.churn)}; lifetime value uses gross margin from the selected period. Country filter does not apply to members.</p></section>`;
    }
  });
})();

/* module: suppliers.js */
// Suppliers and spend tab (procurement). Spend comes from cost of sales in the facts, split over
// 12 demo suppliers per site with a small seeded random generator keyed on the site id. Demo data only.
(function(){
  const fin = v => (typeof v === "number" && isFinite(v)) ? v : 0;
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, fin(v)));
  const CATS = ["Raw materials", "Packaging", "Logistics", "Services", "Equipment"];
  const CAT_C = ["var(--c1)", "var(--c2)", "var(--c3)", "var(--c4)", "var(--c5)"];

  // Tiny seeded generator (mulberry32) with a string hash, so every site always gets the same suppliers.
  function seed(str){ let h = 2166136261; for(let i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
  function rng(str){ let a = seed(str); return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }

  const cache = {};
  function roster(site){
    if(cache[site.id]) return cache[site.id];
    const r = rng("suppliers:" + site.id);
    const list = [];
    for(let i=0;i<12;i++){
      const w = (0.6 + r()*0.8) / Math.pow(i+1, 1.15);       // a few big suppliers, a long tail
      const cat = i < 5 ? (i + Math.floor(r()*5)) % 5 : Math.floor(r()*5);
      list.push({
        site, n: i+1, name: "Demo Supplier " + String(i+1).padStart(2, "0"),
        w, cat,
        ontime: Math.round((80 + r()*19) * 10) / 10,          // % of deliveries on the promised day
        quality: Math.round((86 + r()*13.5) * 10) / 10,        // % of items accepted without a fault
        reply: Math.round(10 + r()*230),                       // minutes to answer a request
        pidx: Math.round((92 + r()*20) * 10) / 10,             // price vs market, 100 = at market
        contract: r() < 0.72,                                  // is there a signed price agreement
        pay: Math.round(15 + r()*45)                           // payment days agreed
      });
    }
    const tw = sum(list, s=>s.w) || 1;
    list.forEach(s=>{ s.share = s.w / tw; });
    cache[site.id] = list;
    return list;
  }

  const speedScore = m => clamp(100 * (240 - m) / 225, 0, 100);
  const priceScore = p => clamp(100 - (p - 90) * 5, 0, 100);
  const overall = s => fin(0.4*s.ontime + 0.3*s.quality + 0.2*speedScore(s.reply) + 0.1*priceScore(s.pidx));
  const scorePill = v => v >= 85 ? "g" : v >= 70 ? "a" : "r";
  const pillTxt = { g: "Strong", a: "Watch", r: "Act now" };

  // All suppliers in scope with spend for the chosen months.
  function build(){
    const ms = months();
    const multi = st.site === "all";
    const out = [];
    D.sites.filter(s=>multi || s.id===st.site).forEach(site=>{
      const spend = fin(sum(D.facts.filter(f=>f.site===site.id && (st.pc==="all"||f.pc===st.pc) && ms.includes(f.m)), f=>f.cogs));
      roster(site).forEach(s=>{
        const sp = fin(spend * s.share);
        const score = overall(s);
        out.push(Object.assign({}, s, {
          label: s.name + (multi ? " (" + site.code + ")" : ""),
          spend: sp, score,
          save: s.pidx > 100 ? fin(sp * (s.pidx - 100) / 100) : 0
        }));
      });
    });
    out.sort((a,b)=>(b.spend-a.spend) || (a.label < b.label ? -1 : 1));
    const total = fin(sum(out, s=>s.spend));
    let cum = 0;
    out.forEach(s=>{
      const before = cum;
      cum += s.spend;
      s.cum = total > 0 ? fin(cum/total) : 0;
      s.abc = total <= 0 ? "C" : before/total < 0.8 ? "A" : before/total < 0.95 ? "B" : "C";
    });
    return { list: out, total, ms, multi };
  }

  // Pareto chart: bars = supplier spend, line = cumulative share, dashed guides at 80% and 95%.
  function pareto(list, total){
    const items = list.slice(0, 24);
    if(!items.length || total <= 0) return `<p class="note">No spend in this view. Try a longer period or another profit centre.</p>`;
    const W=640, H=240, L=54, R=40, T=12, B=30, w=W-L-R, h=H-T-B;
    const mx = niceMax(Math.max(...items.map(s=>s.spend)) * 1.05);
    const bw = w / items.length;
    const y = v => T + h - v/mx*h, yp = p => T + h - p*h;
    const abcC = { A: "var(--c1)", B: "var(--c4)", C: "var(--c6)" };
    let g = "";
    for(let i=0;i<=4;i++){ const v = mx*i/4; g += `<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${money(v)}</text>`; }
    [0.8, 0.95].forEach(p=>{ g += `<line x1="${L}" x2="${W-R}" y1="${yp(p)}" y2="${yp(p)}" stroke="var(--mut)" stroke-dasharray="4 3"/><text x="${W-R+4}" y="${yp(p)+4}">${Math.round(p*100)}%</text>`; });
    g += `<text x="${W-R+4}" y="${yp(1)+4}">100%</text>`;
    items.forEach((s,i)=>{
      const x = L + i*bw;
      g += `<rect x="${x+bw*.15}" y="${y(s.spend)}" width="${bw*.7}" height="${T+h-y(s.spend)}" fill="${abcC[s.abc]}" rx="2"${s.site?` data-drill="site:${esc(s.site.id)}" data-s="cursor:pointer"`:""}><title>${esc(s.label)}: ${money(s.spend)} · class ${s.abc} · ${pct(s.cum)} cumulative</title></rect>`;
      g += `<text x="${x+bw/2}" y="${H-12}" text-anchor="middle">${i+1}</text>`;
    });
    const pts = items.map((s,i)=>`${L+i*bw+bw/2},${yp(s.cum)}`).join(" ");
    g += `<polyline points="${pts}" fill="none" stroke="var(--c3)" stroke-width="2"/>`;
    items.forEach((s,i)=>{ g += `<circle cx="${L+i*bw+bw/2}" cy="${yp(s.cum)}" r="2.6" fill="var(--c3)"><title>Cumulative after ${esc(s.label)}: ${pct(s.cum)}</title></circle>`; });
    return `<svg id="tSupParetoSvg" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Supplier spend from largest to smallest with cumulative share">${g}</svg>
      <div class="legend"><span><i data-s="background:var(--c1)"></i>A: first 80% of spend</span><span><i data-s="background:var(--c4)"></i>B: next 15%</span><span><i data-s="background:var(--c6)"></i>C: last 5%</span><span><i data-s="background:var(--c3)"></i>Cumulative share</span></div>
      ${list.length > items.length ? `<p class="note">Showing the ${items.length} largest of ${list.length} suppliers. Numbers under the bars are ranks.</p>` : `<p class="note">Numbers under the bars are ranks in the table below.</p>`}`;
  }

  function getMin(){
    if(typeof st.supMin !== "number" || !isFinite(st.supMin)){
      const v = +load("supMin");
      st.supMin = isFinite(v) ? clamp(v, 0, 100) : 0;
    }
    return st.supMin;
  }

  BI.add({
    id: "suppliers",
    label: "Suppliers",
    formulas: {
      supSpend: "Spend = Cost of sales in the period (by site and profit centre), split over 12 demo suppliers per site by a fixed share",
      supTop3: "Top-3 share = Spend with the 3 largest suppliers / Total spend",
      supContract: "Under contract % = Spend with suppliers that have a signed price agreement / Total spend",
      supPay: "Average payment days = sum of (Supplier spend x Payment days) / Total spend",
      supCum: "Cumulative share = Spend of this supplier and every larger one / Total spend",
      supAbc: "ABC class: A = suppliers that make up the first 80% of spend; B = the next 15%; C = the last 5%",
      supCat: "Category spend = sum of supplier spend in that category",
      supOnTime: "On-time % = deliveries on the promised day / all deliveries",
      supQuality: "Quality % = items accepted without a fault / all items received",
      supReply: "Reply minutes = average time the supplier takes to answer a request",
      supSpeed: "Speed score = 100 x (240 - Reply minutes) / 225, kept between 0 and 100",
      supPidx: "Price index = Supplier price / Market price x 100 (100 = at market, above 100 = we pay more)",
      supPriceScore: "Price score = 100 - (Price index - 90) x 5, kept between 0 and 100",
      supScore: "Overall score = 0.4 x On-time % + 0.3 x Quality % + 0.2 x Speed score + 0.1 x Price score",
      supPill: "Score status: Strong 85 or more; Watch 70 to 84.9; Act now below 70",
      supMav: "Maverick spend = Spend with suppliers that have no signed price agreement (off contract)",
      supSave: "Savings opportunity = Spend x (Price index - 100) / 100, only for suppliers with a price index above 100"
    },
    render: () => {
      const { list, total, ms, multi } = build();
      const min = getMin();
      const scope = (multi ? "All sites on this side" : esc(siteName(st.site))) + " · " + (st.pc==="all" ? "all profit centres" : esc(st.pc)) + " · last " + ms.length + " months";
      const top3 = sum(list.slice(0,3), s=>s.spend);
      const onC = sum(list.filter(s=>s.contract), s=>s.spend);
      const mav = total - onC;
      const payD = total > 0 ? fin(sum(list, s=>s.spend*s.pay)/total) : 0;
      const saveTot = fin(sum(list, s=>s.save));
      const sh = (a) => total > 0 ? fin(a/total) : 0;

      const tiles = [
        ["Total spend", money(total), `${list.length} suppliers`, "supSpend"],
        ["Top-3 supplier share", pct(sh(top3)), `<span class="${sh(top3)>0.6?"down":"flat"}">${sh(top3)>0.6?"High reliance on a few":"Spread is fine"}</span>`, "supTop3"],
        ["Spend under contract", pct(sh(onC)), `<span class="pill ${sh(onC)>=0.8?"g":sh(onC)>=0.65?"a":"r"}">${sh(onC)>=0.8?"On track":sh(onC)>=0.65?"Watch":"Act now"}</span> goal 80%`, "supContract"],
        ["Average payment days", payD.toFixed(0) + " days", "weighted by spend", "supPay"],
        ["Off-contract spend", money(mav), `${list.filter(s=>!s.contract).length} suppliers with no agreement`, "supMav"],
        ["Savings opportunity", money(saveTot), `${list.filter(s=>s.save>0).length} suppliers above market price`, "supSave"]
      ];
      const tileHtml = `<div class="tiles t3">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]]||"")}"><span class="k">${t[0]}</span><span class="v">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>`;

      if(total <= 0){
        return tileHtml + `<section class="p w12"><h2>Suppliers and spend</h2><p class="sub">${scope}</p><p class="note">There is no spend for this choice of filters yet. Try "All profit centres" or a longer period.</p></section>`;
      }

      // Category bars
      const cats = CATS.map((k,i)=>({ k, v: fin(sum(list.filter(s=>s.cat===i), s=>s.spend)), c: CAT_C[i] })).sort((a,b)=>b.v-a.v);
      const catRows = cats.map(c=>[esc(c.k), money(c.v), pct(sh(c.v)), String(list.filter(s=>CATS[s.cat]===c.k).length)]);

      // ABC summary
      const abc = ["A","B","C"].map(k=>{ const r = list.filter(s=>s.abc===k); return { k, n: r.length, v: sum(r, s=>s.spend) }; });
      const abcTxt = { A: "Manage closely: review prices and terms each quarter", B: "Check twice a year", C: "Keep simple: group orders or move to fewer suppliers" };

      // Scorecard (filtered by the slider)
      const nameCell = s => multi ? `<span data-drill="site:${esc(s.site.id)}" data-s="cursor:pointer" title="Click to filter to this site">${esc(s.label)}</span>` : esc(s.label);
      const shown = list.filter(s=>s.score >= min);
      const scRows = shown.length ? shown.map(s=>[
        String(list.indexOf(s)+1), nameCell(s), esc(CATS[s.cat]), money(s.spend), s.abc,
        s.ontime.toFixed(1)+"%", s.quality.toFixed(1)+"%", String(s.reply), s.pidx.toFixed(1),
        s.score.toFixed(1), `<span class="pill ${scorePill(s.score)}">${pillTxt[scorePill(s.score)]}</span>`,
        s.contract ? "Yes" : `<span class="pill r" title="${esc(FX.supMav)}">Off contract</span>`
      ]) : [[`<span class="note">No supplier scores ${min} or more. Move the slider to the left.</span>`,"","","","","","","","","","",""]];
      const avgScore = shown.length ? fin(sum(shown, s=>s.score*s.spend) / (sum(shown, s=>s.spend) || 1)) : 0;
      const scFoot = ["", shown.length + " of " + list.length, "", money(sum(shown, s=>s.spend)), "", "", "", "", "", avgScore.toFixed(1), "spend-weighted", ""];

      // Maverick and savings tables
      const mavList = list.filter(s=>!s.contract);
      const mavRows = mavList.length ? mavList.map(s=>[nameCell(s), esc(CATS[s.cat]), money(s.spend), pct(sh(s.spend)), s.pidx.toFixed(1), s.pay + " days"])
        : [[`<span class="note">Every supplier in this view has a signed agreement.</span>`,"","","","",""]];
      const saveList = list.filter(s=>s.save > 0).sort((a,b)=>b.save-a.save);
      const saveRows = saveList.length ? saveList.map(s=>[nameCell(s), money(s.spend), s.pidx.toFixed(1), money(s.save), s.contract ? "Ask for a price review" : "Put on contract at market price"])
        : [[`<span class="note">No supplier is above market price in this view.</span>`,"","","",""]];

      return tileHtml + `
  <section class="p w8"><h2>Which suppliers take most of the spend (Pareto)</h2><p class="sub">${scope} · largest first</p>${pareto(list, total)}</section>
  <section class="p w4"><h2>Spend by category</h2><p class="sub">${scope}</p>${hbars(cats, money)}
    <p class="note" data-s="margin-top:10px">${abc.map(a=>`<b>${a.k}</b>: ${a.n} suppliers, ${money(a.v)} (${pct(sh(a.v))}). ${abcTxt[a.k]}.`).join("<br>")}</p></section>
  <section class="p w12"><h2>Supplier scorecard</h2><p class="sub">${scope} · hover a column title to see how it is worked out</p>
    <div class="row" data-s="margin-bottom:8px"><label for="supMin" class="note">Show suppliers with a score of at least <b id="supMinV">${min}</b></label><input id="supMin" type="range" min="0" max="100" step="5" value="${min}" data-s="width:100%;max-width:320px"></div>
    ${table("tSupScore", [{t:"Rank"},{t:"Supplier"},{t:"Category",f:"supCat"},{t:"Spend",f:"supSpend"},{t:"ABC",f:"supAbc"},{t:"On-time",f:"supOnTime"},{t:"Quality",f:"supQuality"},{t:"Reply min",f:"supReply"},{t:"Price index",f:"supPidx"},{t:"Score",f:"supScore"},{t:"Status",f:"supPill"},{t:"Contract",f:"supMav"}], scRows, scFoot)}</section>
  <section class="p w12"><h2>Spend by category</h2><p class="sub">${scope}</p>${table("tSupCat", [{t:"Category"},{t:"Spend",f:"supCat"},{t:"Share of spend",f:"supCat"},{t:"Suppliers"}], catRows, ["Total", money(total), pct(1), String(list.length)])}</section>
  <section class="p w12"><h2>Maverick spend: buying without a contract</h2><p class="sub">${scope} · ${money(mav)} (${pct(sh(mav))} of spend) has no signed price agreement</p>${table("tSupMav", [{t:"Supplier"},{t:"Category",f:"supCat"},{t:"Spend",f:"supMav"},{t:"Share of spend",f:"supSpend"},{t:"Price index",f:"supPidx"},{t:"Payment days",f:"supPay"}], mavRows, mavList.length ? ["Total", "", money(mav), pct(sh(mav)), "", ""] : null)}</section>
  <section class="p w12"><h2>Savings opportunity</h2><p class="sub">${scope} · what we could save by paying the market price</p>${table("tSupSave", [{t:"Supplier"},{t:"Spend",f:"supSpend"},{t:"Price index",f:"supPidx"},{t:"Savings",f:"supSave"},{t:"Next step"}], saveRows, saveList.length ? ["Total", money(sum(saveList, s=>s.spend)), "", money(saveTot), ""] : null)}</section>`;
    }
  });

  document.addEventListener("input", e=>{
    if(e.target.id !== "supMin") return;
    st.supMin = clamp(+e.target.value, 0, 100);
    store("supMin", String(st.supMin));
    render();
    const n = document.getElementById("supMin"); if(n) n.focus();
  });
})();

BI.mods.forEach(m=>{const f=document.querySelector('#tabs a[data-v="alerts"]');const a=document.createElement("a");a.href="#"+m.id;a.dataset.v=m.id;a.textContent=m.label;f.parentNode.insertBefore(a,f);});

/* ---------- wiring ---------- */
function render(){
  const v=(location.hash||"#overview").slice(1); const view=V[v]?v:"overview";
  document.querySelectorAll("#tabs a").forEach(a=>{if(a.dataset.v===view)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current")});
  $("#view").innerHTML=chips()+V[view]();
  const n=runAlerts().length; $("#alertN").textContent=n||""; $("#alertN").hidden=!n;
  const pr=$("#prob"); if(pr) pr.addEventListener("input",e=>{st.prob=+e.target.value;render()});
}
function drill(spec){
  let tab=null;
  spec.split("|").forEach(p=>{const i=p.indexOf(":");const k=p.slice(0,i),v=p.slice(i+1);
    if(k==="tab")tab=v;
    else if(k==="site"){st.site=v;$("#fSite").value=v;fillPc();}
    else if(k==="pc"){st.pc=v;$("#fPc").value=v;}
    else if(k==="country"){st.country=(st.country===v?"all":v);$("#fCountry").value=st.country;}
    else st[k]=(st[k]===v?"":v);});
  if(tab&&location.hash!=="#"+tab)history.replaceState(null,"","#"+tab);
  render();
  const mp=$("#monthPanel"); if(mp&&spec.startsWith("month:"))mp.scrollIntoView({block:"nearest"});
}
function tableCsv(t){return [...t.querySelectorAll("tr")].map(r=>[...r.children].map(c=>'"'+(c.querySelector("input")?c.querySelector("input").value:c.innerText).replace(/"/g,'""')+'"').join(",")).join("\n")}
function copyText(txt,msg){Promise.resolve().then(()=>navigator.clipboard.writeText(txt)).then(()=>toast(msg),()=>{const ta=document.createElement("textarea");ta.value=txt;document.body.append(ta);ta.select();try{document.execCommand("copy")}catch(x){}ta.remove();toast(msg)});}
document.addEventListener("click",e=>{
  const dr=e.target.closest("[data-drill]"); if(dr){drill(dr.dataset.drill);return;}
  const cl=e.target.closest("[data-clear]"); if(cl){const k=cl.dataset.clear;
    if(k==="all"){Object.assign(st,{site:"all",pc:"all",country:"all",stage:"",seg:"",month:""});$("#fSite").value="all";$("#fCountry").value="all";fillPc();}
    else if(["site","pc","country"].includes(k)){st[k]="all";$({site:"#fSite",pc:"#fPc",country:"#fCountry"}[k]).value="all";if(k==="site")fillPc();}
    else st[k]="";
    render();return;}
  const sv=e.target.closest("[data-save]"); if(sv){const csv=tableCsv(document.getElementById(sv.dataset.save));
    try{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download=sv.dataset.save+".csv";document.body.append(a);a.click();a.remove();toast("CSV file saved (if your browser allows downloads here)")}catch(x){copyText(csv,"Saving is blocked here, so the table was copied instead")}return;}
  if(e.target.closest("[data-reset-thr]")){RULES.forEach(r=>store("thr."+r.id,""));render();toast("Limits reset");return;}
  const b=e.target.closest("[data-copy]");if(!b)return;
  copyText(tableCsv(document.getElementById(b.dataset.copy)),"Table copied as CSV");});
document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches("div[data-drill]")){e.preventDefault();drill(e.target.dataset.drill)}});
document.addEventListener("change",e=>{const t=e.target.closest("[data-thr]");if(!t)return;store("thr."+t.dataset.thr,t.value);const id=t.id;render();const n=document.getElementById(id);if(n)n.focus();});
$("#exportView").addEventListener("click",()=>{const parts=[...document.querySelectorAll("#view section")].filter(s=>s.querySelector("table")).map(s=>"# "+(s.querySelector("h2")||{}).innerText+"\n"+[...s.querySelectorAll("table")].map(tableCsv).join("\n\n"));copyText(parts.join("\n\n"),"Whole tab copied as CSV ("+parts.length+" tables)")});
["fSite","fPc","fCountry","fPer"].forEach(id=>$("#"+id).addEventListener("change",e=>{
  const k={fSite:"site",fPc:"pc",fCountry:"country",fPer:"per"}[id]; st[k]=k==="per"?+e.target.value:e.target.value; if(k==="site")fillPc(); store(k,st[k]); render();}));
function setTheme(t){document.documentElement.setAttribute("data-theme",t);$("#theme").textContent=t==="dark"?"Light":"Dark";store("theme",t)}
$("#theme").addEventListener("click",()=>setTheme(document.documentElement.getAttribute("data-theme")==="dark"?"light":"dark"));
window.addEventListener("hashchange",render);
$("#tabs").addEventListener("click",e=>{const a=e.target.closest("a[data-v]");if(!a)return;e.preventDefault();if(location.hash!=="#"+a.dataset.v){history.replaceState(null,"","#"+a.dataset.v)}render()});
fillFilters();
["site","country"].forEach(k=>{const v=load(k);if(v&&[...$(k==="site"?"#fSite":"#fCountry").options].some(o=>o.value===v)){st[k]=v;$(k==="site"?"#fSite":"#fCountry").value=v}});
fillPc();
setTheme(load("theme")||"light");
render();
